void test_pe_resources() {
    const auto image = transmute::PeImage::parse(icon_resource_executable());
    const auto group = image.find_resource(14, u"APPICON");
    const auto numeric_group = image.find_resource(14, std::uint16_t{100}, 1033);
    const auto icon = image.find_resource(3, std::uint16_t{1});
    expect(group && group->size() == 20 &&
               (*group)[2] == 1 && (*group)[4] == 1 &&
               (*group)[6] == 1 && (*group)[7] == 1 &&
               (*group)[14] == 48 && (*group)[18] == 1,
           "named PE icon group lookup failed");
    expect(numeric_group && numeric_group->data() == group->data(),
           "numeric PE icon group lookup failed");
    expect(icon && icon->size() == 48 &&
               (*icon)[0] == 40 && (*icon)[4] == 1 && (*icon)[8] == 2 &&
               (*icon)[0x2a] == 0xff && (*icon)[0x2b] == 0xff,
           "PE icon payload lookup failed");
    expect(!image.find_resource(14, u"MISSING") &&
               !image.find_resource(14, std::uint16_t{101}) &&
               !image.find_resource(3, std::uint16_t{1}, 1041) &&
               !image.find_resource(15, std::uint16_t{1}) &&
               !transmute::PeImage::parse(executable({0xd65f03c0}))
                    .find_resource(14, u"APPICON"),
           "missing PE resource lookup should return no payload");

    auto invalid = icon_resource_executable();
    put32(invalid, 0x400 + 0x1c, 0x80000300);
    expect_failure([&] {
        auto malformed = transmute::PeImage::parse(invalid);
        (void)malformed.find_resource(14, u"APPICON");
    }, "invalid PE resource directory offset");

    invalid = icon_resource_executable();
    put32(invalid, 0x400 + 0x60, 0x800001ff);
    expect_failure([&] {
        auto malformed = transmute::PeImage::parse(invalid);
        (void)malformed.find_resource(14, u"APPICON");
    }, "invalid PE resource directory offset");

    invalid = icon_resource_executable();
    put16(invalid, 0x400 + 0x160, 0xffff);
    expect_failure([&] {
        auto malformed = transmute::PeImage::parse(invalid);
        (void)malformed.find_resource(14, u"APPICON");
    }, "invalid PE resource directory offset");

    invalid = icon_resource_executable();
    put32(invalid, 0x400 + 0xc0, 0x2ff0);
    expect_failure([&] {
        auto malformed = transmute::PeImage::parse(invalid);
        (void)malformed.find_resource(3, std::uint16_t{1});
    }, "PE resource data extends beyond image");

    invalid = icon_resource_executable();
    put16(invalid, 0x400 + 14, 0xffff);
    expect_failure([&] {
        auto malformed = transmute::PeImage::parse(invalid);
        (void)malformed.find_resource(14, u"APPICON");
    }, "invalid PE resource directory offset");
}

void test_decoded_integer_blocks() {
    constexpr std::array words{
        0xd2800000U | (0x1234U << 5),
        0xf2800000U | (1U << 21) | (0xabcdU << 5),
        0x91000000U | (5U << 10),
        0x52800001U | (0xffffU << 5),
        0x72800001U | (1U << 21) | (0xabcdU << 5),
        0x51000002U | (3U << 10) | (1U << 5),
        0x910043ffU,
        0xd503201fU,
        0xd65f03c0U,
    };
    const auto decoded = transmute::decode_integer_block(0x140001000ULL, words);
    expect(decoded && decoded->instructions.size() == words.size() &&
               decoded->instructions[0].op == transmute::BlockOp::move_zero &&
               decoded->instructions[1].op == transmute::BlockOp::move_keep &&
               decoded->instructions[2].op == transmute::BlockOp::add_immediate &&
               decoded->instructions[5].op == transmute::BlockOp::subtract_immediate &&
               decoded->instructions.back().op == transmute::BlockOp::ret,
           "OS-neutral decoded integer block is wrong");
    expect(!transmute::decode_integer_block(0x140001002ULL, words) &&
               !transmute::decode_integer_block(0x140001000ULL,
                   std::array{0xffffffffU, 0xd65f03c0U}) &&
               !transmute::decode_integer_block(0x140001000ULL,
                   std::array{0x52c00000U, 0xd65f03c0U}),
           "decoder accepted a block outside the JIT's exact subset");
    const auto backward = transmute::decode_integer_block(
        0x140001000ULL, std::array{0xd503201fU, 0x17ffffffU});
    expect(backward && backward->instructions.back().op ==
               transmute::BlockOp::branch &&
               backward->instructions.back().immediate == 0x140001000ULL,
           "decoded unconditional branch lost its signed displacement");
#if defined(_WIN32) && (defined(_M_X64) || defined(__x86_64__))
    auto image = transmute::PeImage::parse(
        executable(std::vector<std::uint32_t>(words.begin(), words.end())));
    transmute::ReferenceEngine reference(image);
    auto state = reference.state();
    transmute::X64BlockCache cache;
    expect(cache.execute(state, image.entry(), words),
           "x64 JIT rejected a supported integer block");
    const auto result = reference.run();
    const auto& expected = reference.state();
    expect(result.instructions == words.size() &&
               state.x == expected.x && state.sp == expected.sp &&
               state.pc == expected.pc && state.nzcv == expected.nzcv,
           "x64 JIT integer block differs from ReferenceEngine");
    expect(cache.cache_size() == 1 && cache.last_code_address() != nullptr,
           "x64 JIT did not cache compiled code");
    const auto code_stats = cache.stats();
    expect(code_stats.emitted_code_bytes > 0 &&
               code_stats.allocated_code_bytes >= code_stats.emitted_code_bytes &&
               code_stats.compilation_seconds >= 0,
           "x64 JIT code allocation counters are inconsistent");
    MEMORY_BASIC_INFORMATION protection{};
    expect(VirtualQuery(cache.last_code_address(), &protection,
                        sizeof(protection)) != 0 &&
               protection.State == MEM_COMMIT &&
               protection.Protect == PAGE_EXECUTE_READ,
           "x64 JIT cache is not executable/read-only after emission");

    auto repeated = transmute::ReferenceEngine(image).state();
    const auto first_code = cache.last_code_address();
    expect(cache.execute(repeated, image.entry(), words) &&
               cache.cache_size() == 1 && cache.last_code_address() == first_code &&
               repeated.x == state.x && repeated.sp == state.sp,
           "x64 JIT cache hit changed guest semantics");
    repeated = transmute::ReferenceEngine(image).state();
    expect(cache.execute_cached(repeated, image.entry(), 0, words.size()) ==
               words.size() && repeated.x == state.x &&
               cache.last_code_address() == first_code,
           "generation-checked x64 JIT fast cache hit failed");
    auto changed = words;
    changed[2] = 0x91000000U | (9U << 10);
    repeated = transmute::ReferenceEngine(image).state();
    expect(cache.execute(repeated, image.entry(), changed) &&
               cache.cache_size() == 2 && repeated.x[0] == state.x[0] + 4,
           "x64 JIT reused stale code after instruction bytes changed");
    repeated = transmute::ReferenceEngine(image).state();
    expect(cache.execute(repeated, image.entry(), words, 1) &&
               cache.cache_size() == 3 && repeated.x == state.x,
           "x64 JIT ignored the caller's code generation");
    cache.invalidate_range(image.entry() + 4, 4);
    expect(cache.cache_size() == 0 && cache.last_code_address() == nullptr,
           "x64 JIT executable-write invalidation missed an overlapping block");

    const auto before = repeated;
    expect(!cache.execute(repeated, image.entry(),
                          std::array{0x10000000U, 0xd65f03c0U}) &&
               repeated.x == before.x && repeated.pc == before.pc &&
               repeated.sp == before.sp && cache.cache_size() == 0,
           "x64 JIT changed state before interpreter fallback");
    cache.remember_fallback(image.entry(), 2);
    bool known_fallback = false;
    repeated = transmute::ReferenceEngine(image).state();
    expect(cache.execute_cached(repeated, image.entry(), 2, 8,
                                &known_fallback) == 0 && known_fallback &&
               cache.stats().negative_cache_entries == 1 &&
               cache.stats().negative_cache_hits == 1,
           "JIT did not remember a generation-checked interpreter fallback");
    known_fallback = false;
    expect(cache.execute_cached(repeated, image.entry(), 3, 8,
                                &known_fallback) == 0 && !known_fallback,
           "JIT negative fallback survived a code-generation change");
    cache.invalidate_range(image.entry(), 4);
    expect(cache.stats().negative_cache_entries == 0,
           "JIT range invalidation retained a negative fallback");
#endif
}

#if defined(_WIN32) && (defined(_M_X64) || defined(__x86_64__))
void test_jit_wx_code_arena_lifetime() {
    auto image = transmute::PeImage::parse(executable({0xd65f03c0U}));
    transmute::ReferenceEngine engine(image);
    transmute::X64BlockCache cache;
    constexpr std::array first{0xd2800020U, 0xd65f03c0U}; // return 1
    constexpr std::array second{0xd2800040U, 0xd65f03c0U}; // return 2
    auto state = engine.state();
    expect(cache.execute(state, image.entry(), first) && state.x[0] == 1,
           "first JIT arena block failed");
    const auto first_code = cache.last_code_address();
    state = engine.state();
    state.pc = image.entry() + 0x100;
    expect(cache.execute(state, state.pc, second) && state.x[0] == 2,
           "second JIT arena block failed");
    const auto second_code = cache.last_code_address();
    MEMORY_BASIC_INFORMATION first_memory{}, second_memory{};
    expect(first_code != second_code &&
               VirtualQuery(first_code, &first_memory, sizeof(first_memory)) != 0 &&
               VirtualQuery(second_code, &second_memory, sizeof(second_memory)) != 0 &&
               first_memory.AllocationBase == second_memory.AllocationBase &&
               first_memory.Protect == PAGE_EXECUTE_READ &&
               second_memory.Protect == PAGE_EXECUTE_READ,
           "JIT arena did not preserve W^X after a second block append");
    const auto stats = cache.stats();
    expect(stats.compiled_blocks == 2 && stats.allocated_code_bytes == 65536 &&
               stats.live_code_bytes == 65536 &&
               stats.emitted_code_bytes < stats.live_code_bytes,
           "JIT arena did not pack blocks into one bounded chunk");
    cache.invalidate_range(image.entry(), 8);
    expect(cache.cache_size() == 1, "JIT arena invalidation removed another block");
    state = engine.state();
    state.pc = image.entry() + 0x100;
    expect(cache.execute(state, state.pc, second) && state.x[0] == 2 &&
               cache.last_code_address() == second_code &&
               cache.stats().live_code_bytes == 65536,
           "JIT arena freed live code after partial invalidation");
    cache.invalidate_all();
    expect(cache.cache_size() == 0 && cache.last_code_address() == nullptr &&
               cache.stats().live_code_bytes == 0,
           "JIT arena retained code after full invalidation");
}

void benchmark_jit_cached_dispatch() {
    constexpr std::uint64_t base = 0x140001000;
    constexpr std::uint64_t visits = 5000000;
    const std::array<std::uint32_t, 2> words{0x91000400, 0xd65f03c0};
    transmute::X64BlockCache cache;
    transmute::CpuState state{};
    state.x[30] = base + 0x1000;
    for (unsigned index = 0; index < 16; ++index) {
        state.pc = base + index * 64;
        expect(cache.execute(state, state.pc, words, 1),
               "cached dispatch benchmark failed to compile");
    }
    state.x[0] = 0;
    const auto started = std::chrono::steady_clock::now();
    for (std::uint64_t index = 0; index < visits; ++index) {
        state.pc = base + ((index * 7) & 15) * 64;
        expect(cache.execute_cached(state, state.pc, 1, 2) == 2,
               "cached dispatch benchmark missed a supported block");
    }
    const auto seconds = std::chrono::duration<double>(
        std::chrono::steady_clock::now() - started).count();
    expect(state.x[0] == visits,
           "cached dispatch benchmark produced the wrong result");
    std::cout << "JIT cached dispatch: visits=" << visits
              << " seconds=" << seconds << '\n';
}

void test_jit_cached_dispatch_lifetime() {
    constexpr std::uint64_t first = 0x140001000;
    constexpr std::uint64_t collision = first + 0x4000;
    const std::array<std::uint32_t, 2> one{0xd2800020, 0xd65f03c0};
    const std::array<std::uint32_t, 2> two{0xd2800040, 0xd65f03c0};
    transmute::X64BlockCache cache;
    transmute::CpuState state{};
    state.x[30] = first + 0x80;
    state.pc = first;
    expect(cache.execute(state, first, one, 1), "could not compile first cached block");
    state.pc = collision;
    expect(cache.execute(state, collision, two, 1), "could not compile colliding block");
    for (unsigned index = 0; index < 40; ++index) {
        state.pc = index & 1U ? collision : first;
        expect(cache.execute_cached(state, state.pc, 1, 2) == 2 &&
                   state.x[0] == (index & 1U ? 2U : 1U),
               "cached dispatch confused colliding guest addresses");
    }
    state.pc = first;
    const auto before = state;
    expect(cache.execute_cached(state, first, 1, 1) == 0 &&
               state.x == before.x && state.pc == before.pc,
           "cached dispatch changed state beyond instruction budget");
    expect(cache.execute_cached(state, first, 2, 2) == 0 &&
               state.x == before.x && state.pc == before.pc,
           "cached dispatch retained stale code generation");
    cache.remember_fallback(first, 2);
    bool fallback = false;
    expect(cache.execute_cached(state, first, 2, 2, &fallback) == 0 && fallback,
           "cached dispatch retained a positive block after fallback publication");
    expect(cache.execute(state, first, two, 2),
           "cached dispatch did not replace a negative block");
    state.pc = first;
    fallback = true;
    expect(cache.execute_cached(state, first, 2, 2, &fallback) == 2 &&
               !fallback && state.x[0] == 2,
           "cached dispatch retained a negative block after compilation");
    cache.invalidate_range(first + 4, 4);
    state.pc = first;
    expect(cache.execute_cached(state, first, 2, 2) == 0,
           "cached dispatch executed invalidated code");
    state.pc = collision;
    expect(cache.execute(state, collision, two, 3),
           "cached dispatch could not compile after range invalidation");
    cache.invalidate_all();
    state.pc = collision;
    expect(cache.execute_cached(state, collision, 3, 2) == 0 &&
               cache.last_code_address() == nullptr,
           "cached dispatch retained reclaimed native code");
}

void test_jit_cached_dispatch_reentrancy() {
    constexpr std::uint64_t first = 0x140001000;
    constexpr std::uint64_t collision = first + 0x4000;
    const std::array<std::uint32_t, 2> load{0xb9400040, 0xd65f03c0};
    const std::array<std::uint32_t, 2> two{0xd2800040, 0xd65f03c0};
    auto image = transmute::PeImage::parse(executable({0xd65f03c0}));
    transmute::X64BlockCache cache;
    struct ReentrantMemory final : transmute::ReferenceEngine {
        transmute::X64BlockCache& cache;
        std::uint64_t collision;
        bool armed{};
        mutable bool entered{};
        ReentrantMemory(transmute::PeImage& image, transmute::X64BlockCache& cache,
                        std::uint64_t collision)
            : ReferenceEngine(image), cache(cache), collision(collision) {}
        std::optional<std::uint64_t> try_read_contiguous(
            std::uint64_t address, unsigned bytes) const override {
            const auto result = ReferenceEngine::try_read_contiguous(address, bytes);
            if (armed && !entered) {
                entered = true;
                transmute::CpuState nested{};
                nested.pc = collision;
                nested.x[30] = collision + 0x80;
                expect(cache.execute_cached(nested, collision, 1, 2) == 2 &&
                           nested.x[0] == 2,
                       "reentrant memory did not visit the colliding block");
            }
            return result;
        }
    } memory(image, cache, collision);
    const auto address = memory.state().sp - 128;
    static_cast<transmute::GuestMemory&>(memory).write32(address, 0x11223344);
    transmute::CpuState state{};
    state.pc = first;
    state.x[2] = address;
    state.x[30] = first + 0x80;
    expect(cache.execute(state, first, load, 1, &memory),
           "could not compile reentrant load fixture");
    state.pc = collision;
    expect(cache.execute(state, collision, two, 1),
           "could not compile reentrant collision fixture");
    memory.armed = true;
    state.pc = first;
    expect(cache.execute_cached(state, first, 1, 2, nullptr, &memory) == 2 &&
               memory.entered && state.x[0] == 0x11223344 &&
               state.pc == first + 0x80,
           "reentrant memory replaced the outer cached block");
}

void test_jit_cache_reentrant_invalidation() {
    constexpr std::uint64_t first = 0x140001000ULL;
    constexpr std::uint64_t collision = first + 0x4000;
    constexpr std::array<std::uint32_t, 2> load{0xf9400040U, 0xd65f03c0U};
    constexpr std::array<std::uint32_t, 2> replacement{0xd2800040U, 0xd65f03c0U};
    for (const bool cached : {true, false}) {
        for (const bool all : {true, false}) {
            auto image = transmute::PeImage::parse(executable({0xd65f03c0U}));
            transmute::X64BlockCache cache;
            struct InvalidatingMemory final : transmute::ReferenceEngine {
                transmute::X64BlockCache& cache;
                std::uint64_t first, collision;
                bool all, armed{};
                mutable bool entered{};
                mutable const void* replacement_address{};
                InvalidatingMemory(transmute::PeImage& image, transmute::X64BlockCache& cache,
                                   std::uint64_t first, std::uint64_t collision, bool all)
                    : ReferenceEngine(image), cache(cache), first(first), collision(collision), all(all) {}
                std::optional<std::uint64_t> try_read_contiguous(
                    std::uint64_t address, unsigned bytes) const override {
                    const auto value = ReferenceEngine::try_read_contiguous(address, bytes);
                    if (armed && !entered) {
                        entered = true;
                        if (all) cache.invalidate_all();
                        else cache.invalidate_range(first, 8);
                        transmute::CpuState nested{};
                        nested.pc = collision;
                        nested.x[30] = collision + 0x80;
                        const std::array<std::uint32_t, 2> words{0xd2800040U, 0xd65f03c0U};
                        expect(cache.execute(nested, collision, words, 1) && nested.x[0] == 2,
                               "memory reentry could not compile its colliding replacement");
                        replacement_address = cache.last_code_address();
                    }
                    return value;
                }
            } memory(image, cache, first, collision, all);
            const auto address = memory.state().sp - 128;
            static_cast<transmute::GuestMemory&>(memory).write64(address, 0x123456789abcdef0ULL);
            transmute::CpuState state{};
            state.pc = first;
            state.x[0] = 0x5555;
            state.x[2] = address;
            state.x[30] = first + 0x80;
            state.sp = memory.state().sp;
            state.nzcv = 0xa0000000U;
            const auto before = state;
            expect(cache.execute(state, first, load, 1, &memory),
                   "could not compile reentrant invalidation load fixture");
            state = before;
            memory.armed = true;
            const auto executed = cached
                ? cache.execute_cached(state, first, 1, 2, nullptr, &memory)
                : cache.execute(state, first, load, 1, &memory) ? 2U : 0U;
            auto expected_registers = before.x;
            expected_registers[0] = 0x123456789abcdef0ULL;
            expect(executed == 2 && memory.entered && state.x == expected_registers &&
                       state.pc == before.x[30] && state.sp == before.sp &&
                       state.nzcv == before.nzcv,
                   "reentrant invalidation reclaimed or replaced the active JIT block");
            expect(cache.last_code_address() == memory.replacement_address,
                   "outer execution exposed retired code as the latest JIT address");
            auto stale = before;
            expect(cache.execute_cached(stale, first, 1, 2, nullptr, &memory) == 0 &&
                       stale.x == before.x && stale.pc == before.pc,
                   "reentrant invalidation republished the removed outer JIT block");
            transmute::CpuState nested{};
            nested.pc = collision;
            nested.x[30] = collision + 0x80;
            expect(cache.execute_cached(nested, collision, 1, replacement.size()) == replacement.size() &&
                       nested.x[0] == 2 && nested.pc == collision + 0x80,
                   "outer cache reentry damaged the replacement JIT block");
        }
    }
}

void test_jit_runtime_dispatch_and_invalidation() {
    auto image = transmute::PeImage::parse(executable({
        0xd2800000U, // movz x0, #0
        0x91000400U, // add x0, x0, #1
        0xd1000421U, // sub x1, x1, #1
        0xb5ffffc1U, // cbnz x1, two instructions backward
        0xd65f03c0U  // ret
    }));
    transmute::ReferenceEngine reference(image);
    transmute::ReferenceEngine optimized(image);
    reference.set_initial_register(1, 100);
    optimized.set_initial_register(1, 100);
    optimized.set_jit_enabled(true);
    optimized.set_jit_profiling(true);
    const auto expected = reference.run();
    const auto actual = optimized.run();
    expect(actual.exit_code == expected.exit_code &&
               actual.instructions == expected.instructions &&
               actual.exit_code == 100 &&
               optimized.state().x == reference.state().x &&
               optimized.state().sp == reference.state().sp &&
               optimized.state().pc == reference.state().pc &&
               optimized.state().nzcv == reference.state().nzcv &&
               optimized.jit_executed_instructions() >= 200,
           "opt-in JIT loop dispatch differs from interpreter fallback");
    const auto loop_stats = optimized.jit_stats(2);
    std::uint64_t profiled_invocations = 0;
    for (const auto& block : loop_stats.hottest_blocks) {
        expect(block.guest_pc >= image.entry() &&
                   block.guest_pc < image.entry() + 5 * 4,
               "counted loop profile attributed execution outside its owner");
        profiled_invocations += block.executions;
    }
    expect(loop_stats.compiled_blocks == 1 &&
               loop_stats.compiled_native_regions == 1 && loop_stats.fast_hits > 0 &&
               loop_stats.native_blocks < 12 &&
               loop_stats.native_guest_instructions ==
                   optimized.jit_executed_instructions() &&
               loop_stats.fallback_instructions == 0 &&
               !loop_stats.hottest_blocks.empty() &&
               profiled_invocations == loop_stats.native_blocks,
           "opt-in JIT frame counters missed the counted hot loop");

    transmute::ReferenceEngine budget_reference(image);
    transmute::ReferenceEngine budget_optimized(image);
    for (auto* engine : {&budget_reference, &budget_optimized}) {
        engine->set_initial_register(1, 100);
        engine->set_instruction_limit(5);
    }
    budget_optimized.set_jit_enabled(true);
    expect_failure([&] { static_cast<void>(budget_reference.run()); },
                   "guest exceeded instruction limit");
    expect_failure([&] { static_cast<void>(budget_optimized.run()); },
                   "guest exceeded instruction limit");
    expect(budget_optimized.state().x == budget_reference.state().x &&
               budget_optimized.state().pc == budget_reference.state().pc &&
               budget_optimized.state().nzcv == budget_reference.state().nzcv &&
               budget_optimized.jit_executed_instructions() <= 5,
           "chained JIT dispatch crossed the guest instruction budget");

    auto branch_image = transmute::PeImage::parse(executable({
        0xd503201fU, // nop
        0x34000040U, // cbz w0, +8
        0xd28000e0U, // movz x0, #7 (skipped)
        0xd65f03c0U  // ret
    }));
    transmute::ReferenceEngine branch_reference(branch_image);
    transmute::ReferenceEngine branch_optimized(branch_image);
    branch_reference.set_initial_register(0, 0x100000000ULL);
    branch_optimized.set_initial_register(0, 0x100000000ULL);
    branch_optimized.set_jit_enabled(true);
    const auto branch_expected = branch_reference.run();
    const auto branch_actual = branch_optimized.run();
    expect(branch_actual.exit_code == branch_expected.exit_code &&
               branch_actual.exit_code == 0 &&
               branch_actual.instructions == branch_expected.instructions &&
               branch_optimized.state().x == branch_reference.state().x &&
               branch_optimized.state().pc == branch_reference.state().pc &&
               branch_optimized.jit_executed_instructions() >= 2,
           "opt-in JIT CBZ W branch differs from ReferenceEngine");

    constexpr std::uint64_t code = 0x200000000ULL;
    optimized.map_memory(code, 4096);
    optimized.set_memory_access(code, true, true, true);
    optimized.write32(code, 0xd2800020U);      // movz x0, #1
    optimized.write32(code + 4, 0xd503201fU);  // nop
    optimized.write32(code + 8, 0xd65f03c0U);  // ret
    const auto before = optimized.jit_executed_instructions();
    expect(optimized.invoke_callback(code, 0) == 1 &&
               optimized.jit_executed_instructions() >= before + 3,
           "opt-in JIT did not execute mapped guest code");
    optimized.write32(code, 0xd2800040U);      // movz x0, #2
    expect(optimized.invoke_callback(code, 0) == 2,
           "opt-in JIT reused stale code after executable-memory write");
    optimized.set_memory_access(code, true, false, true);
    expect(optimized.invoke_callback(code, 0) == 2,
           "opt-in JIT lost mapped code after protection change");
}

void test_jit_negative_fallback_dispatch() {
    auto image = transmute::PeImage::parse(executable({
        0x98000003U, // ldrsw x3, literal at current PC: interpreter fallback
        0x51000421U, // sub w1, w1, #1
        0x35ffffc1U, // cbnz w1, -8
        0xd65f03c0U
    }));
    transmute::ReferenceEngine reference(image);
    transmute::ReferenceEngine optimized(image);
    for (auto* engine : {&reference, &optimized}) {
        engine->set_initial_register(0, image.entry());
        engine->set_initial_register(1, 5000);
    }
    optimized.set_jit_enabled(true);
    optimized.set_jit_profiling(true);
    const auto expected = reference.run();
    const auto actual = optimized.run();
    const auto stats = optimized.jit_stats();
    expect(actual.exit_code == expected.exit_code &&
               actual.instructions == expected.instructions &&
               optimized.state().x == reference.state().x &&
               optimized.state().pc == reference.state().pc &&
               optimized.state().nzcv == reference.state().nzcv,
           "JIT negative fallback changed guest loop semantics");
    expect(stats.negative_cache_hits >= 4999 &&
               stats.negative_cache_entries >= 1,
           "JIT negative fallback cache missed the repeated load");
    expect(stats.fallback_profile_observations ==
               stats.fallback_instructions,
           "JIT fallback sampler missed interpreter observations");
    expect(!stats.hottest_fallbacks.empty() &&
               stats.hottest_fallbacks.front().guest_pc == image.entry() &&
               stats.hottest_fallbacks.front().opcode == 0x98000003U,
           "JIT fallback sampler missed the repeated load");
}

void test_jit_single_instruction_admission() {
    const std::vector<std::uint32_t> words{
        0xaa1e03f6U, // save LR in x22
        0xd2800081U, // movz x1,#4
        0xf2a00001U, // movk x1,#0,lsl#16
        0xd2b40014U, // movz x20,#0xa000,lsl#16
        0xf0002231U, 0xd51b4214U, // profiled ADRP; unsupported MSR separator
        0x9100e108U, 0xd51b4214U, // profiled ADD x8,x8,#56
        0x910103ffU, 0xd51b4214U, // profiled ADD SP,SP,#64
        0xd10103ffU, 0xd51b4214U, // restore SP
        0x90001568U, 0xd51b4214U, // profiled ADRP
        0x94000008U, 0xd51b4214U, // direct BL helper; MSR remains a fallback
        0xd1000421U, 0xd51b4214U, // SUB x1,x1,#1
        0xb5fffe41U, // CBNZ x1 to first ADRP
        0xaa1603feU, 0xd2800000U, 0xd65f03c0U,
        0xd65f03c0U}; // helper is a lone RET
    auto image = transmute::PeImage::parse(executable(words));
    transmute::ReferenceEngine reference(image);
    transmute::ReferenceEngine optimized(image);
    const auto original_sp = reference.state().sp;
    optimized.set_jit_enabled(true);
    optimized.set_jit_profiling(true);
    const auto expected = reference.run();
    const auto actual = optimized.run();
    const auto stats = optimized.jit_stats();
    expect(actual.instructions == 71 && actual.instructions == expected.instructions &&
               actual.exit_code == expected.exit_code &&
               optimized.state().x == reference.state().x &&
               optimized.state().pc == reference.state().pc &&
               optimized.state().sp == original_sp &&
               optimized.state().nzcv == 0xa0000000U &&
               optimized.jit_executed_instructions() == 43 &&
               stats.fallback_instructions == 28 && stats.fast_hits > 0,
           "JIT singleton policy skipped supported prefixes or changed guest state");
    for (const auto opcode : {0xf0002231U, 0x90001568U, 0x9100e108U,
                              0x910103ffU, 0xb4000240U, 0xd65f03c0U}) {
        auto single_image = transmute::PeImage::parse(executable({
            opcode, 0xd51b4214U, 0xd65f03c0U}));
        transmute::ReferenceEngine single_reference(single_image);
        transmute::ReferenceEngine single_optimized(single_image);
        for (auto* engine : {&single_reference, &single_optimized}) {
            engine->set_initial_register(0, 1); // CBZ falls through to MSR.
            engine->set_initial_register(20, 0x50000000);
        }
        single_optimized.set_jit_enabled(true);
        const auto expected_single = single_reference.run();
        const auto actual_single = single_optimized.run();
        expect(actual_single.instructions == expected_single.instructions &&
                   single_optimized.state().x == single_reference.state().x &&
                   single_optimized.state().sp == single_reference.state().sp &&
                   single_optimized.state().pc == single_reference.state().pc &&
                   single_optimized.state().nzcv == single_reference.state().nzcv &&
                   single_optimized.jit_executed_instructions() ==
                       (opcode == 0xd65f03c0U ? 1U : 2U),
               "JIT failed to admit a sampled supported single instruction");
    }
    for (const auto budget : {1ULL, 4ULL, 5ULL, 8ULL, 9ULL, 14ULL,
                              16ULL, 20ULL, 30ULL, 70ULL}) {
        transmute::ReferenceEngine limited_reference(image);
        transmute::ReferenceEngine limited_optimized(image);
        limited_reference.set_instruction_limit(budget);
        limited_optimized.set_instruction_limit(budget);
        limited_optimized.set_jit_enabled(true);
        expect_failure([&] { static_cast<void>(limited_reference.run()); },
                       "guest exceeded instruction limit");
        expect_failure([&] { static_cast<void>(limited_optimized.run()); },
                       "guest exceeded instruction limit");
        expect(limited_optimized.state().x == limited_reference.state().x &&
                   limited_optimized.state().pc == limited_reference.state().pc &&
                   limited_optimized.state().sp == limited_reference.state().sp &&
                   limited_optimized.state().nzcv == limited_reference.state().nzcv &&
                   limited_optimized.jit_executed_instructions() <= budget,
               "JIT admitted singleton exceeded its instruction budget");
    }
}

void test_jit_variable_shifts() {
    struct Registers { unsigned destination, source, count; };
    constexpr std::array register_forms{
        Registers{0, 8, 9}, Registers{8, 8, 9}, Registers{9, 8, 9},
        Registers{8, 8, 8}, Registers{8, 31, 9}, Registers{8, 8, 31},
        Registers{31, 8, 9}, Registers{8, 31, 31}};
    constexpr std::array counts{0ULL, 1ULL, 31ULL, 32ULL, 33ULL, 63ULL,
        64ULL, 65ULL, 127ULL, 255ULL, 256ULL, UINT64_MAX,
        0x1234567800000021ULL};
    constexpr std::array values{0ULL, 0x8000000080000001ULL,
        UINT64_MAX, 0x123456789abcdef0ULL};
    const auto shifted = [](std::uint64_t value, std::uint64_t count,
                            unsigned operation, bool wide) {
        const auto width = wide ? 64U : 32U;
        const auto mask = wide ? UINT64_MAX : 0xffffffffULL;
        value &= mask;
        const auto shift = static_cast<unsigned>(count & (width - 1));
        if (shift == 0) return value;
        if (operation == 0) return (value << shift) & mask;
        if (operation == 1) return value >> shift;
        if (operation == 2) {
            const auto fill = (value & (1ULL << (width - 1))) != 0
                ? (UINT64_MAX << (width - shift)) & mask : 0;
            return (value >> shift) | fill;
        }
        return ((value >> shift) | (value << (width - shift))) & mask;
    };
    for (const bool wide : {false, true}) {
        for (unsigned operation = 0; operation != 4; ++operation) {
            for (const auto registers : register_forms) {
                const auto opcode = (wide ? 0x9ac02000U : 0x1ac02000U) |
                    (operation << 10) | (registers.count << 16) |
                    (registers.source << 5) | registers.destination;
                const auto move_result = registers.destination == 31
                    ? 0xd503201fU // Preserve X0 for a discarded destination.
                    : 0xaa0003e0U | (registers.destination << 16);
                const std::array words{opcode, move_result, 0xd65f03c0U};
                auto image = transmute::PeImage::parse(executable({
                    0xd51b4214U, // msr nzcv,x20 initializes arbitrary flags
                    words[0], words[1], words[2]}));
                transmute::ReferenceEngine reference(image);
                reference.set_initial_vector(7, {0x0123456789abcdefULL, UINT64_MAX});
                transmute::X64BlockCache cache;
                unsigned flags = 0;
                for (const auto value : values) {
                    for (const auto count : counts) {
                        reference.set_initial_register(0, 0xabcdef0123456789ULL);
                        reference.set_initial_register(8, value);
                        reference.set_initial_register(9, count);
                        reference.set_initial_register(20, (flags++ & 15U) << 28);
                        auto state = reference.state();
                        state.pc = image.entry() + 4;
                        state.nzcv = static_cast<std::uint32_t>(state.x[20]);
                        state.fpcr = 0x01c00000U;
                        state.fpsr = 0x0800009fU;
                        const auto before = state;
                        const auto input = registers.source == 31 ? 0
                            : before.x[registers.source];
                        const auto shift_count = registers.count == 31 ? 0
                            : before.x[registers.count];
                        const auto result = shifted(input, shift_count, operation, wide);
                        auto expected_registers = before.x;
                        if (registers.destination != 31) {
                            expected_registers[registers.destination] = result;
                            expected_registers[0] = result;
                        }
                        const auto reference_result = reference.invoke_callback(
                            image.entry(), std::span<const std::uint64_t>{});
                        expect(cache.execute(state, image.entry() + 4, words) &&
                                   state.x == expected_registers &&
                                   state.x[0] == reference_result &&
                                   state.sp == before.sp && state.pc == before.x[30] &&
                                   state.nzcv == before.nzcv && state.v == before.v &&
                                   state.fpcr == before.fpcr && state.fpsr == before.fpsr,
                               "JIT variable shift changed result, aliases, or architectural flags");
                        auto cached = before;
                        expect(cache.execute_cached(cached, cached.pc, 0, 2) == 0 &&
                                   cached.x == before.x && cached.pc == before.pc &&
                                   cached.nzcv == before.nzcv && cached.sp == before.sp,
                               "JIT variable shift crossed the cached instruction budget");
                        expect(cache.execute_cached(cached, cached.pc, 0, 3) == 3 &&
                                   cached.x == state.x && cached.pc == state.pc &&
                                   cached.nzcv == before.nzcv && cached.v == before.v,
                               "JIT cached variable shift differs from its first execution");
                    }
                }
                expect(cache.cache_size() == 1,
                       "JIT variable shift failed to reuse code across dynamic counts");
            }
        }
    }
    for (const auto word : {0x9ac82128U, 0x9ad82128U}) {
        const auto decoded = transmute::decode_integer_block(
            0x140001000ULL, std::array{word});
        expect(decoded && decoded->instructions.front().op ==
                              transmute::BlockOp::shift_register &&
                   decoded->instructions.front().wide &&
                   decoded->instructions.front().shift_type == 0,
               "JIT failed to decode a profiled Blender LSLV form");
    }
    for (const auto word : {0x3ac82128U, 0x5ac82128U, 0x1ae82128U,
                            0x1ac83128U, 0x1ac86128U}) {
        expect(!transmute::decode_integer_block(
                   0x140001000ULL, std::array{word}),
               "JIT accepted a reserved variable-shift encoding");
    }
    auto budget_image = transmute::PeImage::parse(executable({
        0x9ac92108U, // lslv x8,x8,x9
        0x9aca2508U, // lsrv x8,x8,x10
        0x9acb2908U, // asrv x8,x8,x11
        0x9acc2d08U, // rorv x8,x8,x12
        0xd65f03c0U}));
    for (std::uint64_t budget = 1; budget != 5; ++budget) {
        transmute::ReferenceEngine reference(budget_image);
        transmute::ReferenceEngine optimized(budget_image);
        for (auto* engine : {&reference, &optimized}) {
            engine->set_initial_register(8, 0x8000000087654321ULL);
            engine->set_initial_register(9, 65);
            engine->set_initial_register(10, 64);
            engine->set_initial_register(11, UINT64_MAX);
            engine->set_initial_register(12, 33);
            engine->set_instruction_limit(budget);
        }
        optimized.set_jit_enabled(true);
        expect_failure([&] { static_cast<void>(reference.run()); },
                       "guest exceeded instruction limit");
        expect_failure([&] { static_cast<void>(optimized.run()); },
                       "guest exceeded instruction limit");
        expect(optimized.state().x == reference.state().x &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().sp == reference.state().sp &&
                   optimized.state().nzcv == reference.state().nzcv &&
                   optimized.jit_executed_instructions() <= budget,
               "JIT variable-shift block exceeded the runtime instruction budget");
    }
}

void test_jit_native_region_decoding() {
    constexpr std::uint64_t pc = 0x500600000ULL;
    const std::array chain{0xf9400081U, 0xf9400022U, 0x8b020000U,
                           0xd65f03c0U, 0xd503201fU};
    const auto region = transmute::decode_native_read_region(pc, chain);
    const auto legacy = transmute::decode_integer_block(pc, chain);
    expect(region && region->words.size() == 4 && legacy &&
               legacy->words.size() == 1,
           "native region changed legacy first-memory decoding or passed RET");
    const auto loop = transmute::decode_native_read_region(pc,
        std::array{0xf9400081U, 0xf1000463U, 0x54ffffc1U});
    expect(loop && loop->words.size() == 3 &&
               loop->instructions.back().immediate == pc,
           "native read loop lost its internal branch target");
    const auto store_exit = transmute::decode_native_read_region(pc,
        std::array{0xf9400081U, 0xf9400022U, 0xf9000082U, 0xd65f03c0U});
    expect(store_exit && store_exit->words.size() == 4 &&
               store_exit->instructions[2].op == transmute::BlockOp::store_doubleword,
           "native region did not admit its guarded journaled store");
    const auto reserved_exit = transmute::decode_native_read_region(pc,
        std::array{0xf9400081U, 0xf9400022U, 0xf9c00000U, 0xd65f03c0U});
    expect(reserved_exit && reserved_exit->words.size() == 2,
           "native read region admitted a reserved memory access");
    expect(!transmute::decode_native_read_region(pc + 1, chain) &&
               !transmute::decode_native_read_region(UINT64_MAX - 3, chain),
           "native region accepted invalid code addresses");
    const auto pure = transmute::decode_native_read_region(pc,
        std::array{0xd503201fU, 0xd65f03c0U});
    expect(pure && pure->words.size() == 2 &&
               pure->instructions[0].op == transmute::BlockOp::nop &&
               pure->instructions[1].op == transmute::BlockOp::ret,
           "counted native region rejected its pure control owner");
    auto image = transmute::PeImage::parse(executable({0xd65f03c0U}));
    transmute::ReferenceEngine engine(image);
    auto state = engine.state();
    state.pc = pc;
    const auto before = state;
    transmute::X64BlockCache cache;
    expect(cache.execute_native_region(state, pc, chain, 0, 4, &engine) == 0 &&
               native_region_same_state(state, before) && cache.cache_size() == 0,
           "ordinary memory exposed a native lease outside its scoped run");
}

void test_jit_native_region_load_forms() {
#if defined(_WIN32) && (defined(_M_X64) || defined(__x86_64__))
    constexpr std::uint64_t data = 0x500600000ULL;
    for (unsigned size = 0; size != 4; ++size) {
        for (unsigned access = 1; access != 4; ++access) {
            if ((size == 2 && access == 3) || (size == 3 && access != 1))
                continue;
            for (unsigned mode = 0; mode != 8; ++mode) {
                for (const unsigned destination : {8U, 9U, 31U}) {
                    if ((mode == 2 || mode == 3) && destination == 9) continue;
                    std::uint32_t opcode = (size << 30) | (access << 22) |
                        (9U << 5) | destination;
                    std::uint64_t register_offset = 0;
                    if (mode == 0) {
                        opcode |= 0x39000000U | (8U << 10);
                    } else if (mode < 4) {
                        const unsigned displacement = mode == 2 ? 8U : 505U;
                        opcode |= 0x38000000U | (displacement << 12) |
                            (mode == 2 ? 0x400U : mode == 3 ? 0xc00U : 0U);
                    } else {
                        const unsigned option = mode == 4 ? 2 : mode == 5 ? 3 :
                                                mode == 6 ? 6 : 7;
                        register_offset = mode == 4 ? 0xabcdef0000000004ULL :
                            mode == 5 ? 3 : mode == 6 ? 0xfffffffcULL : UINT64_MAX - 2;
                        opcode |= 0x38200800U | (10U << 16) | (option << 13) |
                            (mode == 5 || mode == 6 ? 0x1000U : 0U);
                    }
                    const auto bytes = executable({
                        0xf9400096U, // ldr x22,[x4]
                        0xf94002d9U, // ldr x25,[x22]
                        opcode,
                        0xaa0803e0U, // mov x0,x8
                        0xd65f03c0U});
                    auto reference_image = transmute::PeImage::parse(bytes);
                    auto native_image = transmute::PeImage::parse(bytes);
                    transmute::ReferenceEngine reference(reference_image);
                    transmute::ReferenceEngine native(native_image);
                    for (auto* engine : {&reference, &native}) {
                        engine->map_memory(data, 1024);
                        for (unsigned offset = 0; offset != 256; ++offset)
                            static_cast<transmute::GuestMemory&>(*engine).write8(
                                data + offset, static_cast<std::uint8_t>(0x80U + offset));
                        engine->write64(data + 512, data + 768);
                        engine->write64(data + 768, 123);
                        engine->set_initial_register(4, data + 512);
                        engine->set_initial_register(8, UINT64_MAX);
                        engine->set_initial_register(9, data + 128);
                        engine->set_initial_register(10, register_offset);
                        engine->set_initial_vector(7, {0x123456789abcdefULL, UINT64_MAX});
                    }
                    native.set_jit_enabled(true);
                    const auto expected = reference.run();
                    const auto actual = native.run();
                    if (actual.instructions != expected.instructions ||
                        !native_region_same_state(native.state(), reference.state()) ||
                        native.jit_stats().native_region_instructions != 5) {
                        throw std::runtime_error("native ordered load differs for opcode " +
                            std::to_string(opcode));
                    }
                }
            }
        }
    }
#endif
}

void test_jit_native_region_hot_aliases() {
#if defined(_WIN32) && (defined(_M_X64) || defined(__x86_64__))
    constexpr std::uint64_t code = 0x500800000ULL;
    constexpr std::uint64_t object = code + 0x1000;
    constexpr std::uint64_t leaf = object + 0x1000;
    auto image = transmute::PeImage::parse(executable({0xd65f03c0U}));
    transmute::ReferenceEngine engine(image);
    engine.map_memory(code, 4096);
    engine.set_memory_access(code, true, true, true);
    engine.map_memory(object, 16);
    engine.map_memory(leaf, 16);
    engine.write64(object, leaf);
    engine.write64(leaf, 42);
    engine.write32(code, 0xf9400081U); // ldr x1,[x4]
    engine.write32(code + 4, 0xf9400022U); // ldr x2,[x1]
    engine.write32(code + 8, 0x8b020000U); // add x0,x0,x2
    engine.write32(code + 12, 0xd65f03c0U);
    engine.set_initial_register(1, leaf);
    engine.set_initial_register(2, 42);
    engine.set_initial_register(4, object);
    engine.set_jit_enabled(true);
    expect(engine.invoke_callback(code, 7) == 49,
           "native alias fixture did not warm its owning region");
    const auto compiled = engine.jit_stats().compiled_native_regions;
    for (const std::uint64_t offset : {4ULL, 8ULL, 12ULL}) {
        expect(engine.invoke_callback(code + offset, 5) == (offset == 12 ? 5 : 47),
               "native alias did not start at its exact guest instruction");
    }
    expect(compiled == 1 && engine.jit_stats().compiled_native_regions == compiled &&
               engine.jit_stats().native_region_alias_hits >= 3,
           "native hot aliases recompiled overlapping region suffixes");
    // Changing the owner prefix must retire every alias, including one whose
    // own PC/remaining extent does not intersect that write.
    engine.write32(code, 0xd503201fU);
    expect(engine.invoke_callback(code + 4, 5) == 47 &&
               engine.jit_stats().compiled_native_regions == compiled + 1,
           "executable owner-prefix invalidation left a stale native alias");
    engine.unmap_memory(code);
    engine.map_memory(code, 4096);
    engine.set_memory_access(code, true, true, true);
    engine.write32(code, 0xf9400081U);
    engine.write32(code + 4, 0xf9400022U);
    engine.write32(code + 8, 0xcb020000U); // sub x0,x0,x2
    engine.write32(code + 12, 0xd65f03c0U);
    expect(engine.invoke_callback(code + 4, 100) == 58 &&
               engine.jit_stats().compiled_native_regions == compiled + 2,
           "unload/remap reused a freed region owner through its alias");
#endif
}

void test_jit_native_vector_memory_decoding() {
    constexpr std::uint64_t pc = 0x500900000ULL;
    for (const auto [opcode, width, op] :
         std::array<std::tuple<std::uint32_t, unsigned, transmute::BlockOp>, 10>{
             std::tuple{0x3d400020U, 1U, transmute::BlockOp::load_vector},
             std::tuple{0x7d400020U, 2U, transmute::BlockOp::load_vector},
             std::tuple{0xbd400020U, 4U, transmute::BlockOp::load_vector},
             std::tuple{0xfd400020U, 8U, transmute::BlockOp::load_vector},
             std::tuple{0x3dc00020U, 16U, transmute::BlockOp::load_vector},
             std::tuple{0x3d800020U, 16U, transmute::BlockOp::store_vector},
             std::tuple{0x2d400020U, 4U, transmute::BlockOp::load_vector_pair},
             std::tuple{0x6d400020U, 8U, transmute::BlockOp::load_vector_pair},
             std::tuple{0xad400020U, 16U, transmute::BlockOp::load_vector_pair},
             std::tuple{0xad000020U, 16U, transmute::BlockOp::store_vector_pair}}) {
        const auto region = transmute::decode_native_read_region(pc, std::array{opcode});
        expect(region && region->instructions.front().op == op &&
                   region->instructions.front().memory_bytes == width &&
                   !transmute::decode_integer_block(pc, std::array{opcode}),
               "vector memory admission changed its width or the independent leaf decoder");
    }
    for (const std::uint32_t reserved : {0x7dc00020U, 0xbdc00020U, 0xfdc00020U,
                                        0xed400020U, 0x3c600820U, 0x3c400820U,
                                        0x7cc00020U, 0xdc000020U})
        expect(!transmute::decode_native_read_region(pc, std::array{reserved}),
               "native vector memory decoder admitted a reserved size/address form");
    const auto literal = transmute::decode_native_read_region(pc,
        std::array{0x9cffffe7U}); // ldr q7, preceding instruction address
    expect(literal && literal->instructions.front().memory_literal &&
               literal->instructions.front().immediate == pc - 4 &&
               literal->instructions.front().memory_bytes == 16,
           "native vector literal lost signed PC-relative addressing");
}

void test_jit_simd_fusion_dispatch_budgets() {
#if defined(_WIN32) && (defined(_M_X64) || defined(__x86_64__))
    constexpr std::uint64_t data = 0x500d00000ULL;
    constexpr std::array forms{
        0x4e201c00U, 0x4e601c00U, 0x4ea01c00U, 0x6e201c00U,
        0x4e208400U, 0x4e608400U, 0x4ea08400U, 0x4ee08400U,
        0x6e208400U, 0x6e608400U, 0x6ea08400U, 0x6ee08400U,
    };
    const auto initialize = [](transmute::ReferenceEngine& engine) {
        engine.set_initial_register(0, data);
        engine.set_initial_register(15, UINT64_MAX);
        for (unsigned reg = 0; reg != 32; ++reg) {
            engine.set_initial_vector(reg, {
                0x8877665544332211ULL ^ (reg * 0x1020304050607ULL),
                0xfedcba9876543210ULL + reg * 0x1000100010001ULL});
        }
    };
    for (const auto form : forms) {
        for (const unsigned destination : {2U, 4U, 8U}) {
            const auto first = form | destination | (4U << 5) | (8U << 16);
            const auto second = form | (destination + 1) | (5U << 5) | (9U << 16);
            const std::array leaf_words{first, second, 0xd65f03c0U};
            auto leaf_image = transmute::PeImage::parse(executable({
                first, second, 0xd65f03c0U}));
            transmute::ReferenceEngine leaf_reference(leaf_image);
            initialize(leaf_reference);
            auto leaf_state = leaf_reference.state();
            static_cast<void>(leaf_reference.run());
            transmute::X64BlockCache leaf_cache;
            expect(leaf_cache.execute(leaf_state, leaf_image.entry(), leaf_words) &&
                       native_region_same_state(leaf_state, leaf_reference.state()),
                   "paired SIMD leaf changed aliasing, registers or control state");
            if (transmute::jit_detail::native_avx2_available()) {
                const auto fragment = transmute::jit_detail::emit_fused_integer_simd(
                    first, second);
                const auto* code = static_cast<const std::uint8_t*>(
                    leaf_cache.last_code_address());
                const auto bytes = static_cast<std::size_t>(
                    leaf_cache.stats().emitted_code_bytes);
                expect(std::search(code, code + bytes, fragment.begin(), fragment.end())
                           != code + bytes,
                       "eligible paired SIMD leaf did not contain its AVX2 fragment");
            }
            const auto program = executable({
                0xf940000fU, // ldr x15,[x0], makes the following pair a region.
                first, second, 0xd65f03c0U});
            for (unsigned budget = 1; budget <= 4; ++budget) {
                auto reference_image = transmute::PeImage::parse(program);
                auto native_image = transmute::PeImage::parse(program);
                transmute::ReferenceEngine reference(reference_image);
                transmute::ReferenceEngine native(native_image);
                for (auto* engine : {&reference, &native}) {
                    initialize(*engine);
                    engine->map_memory(data, 8);
                    engine->write64(data, 0x123456789abcdef0ULL);
                }
                native.set_jit_enabled(true);
                static_cast<void>(native.invoke_callback(native_image.entry(),
                    std::span<const std::uint64_t>{}));
                if (budget != 4) {
                    for (auto* engine : {&reference, &native}) {
                        expect_failure([&] { static_cast<void>(engine->run(budget)); },
                                       "guest exceeded instruction limit");
                    }
                    expect(native_region_same_state(native.state(), reference.state()),
                           "paired SIMD region crossed its two-step budget or second entry");
                }
                const auto expected = reference.run();
                const auto actual = native.run();
                expect(actual.instructions == expected.instructions &&
                           native_region_same_state(native.state(), reference.state()) &&
                           native.jit_stats().compiled_native_regions == 1,
                       "paired SIMD region could not resume its independently cached second body");
            }
        }
    }
#endif
}

void test_jit_native_register_span_budgets() {
#if defined(_WIN32) && (defined(_M_X64) || defined(__x86_64__))
    constexpr std::uint64_t data = 0x500f00000ULL;
    std::vector<std::uint32_t> words{
        0xf940008fU, // ldr x15,[x4]
        0x8b0f0000U, // add x0,x0,x15
        0x11000421U, // add w1,w1,#1
        0xca000042U, // eor x2,x2,x0
        0x9280001fU, // movn xzr,#0; internal target in the first pure span
        0x9b0f7c03U, // mul x3,x0,x15
        0x9ac72066U, // lslv x6,x3,x7, uses volatile R10 in its existing emitter
        0xaa020108U, // orr x8,x8,x2
        0x910043ffU, // add sp,sp,#16
        0xd10043ffU, // sub sp,sp,#16
        0x5303442aU, // ubfm w10,w1,#3,#17
        0x9349bc4bU, // sbfm x11,x2,#9,#47
        0x7a541104U, // ccmp w8,#20,#4,ne
        0x4ea88490U, // add v16.4s,v4.4s,v8.4s
        0x4ea984b1U, // add v17.4s,v5.4s,v9.4s; adjacent independent SIMD pair
        0x6eea84d2U, // sub v18.2d,v6.2d,v10.2d
        0x9e660060U, // fmov x0,d3, only transfers bits
        0xd282468cU, // movz x12,#0x1234
        0xb3507c6dU, // bfm x13,x3,#16,#31
        0x9b0f806eU, // msub x14,x3,x15,x0
        0x9a830016U, // csel x22,x0,x3,eq
        0xf94000b0U, // ldr x16,[x5], a precise checked boundary after 20 pure ops
        0x8b100000U, // add x0,x0,x16
        0xca0e01ceU, // eor x14,x14,x14
        0xf10006f7U, // subs x23,x23,#1
        0x54fffd61U, // b.ne to instruction4, entering a pure suffix
        0xd65f03c0U,
    };
    const auto bytes = executable(words);
    const auto initialize = [](transmute::ReferenceEngine& engine, bool second) {
        engine.map_memory(data, 8);
        engine.write64(data, 7);
        if (second) {
            engine.map_memory(data + 0x1000, 8);
            engine.write64(data + 0x1000, 43);
        }
        for (unsigned reg = 0; reg != 30; ++reg)
            engine.set_initial_register(reg, 0xfedcba9876543210ULL ^ (reg * 37U));
        engine.set_initial_register(4, data);
        engine.set_initial_register(5, data + 0x1000);
        engine.set_initial_register(7, 65);
        engine.set_initial_register(23, 3);
        for (unsigned reg = 0; reg != 32; ++reg) {
            engine.set_initial_vector(reg, {0x123456789abcdef0ULL + reg * 67U,
                0xfedcba9876543210ULL ^ (reg * 0x1020304050607ULL)});
        }
    };
    auto count_image = transmute::PeImage::parse(bytes);
    transmute::ReferenceEngine counting(count_image);
    initialize(counting, true);
    const auto complete_steps = counting.run().instructions;
    expect(complete_steps > 64 && complete_steps < 256,
           "pure-span fixture did not exercise the intended internal-loop extent");
    for (std::uint64_t budget = 1; budget <= complete_steps; ++budget) {
        auto reference_image = transmute::PeImage::parse(bytes);
        auto native_image = transmute::PeImage::parse(bytes);
        transmute::ReferenceEngine reference(reference_image);
        transmute::ReferenceEngine native(native_image);
        initialize(reference, true);
        initialize(native, true);
        native.set_jit_enabled(true);
        static_cast<void>(native.invoke_callback(native_image.entry(),
            std::span<const std::uint64_t>{}));
        const auto before = native.jit_executed_instructions();
        if (budget != complete_steps) {
            for (auto* engine : {&reference, &native}) {
                expect_failure([&] { static_cast<void>(engine->run(budget)); },
                               "guest exceeded instruction limit");
            }
            expect(native_region_same_state(native.state(), reference.state()) &&
                       native.jit_executed_instructions() == before + budget,
                   "pure span pre-accounted unexecuted effects or lost its short-budget fallback");
        }
        const auto expected = reference.run();
        const auto actual = native.run();
        expect(actual.instructions == expected.instructions &&
                   native_region_same_state(native.state(), reference.state()) &&
                   native.jit_executed_instructions() == before + complete_steps &&
                   native.jit_stats().compiled_native_regions == 1,
               "pure span could not resume an alias or internal branch with exact dynamic counts");
    }
    auto reference_image = transmute::PeImage::parse(bytes);
    auto native_image = transmute::PeImage::parse(bytes);
    transmute::ReferenceEngine reference(reference_image);
    transmute::ReferenceEngine native(native_image);
    initialize(reference, false);
    initialize(native, false);
    native.set_jit_enabled(true);
    for (auto* engine : {&reference, &native}) {
        expect_failure([&] { static_cast<void>(engine->run()); },
                       "guest read outside mapped memory");
    }
    expect(native_region_same_state(native.state(), reference.state()) &&
               native.state().pc == native_image.entry() + 21 * 4 &&
               native.jit_executed_instructions() == 21,
           "pure span lost its exact completed prefix at the following memory fault");
    for (auto* engine : {&reference, &native}) {
        engine->map_memory(data + 0x1000, 8);
        engine->write64(data + 0x1000, 43);
    }
    const auto expected = reference.run();
    const auto actual = native.run();
    expect(actual.instructions == expected.instructions &&
               native_region_same_state(native.state(), reference.state()),
           "pure span fault retry recounted or replayed an already committed register prefix");
#endif
}

void test_jit_fp_session_region_exits() {
#if defined(_WIN32) && (defined(_M_X64) || defined(__x86_64__))
    GuardedFpHostState restore;
    constexpr unsigned host_csr = 0x1f80U | 0x8040U | 0x2000U | 0x25U;
    constexpr std::uint64_t data = 0x500e00000ULL;
    // FDIV 1/3 contributes IX and FDIV 1/0 contributes DZ. The session must
    // publish both flags before any budget, memory, branch or checked exit.
    for (unsigned ending = 0; ending != 6; ++ending) {
        std::vector<std::uint32_t> words{
            0xd51b4414U, // msr fpcr,x20
            0xd51b4435U, // msr fpsr,x21
            0x1e621820U, // fdiv d0,d1,d2
            0x1e651883U, // fdiv d3,d4,d5
        };
        if (ending == 1) words.push_back(0xf940012aU); // ldr x10,[x9]
        if (ending == 2) words.push_back(0xf900012aU); // str x10,[x9]
        if (ending == 3) words.push_back(0xd53b4436U); // mrs x22,fpsr
        if (ending == 4) {
            words.push_back(0xf10006f7U); // subs x23,x23,#1
            words.push_back(0x54ffffa1U); // b.ne back to first FDIV
        }
        // BR exercises the returned-instruction exit with an arbitrary host
        // observer target. Other endings use RET, including straight fallthrough.
        words.push_back(ending == 5 ? 0xd61f02c0U : 0xd65f03c0U);
        const auto program = executable(words);
        const unsigned complete_steps = ending == 4 ? 19U
            : static_cast<unsigned>(words.size());
        for (unsigned budget = 1; budget <= complete_steps; ++budget) {
            auto reference_image = transmute::PeImage::parse(program);
            auto native_image = transmute::PeImage::parse(program);
            transmute::ReferenceEngine reference(reference_image);
            transmute::ReferenceEngine native(native_image);
            bool native_observed = false;
            for (auto* engine : {&reference, &native}) {
                engine->map_memory(data, 8);
                engine->write64(data, 0x123456789abcdef0ULL);
                engine->set_initial_register(9, data);
                engine->set_initial_register(10, 0xfedcba9876543210ULL);
                engine->set_initial_register(20, 0);
                engine->set_initial_register(21, 0x08000080U);
                engine->set_initial_register(23, 4);
                engine->set_initial_vector(1, {std::bit_cast<std::uint64_t>(1.0), 0});
                engine->set_initial_vector(2, {std::bit_cast<std::uint64_t>(3.0), 0});
                engine->set_initial_vector(4, {std::bit_cast<std::uint64_t>(1.0), 0});
                engine->set_initial_vector(5, {0, 0});
                if (ending == 5) {
                    const auto handler = engine->register_guest_call(
                        [&, engine](transmute::CpuState& state, transmute::GuestMemory&) {
                            expect(_mm_getcsr() == host_csr &&
                                       state.fpsr == 0x08000092U,
                                   "FP session leaked host state or delayed flags across a guest call");
                            if (engine == &native) native_observed = true;
                            state.pc = state.x[30];
                        });
                    engine->set_initial_register(22, handler);
                }
            }
            native.set_jit_enabled(true);
            if (budget < complete_steps) {
                for (auto* engine : {&reference, &native}) {
                    _mm_setcsr(host_csr);
                    expect_failure([&] { static_cast<void>(engine->run(budget)); },
                                   "guest exceeded instruction limit");
                    expect(_mm_getcsr() == host_csr,
                           "FP session failed to restore host state on a dynamic budget exit");
                }
                expect(native_region_same_state(native.state(), reference.state()),
                       "FP session lost a committed prefix at a budget or internal branch");
            }
            _mm_setcsr(host_csr);
            const auto expected = reference.run();
            expect(_mm_getcsr() == host_csr, "reference FP changed host control state");
            _mm_setcsr(host_csr);
            const auto actual = native.run();
            expect(_mm_getcsr() == host_csr &&
                       actual.instructions == expected.instructions &&
                       native_region_same_state(native.state(), reference.state()) &&
                       native.state().fpsr == 0x08000092U &&
                       (ending != 5 || native_observed),
                   "FP session changed final arithmetic, sticky flags or host control state");
            if (ending == 2) {
                expect(native.read64(data) == reference.read64(data),
                       "FP session finalization interfered with native store commit");
            }
        }
    }
    auto fault_image = transmute::PeImage::parse(executable({
        0x1e621820U, // fdiv d0,d1,d2, contributes IX
        0xf940012aU, // ldr x10,[x9], intentionally unmapped
        0xd65f03c0U}));
    transmute::ReferenceEngine faulting(fault_image);
    faulting.set_initial_vector(1, {std::bit_cast<std::uint64_t>(1.0), 0});
    faulting.set_initial_vector(2, {std::bit_cast<std::uint64_t>(3.0), 0});
    faulting.set_initial_register(9, data);
    faulting.set_initial_register(10, 17);
    faulting.set_jit_enabled(true);
    _mm_setcsr(host_csr);
    expect_failure([&] { static_cast<void>(faulting.run()); },
                   "guest read outside mapped memory");
    expect(_mm_getcsr() == host_csr && faulting.state().fpsr == 0x10U &&
               faulting.state().pc == fault_image.entry() + 4 &&
               faulting.state().x[10] == 17,
           "FP session lost its committed flags or leaked host state on a checked memory fault");
#endif
}

void test_jit_guarded_fp_warm_fallback_transition() {
#if defined(_WIN32) && (defined(_M_X64) || defined(__x86_64__))
    auto image = transmute::PeImage::parse(executable({
        0xd51b4414U, // msr fpcr,x20: trap policy stays a checked fallback
        0x1e622820U, // fadd d0,d1,d2
        0x9e660000U, // fmov x0,d0
        0xd65f03c0U}));
    transmute::ReferenceEngine reference(image);
    transmute::ReferenceEngine native(image);
    for (auto* engine : {&reference, &native}) {
        engine->set_initial_register(20, 1U << 8);
        engine->set_initial_vector(1, {std::bit_cast<std::uint64_t>(3.0), 0});
        engine->set_initial_vector(2, {std::bit_cast<std::uint64_t>(4.0), 0});
    }
    native.set_jit_enabled(true);
    const auto empty = std::span<const std::uint64_t>{};
    expect(native.invoke_callback(image.entry(), empty) ==
               reference.invoke_callback(image.entry(), empty),
           "guarded FP trap-policy fallback changed reference arithmetic");
    const auto before = native.jit_stats();
    expect(before.compiled_native_regions == 1 &&
               before.native_region_instructions == 2,
           "data-dependent FP bailout became a permanent negative cache entry");
    for (auto* engine : {&reference, &native})
        engine->set_initial_register(20, 0);
    expect(native.invoke_callback(image.entry(), empty) ==
               reference.invoke_callback(image.entry(), empty) &&
               native.jit_stats().native_region_instructions ==
                   before.native_region_instructions + 3 &&
               native.jit_stats().compiled_native_regions == 1,
           "guarded FP could not return to native execution after warming with trap policy");
#endif
}

class JitIntegerDifferential {
public:
    JitIntegerDifferential()
        : image_(transmute::PeImage::parse(executable({0xd65f03c0U}))),
          reference_(image_) {
        reference_.map_memory(code_, 4096);
        reference_.set_memory_access(code_, true, true, true);
        sink_ = reference_.register_guest_call([this](transmute::CpuState& state,
                                                     transmute::GuestMemory&) {
            observed_ = state;
            captured_ = true;
            state.x[30] = 0xfffffffffffffff0ULL;
        });
        reference_.set_initial_vector(7, {0x0123456789abcdefULL, UINT64_MAX});
        reference_.write32(code_, 0xd51b4214U); // msr nzcv,x20
        reference_.write32(code_ + 4, 0xaa1803feU); // mov x30,x24
        reference_.write32(code_ + 12, 0xd61f02a0U); // br x21, capturing all outputs
    }

    void check(std::uint32_t opcode, std::array<std::uint64_t, 31> registers,
               std::uint32_t nzcv, std::string_view family) {
        // Reserve probe-only registers; none of the matrix register forms use
        // X20/X21/X24. The sampled CCMP's X20 observes the same flags operand.
        registers[24] = registers[30];
        registers[20] = nzcv;
        registers[21] = sink_;
        for (unsigned index = 0; index < registers.size(); ++index) {
            reference_.set_initial_register(index, registers[index]);
        }
        reference_.write32(code_ + 8, opcode);
        auto state = reference_.state();
        state.pc = code_ + 8;
        state.sp = (state.sp - 256) & ~15ULL;
        state.nzcv = nzcv;
        state.fpcr = 0x01c00000U;
        state.fpsr = 0x0800009fU;
        const auto before = state;
        captured_ = false;
        static_cast<void>(reference_.invoke_callback(code_, std::span<const std::uint64_t>{}));
        if (!captured_ || !cache_.execute(state, code_ + 8, std::array{opcode}) ||
            state.x != observed_.x || state.sp != observed_.sp ||
            state.pc != code_ + 12 || state.nzcv != observed_.nzcv ||
            state.v != before.v || state.fpcr != before.fpcr || state.fpsr != before.fpsr) {
            throw std::runtime_error(std::string(family) +
                " JIT/reference mismatch for opcode " + std::to_string(opcode));
        }
        auto cached = before;
        expect(cache_.execute_cached(cached, cached.pc, 0, 0) == 0 &&
                   cached.x == before.x && cached.pc == before.pc &&
                   cached.nzcv == before.nzcv && cached.sp == before.sp,
               "new integer family crossed its cached instruction budget");
        expect(cache_.execute_cached(cached, cached.pc, 0, 1) == 1 &&
                   cached.x == state.x && cached.pc == state.pc &&
                   cached.nzcv == state.nzcv && cached.sp == state.sp &&
                   cached.v == before.v && cached.fpcr == before.fpcr &&
                   cached.fpsr == before.fpsr,
               "new cached integer family differs from its first execution");
    }

private:
    static constexpr std::uint64_t code_ = 0x500000000ULL;
    transmute::PeImage image_;
    transmute::ReferenceEngine reference_;
    transmute::X64BlockCache cache_;
    transmute::CpuState observed_{};
    std::uint64_t sink_{};
    bool captured_{};
};

std::array<std::uint64_t, 31> jit_integer_register_seed() {
    std::array<std::uint64_t, 31> registers{};
    for (unsigned index = 0; index < registers.size(); ++index) {
        registers[index] = 0xfedcba9876543210ULL ^ (0x123456789abcdefULL * index);
    }
    return registers;
}

void test_jit_move_inverse() {
    JitIntegerDifferential probe;
    unsigned flags = 0;
    for (const bool wide : {false, true}) {
        for (unsigned halfword = 0; halfword < (wide ? 4U : 2U); ++halfword) {
            for (const unsigned immediate : {0U, 1U, 0x8000U, 0xffffU}) {
                for (const unsigned destination : {0U, 8U, 30U, 31U}) {
                    const auto opcode = (wide ? 0x92800000U : 0x12800000U) |
                        (halfword << 21) | (immediate << 5) | destination;
                    probe.check(opcode, jit_integer_register_seed(), (flags++ & 15U) << 28, "MOVN");
                }
            }
        }
    }
    for (const auto opcode : {0x92f00008U, 0x92800000U}) {
        probe.check(opcode, jit_integer_register_seed(), 0xa0000000U, "sampled MOVN");
    }
    for (const auto opcode : {0x12c00000U, 0x12e00000U, 0x32800000U, 0xb2800000U}) {
        expect(!transmute::decode_integer_block(0x140001000ULL, std::array{opcode}),
               "MOVN decoder accepted a reserved form");
    }
}

void test_jit_signed_and_merge_bitfields() {
    JitIntegerDifferential probe;
    constexpr std::array forms{std::pair{8U, 9U}, std::pair{8U, 8U},
        std::pair{8U, 31U}, std::pair{31U, 8U}, std::pair{30U, 8U}};
    unsigned variant = 0;
    for (const bool wide : {false, true}) {
        const auto width = wide ? 64U : 32U;
        for (const unsigned operation : {0U, 1U, 2U}) {
            for (unsigned immr = 0; immr < width; ++immr) {
                for (unsigned imms = 0; imms < width; ++imms) {
                    const auto [destination, source] = forms[variant++ % forms.size()];
                    const auto opcode = 0x13000000U | (operation << 29) |
                        (wide ? 0x80400000U : 0U) | (immr << 16) |
                        (imms << 10) | (source << 5) | destination;
                    auto registers = jit_integer_register_seed();
                    registers[8] = variant & 1U ? 0x8000000080000001ULL : UINT64_MAX;
                    registers[9] = variant & 2U ? 0x123456789abcdef0ULL : 0;
                    probe.check(opcode, registers, (variant & 15U) << 28, "bitfield");
                }
            }
        }
        // Exercise both values of the extracted sign and preserve arbitrary
        // destination bits across BFI/BFXIL at every field boundary.
        for (const unsigned operation : {0U, 1U}) {
            for (const auto [immr, imms] : std::array{
                     std::pair{0U, 0U}, std::pair{0U, width - 1},
                     std::pair{width - 1, 0U}, std::pair{width - 1, width - 1},
                     std::pair{8U, 15U}, std::pair{width - 8, 7U}}) {
                for (const auto value : {0ULL, 1ULL, UINT64_MAX, 0x8000000080000080ULL}) {
                    auto registers = jit_integer_register_seed();
                    registers[9] = value;
                    const auto opcode = 0x13000000U | (operation << 29) |
                        (wide ? 0x80400000U : 0U) | (immr << 16) |
                        (imms << 10) | (9U << 5) | 8U;
                    probe.check(opcode, registers, 0x50000000U, "bitfield extrema");
                }
            }
        }
        for (const unsigned operation : {0U, 1U}) {
            const auto valid = 0x13000000U | (operation << 29) | (wide ? 0x80400000U : 0U);
            for (const auto invalid : {valid ^ 0x00400000U,
                    wide ? valid ^ 0x80000000U : valid | 0x00200000U,
                    wide ? valid ^ 0x00400000U : valid | 0x00008000U}) {
                expect(!transmute::decode_integer_block(0x140001000ULL, std::array{invalid}),
                       "new bitfield decoder accepted a reserved width/N encoding");
            }
        }
    }
    probe.check(0x93407eb6U, jit_integer_register_seed(), 0xa0000000U, "sampled SBFM");
}

void test_jit_integer_multiply_family() {
    struct Registers { unsigned destination, source, second, accumulator; };
    constexpr std::array forms{
        Registers{0, 8, 9, 10}, Registers{8, 8, 9, 10},
        Registers{9, 8, 9, 10}, Registers{10, 8, 9, 10},
        Registers{8, 8, 8, 8}, Registers{8, 8, 9, 8},
        Registers{9, 8, 9, 9}, Registers{8, 31, 9, 10},
        Registers{8, 8, 31, 10}, Registers{8, 8, 9, 31},
        Registers{31, 8, 9, 10}, Registers{30, 30, 9, 30},
        Registers{8, 31, 31, 31}};
    constexpr std::array bases{0x1b000000U, 0x1b008000U,
        0x9b000000U, 0x9b008000U, 0x9b200000U, 0x9b208000U,
        0x9ba00000U, 0x9ba08000U, 0x9b407c00U, 0x9bc07c00U};
    constexpr std::array values{0ULL, 1ULL, UINT64_MAX, 0x8000000080000000ULL,
        0x7fffffff7fffffffULL, 0xffffffff80000001ULL, 0x123456789abcdef0ULL};
    JitIntegerDifferential probe;
    unsigned flags = 0;
    for (const auto base : bases) {
        const bool high = (base & 0x00600000U) == 0x00400000U;
        for (const auto form : forms) {
            const auto opcode = base | (form.source << 5) | (form.second << 16) |
                (high ? 0U : form.accumulator << 10) | form.destination;
            for (unsigned index = 0; index < values.size(); ++index) {
                auto registers = jit_integer_register_seed();
                if (form.source != 31) registers[form.source] = values[index];
                if (form.second != 31) registers[form.second] = values[(index + 2) % values.size()];
                if (form.accumulator != 31 && !high) {
                    registers[form.accumulator] = values[(index + 4) % values.size()];
                }
                probe.check(opcode, registers, (flags++ & 15U) << 28, "multiply family");
            }
        }
    }
    probe.check(0x1b082673U, jit_integer_register_seed(), 0xf0000000U, "sampled MADD");
    for (const auto invalid : {0x3b000000U, 0x1b200000U, 0x1ba00000U,
                              0x1b407c00U, 0x9b400000U, 0x9bc00000U,
                              0x9b600000U, 0x9be00000U}) {
        expect(!transmute::decode_integer_block(0x140001000ULL, std::array{invalid}),
               "multiply decoder accepted a reserved form");
    }
}

void test_jit_conditional_compare_family() {
    JitIntegerDifferential probe;
    constexpr std::array values{0ULL, 1ULL, UINT64_MAX, 0x8000000080000000ULL,
        0x7fffffff7fffffffULL, 0x123456780000001fULL};
    for (const bool wide : {false, true}) {
        for (const bool subtract : {false, true}) {
            for (const bool immediate : {false, true}) {
                for (unsigned condition = 0; condition < 16; ++condition) {
                    for (unsigned flags = 0; flags < 16; ++flags) {
                        for (unsigned index = 0; index < values.size(); ++index) {
                            const auto source = index == 4 ? 31U : 8U;
                            const auto second = immediate ? (index * 7U) & 31U
                                : index == 3 ? 31U : index == 5 ? 8U : 9U;
                            const auto opcode = 0x3a400000U | (wide ? 0x80000000U : 0U) |
                                (subtract ? 0x40000000U : 0U) | (immediate ? 0x800U : 0U) |
                                (second << 16) | (condition << 12) | (source << 5) |
                                ((flags + index) & 15U);
                            auto registers = jit_integer_register_seed();
                            registers[8] = values[index];
                            registers[9] = values[(index + 1) % values.size()];
                            probe.check(opcode, registers, flags << 28, "conditional compare");
                        }
                    }
                }
            }
        }
    }
    probe.check(0x7a541104U, jit_integer_register_seed(), 0x20000000U, "sampled CCMP");
    for (const auto invalid : {0x1a400000U, 0x5a400800U, 0x3a400400U,
                              0x3a400c00U, 0x3a400010U, 0xfa600000U}) {
        expect(!transmute::decode_integer_block(0x140001000ULL, std::array{invalid}),
               "conditional compare decoder accepted reserved bits");
    }
}

void test_jit_pointer_authentication_disabled_hints() {
    JitIntegerDifferential probe;
    for (const auto opcode : {0xd503201fU, 0xd50320ffU, 0xd503233fU,
                             0xd503237fU, 0xd50323bfU, 0xd50323ffU}) {
        for (unsigned flags = 0; flags < 16; ++flags) {
            probe.check(opcode, jit_integer_register_seed(), flags << 28, "PAuth-disabled HINT");
        }
    }
    for (const auto opcode : {0xd503231fU, 0xd503235fU, 0xd503239fU,
                             0xd50323dfU, 0xd50330bfU, 0xd503309fU,
                             0xd50330dfU, 0xd65f0bffU, 0xd65f0fffU,
                             0xd61f0820U, 0xd63f0820U}) {
        expect(!transmute::decode_integer_block(0x140001000ULL, std::array{opcode}),
               "PAuth hint lowering admitted adjacent hints, barriers or authenticated control flow");
    }
}

void test_jit_direct_branch_link() {
    constexpr std::uint64_t pc = 0x140001000ULL;
    for (const auto opcode : {0x94000000U, 0x94000001U, 0x97ffffffU,
            0x96000000U, 0x95ffffffU, 0x9400146eU, 0x97fffe71U, 0x97fe765eU}) {
        transmute::X64BlockCache cache;
        const auto decoded = transmute::decode_integer_block(pc, std::array{opcode, 0xd503201fU});
        auto displacement = static_cast<std::int64_t>(opcode & 0x03ffffffU);
        if (displacement >= (1LL << 25)) displacement -= 1LL << 26;
        const auto target = pc + static_cast<std::uint64_t>(displacement * 4);
        expect(decoded && decoded->words.size() == 1 &&
                   decoded->instructions.front().op == transmute::BlockOp::branch_link &&
                   decoded->instructions.front().immediate == target,
               "BL decoder lost its signed target or block boundary");
        transmute::CpuState state{};
        state.x = jit_integer_register_seed();
        state.pc = pc;
        state.sp = 0x600000000ULL;
        state.nzcv = 0xa0000000U;
        const auto before = state;
        expect(cache.execute(state, pc, std::array{opcode, 0xd503201fU}) &&
                   state.x[30] == pc + 4 && state.pc == target &&
                   state.sp == before.sp && state.nzcv == before.nzcv,
               "BL JIT changed LR, target, SP or NZCV");
        auto expected_registers = before.x;
        expected_registers[30] = pc + 4;
        expect(state.x == expected_registers, "BL changed another guest register");
        auto cached = before;
        expect(cache.execute_cached(cached, pc, 0, 0) == 0 &&
                   cached.pc == before.pc && cached.x == before.x,
               "cached BL crossed its instruction budget");
        expect(cache.execute_cached(cached, pc, 0, 1) == 1 &&
                   cached.pc == target && cached.x == expected_registers,
               "cached BL changed its target or return link");
    }
    auto image = transmute::PeImage::parse(executable({
        0xaa1e03f6U, 0x94000006U, 0xaa1603feU, 0xd65f03c0U,
        0x91000c00U, 0xd65f03c0U, 0xd503201fU,
        0xaa1e03f7U, 0x97fffffcU, 0x91001400U, 0xaa1703feU, 0xd65f03c0U}));
    for (std::uint64_t budget = 1; budget <= 11; ++budget) {
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        optimized.set_jit_enabled(true);
        if (budget < 11) {
            expect_failure([&] { static_cast<void>(reference.run(budget)); }, "guest exceeded instruction limit");
            expect_failure([&] { static_cast<void>(optimized.run(budget)); }, "guest exceeded instruction limit");
        } else {
            const auto expected = reference.run(budget);
            const auto actual = optimized.run(budget);
            expect(actual.instructions == 11 && actual.instructions == expected.instructions &&
                       actual.exit_code == 8 && actual.exit_code == expected.exit_code &&
                       optimized.jit_executed_instructions() == 11,
                   "nested forward/backward BL did not execute wholly through JIT");
        }
        expect(optimized.state().x == reference.state().x &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().sp == reference.state().sp &&
                   optimized.state().nzcv == reference.state().nzcv &&
                   optimized.jit_executed_instructions() <= budget,
               "nested BL differs from reference at an instruction budget boundary");
    }
}

void test_jit_core_integer_batch_budgets() {
    const std::vector<std::uint32_t> words{
        0xd51b4214U, // initialize arbitrary NZCV through reference-only MSR
        0x92f00008U, 0x92800000U, 0x93407eb6U,
        0xb3400000U | (60U << 16) | (7U << 10) | (8U << 5) | 9U,
        0x1b082673U,
        0x9b200000U | (9U << 16) | (10U << 10) | (8U << 5) | 10U,
        0x9ba08000U | (9U << 16) | (10U << 10) | (8U << 5) | 10U,
        0x9b407c00U | (9U << 16) | (8U << 5) | 11U,
        0x7a541104U,
        0xba400800U | (31U << 16) | (10U << 12) | (8U << 5) | 15U,
        0xd503237fU, 0xd50323ffU, 0x1280001fU, 0xd65f03c0U};
    auto image = transmute::PeImage::parse(executable(words));
    for (std::uint64_t budget = 1; budget <= words.size(); ++budget) {
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        const auto registers = jit_integer_register_seed();
        for (auto* engine : {&reference, &optimized}) {
            for (unsigned index = 0; index < registers.size() - 1; ++index) {
                engine->set_initial_register(index, registers[index]);
            }
            engine->set_initial_register(20, 0xa0000000U);
            engine->set_initial_vector(7, {0x123456789abcdefULL, UINT64_MAX});
        }
        optimized.set_jit_enabled(true);
        if (budget < words.size()) {
            expect_failure([&] { static_cast<void>(reference.run(budget)); }, "guest exceeded instruction limit");
            expect_failure([&] { static_cast<void>(optimized.run(budget)); }, "guest exceeded instruction limit");
        } else {
            const auto expected = reference.run(budget);
            const auto actual = optimized.run(budget);
            expect(actual.instructions == words.size() && actual.instructions == expected.instructions &&
                       actual.exit_code == expected.exit_code &&
                       optimized.jit_executed_instructions() == words.size() - 1,
                   "mixed integer batch missed newly supported operations");
        }
        expect(optimized.state().x == reference.state().x &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().sp == reference.state().sp &&
                   optimized.state().nzcv == reference.state().nzcv &&
                   optimized.state().v == reference.state().v &&
                   optimized.state().fpcr == reference.state().fpcr &&
                   optimized.state().fpsr == reference.state().fpsr &&
                   optimized.jit_executed_instructions() <= budget,
               "mixed integer batch exceeded a runtime budget or changed architectural state");
    }
    const auto before_memory = transmute::decode_integer_block(image.entry(),
        std::array{0x92800000U, 0x93407eb6U, 0xf9400109U});
    const auto after_memory = transmute::decode_integer_block(image.entry(),
        std::array{0xf9400109U, 0x92800000U, 0x1b082673U, 0xf940010aU});
    expect(before_memory && before_memory->words.size() == 2 &&
               after_memory && after_memory->words.size() == 3,
           "integer expansion changed the JIT first-memory-operation contract");
}

void test_jit_bit_test_and_unconditional_branches() {
    const auto compare = [](std::uint32_t branch, std::uint64_t initial,
                            std::uint32_t expected_exit) {
        auto image = transmute::PeImage::parse(executable({
            0xd503201fU, // nop, so the JIT has a two-instruction block
            branch,      // skip the next instruction when taken
            0xd2800120U, // movz x0, #9
            0xd65f03c0U  // ret
        }));
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        reference.set_initial_register(0, initial);
        optimized.set_initial_register(0, initial);
        optimized.set_jit_enabled(true);
        const auto expected = reference.run();
        const auto actual = optimized.run();
        expect(actual.exit_code == expected_exit &&
                   actual.exit_code == expected.exit_code &&
                   actual.instructions == expected.instructions &&
                   optimized.state().x == reference.state().x &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().nzcv == reference.state().nzcv &&
                   optimized.jit_executed_instructions() >= 2,
               "opt-in JIT bit-test/unconditional branch differs from interpreter");
    };
    compare(0x36180040U, 0, 0);               // tbz w0, #3, +8: taken
    compare(0x36180040U, 8, 9);               // tbz w0, #3, +8: not taken
    compare(0xb7180040U, 1ULL << 35, 0);     // tbnz x0, #35, +8: taken
    compare(0xb7180040U, 0, 9);               // tbnz x0, #35, +8: not taken
    compare(0x14000002U, 5, 5);               // b +8
}

void test_jit_register_branches() {
    const auto compare = [](std::vector<std::uint32_t> words,
                            std::size_t target_index,
                            std::uint32_t expected_exit) {
        auto image = transmute::PeImage::parse(executable(words));
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        for (auto* engine : {&reference, &optimized}) {
            engine->set_initial_register(1, image.entry() + target_index * 4);
        }
        optimized.set_jit_enabled(true);
        const auto expected = reference.run();
        const auto actual = optimized.run();
        expect(actual.exit_code == expected_exit &&
                   actual.exit_code == expected.exit_code &&
                   actual.instructions == expected.instructions &&
                   optimized.state().x == reference.state().x &&
                   optimized.state().sp == reference.state().sp &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().nzcv == reference.state().nzcv &&
                   optimized.jit_executed_instructions() >= 2,
               "JIT BR/BLR differs from ReferenceEngine");
    };
    compare({0xd28000e0U, // movz x0,#7
             0xd61f0020U, // br x1
             0xd2800120U, // movz x0,#9 (skipped)
             0xd65f03c0U}, 3, 7);
    compare({0xaa1e03e2U, // mov x2,x30: preserve caller link
             0xd63f0020U, // blr x1
             0x91000800U, // add x0,x0,#2
             0xaa0203feU, // mov x30,x2
             0xd65f03c0U, // ret
             0xd28000e0U, // callee: movz x0,#7
             0xd65f03c0U}, 5, 9);
    compare({0xaa1e03e2U, // mov x2,x30
             0xaa0103feU, // mov x30,x1
             0xd503201fU, // nop
             0xd63f03c0U, // blr x30: target is old LR
             0xaa0203feU, // mov x30,x2
             0xd65f03c0U, // ret
             0xd28000e0U, // callee: movz x0,#7
             0xd65f03c0U}, 6, 7);
    const auto decoded = transmute::decode_integer_block(
        0x140001000ULL, std::array{0xd503201fU, 0xd63f03c0U});
    expect(decoded && decoded->instructions.size() == 2 &&
               decoded->instructions.back().op ==
                   transmute::BlockOp::branch_link_register &&
               decoded->instructions.back().source == 30,
           "JIT did not terminate its block at BLR X30");
    expect(!transmute::decode_integer_block(
               0x140001000ULL, std::array{0xd61f0021U}),
           "JIT accepted reserved BR register bits");
}

void test_jit_byte_memory_access() {
    constexpr std::uint64_t data = 0x500000000ULL;
    const auto compare = [=](std::vector<std::uint32_t> words,
                            std::uint64_t initial_x8,
                            std::array<std::uint8_t, 4> initial_bytes,
                            std::uint64_t expected_x8,
                            std::uint64_t expected_x9,
                            std::array<std::uint8_t, 4> expected_bytes) {
        auto image = transmute::PeImage::parse(executable(words));
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        for (auto* engine : {&reference, &optimized}) {
            engine->map_memory(data, 4096);
            auto& memory = static_cast<transmute::GuestMemory&>(*engine);
            for (std::size_t index = 0; index < initial_bytes.size(); ++index) {
                memory.write8(data + index, initial_bytes[index]);
            }
            engine->set_initial_register(8, initial_x8);
            engine->set_initial_register(9, data + 1);
        }
        optimized.set_jit_enabled(true);
        const auto expected = reference.run();
        const auto actual = optimized.run();
        expect(actual.exit_code == expected.exit_code &&
                   actual.instructions == expected.instructions &&
                   optimized.state().x == reference.state().x &&
                   optimized.state().sp == reference.state().sp &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().nzcv == reference.state().nzcv &&
                   optimized.state().x[8] == expected_x8 &&
                   optimized.state().x[9] == expected_x9 &&
                   optimized.jit_executed_instructions() >= 1,
               "JIT byte memory access or writeback differs from ReferenceEngine");
        for (std::size_t index = 0; index < expected_bytes.size(); ++index) {
            expect(static_cast<transmute::GuestMemory&>(optimized).read8(
                       data + index) == expected_bytes[index] &&
                       static_cast<transmute::GuestMemory&>(reference).read8(
                       data + index) == expected_bytes[index],
                   "JIT byte memory access changed guest data");
        }
    };
    compare({0x38401528U, // ldrb w8,[x9],#1
             0x35ffffe8U, // cbnz w8,-4
             0x2a0803e0U, // mov w0,w8
             0xd65f03c0U}, 0, {0, 1, 2, 0}, 0, data + 4,
            {0, 1, 2, 0});
    compare({0x385ffd29U, // ldrb w9,[x9,#-1]!: writeback wins alias
             0xaa0903e0U, // mov x0,x9
             0xd65f03c0U}, 0x1234, {0x5a, 0, 0, 0}, 0x1234,
            data, {0x5a, 0, 0, 0});
    compare({0x39400928U, // ldrb w8,[x9,#2]
             0x2a0803e0U, // mov w0,w8
             0xd65f03c0U}, 0, {0, 0, 0, 0x7b}, 0x7b,
            data + 1, {0, 0, 0, 0x7b});
    compare({0x38001528U, // strb w8,[x9],#1
             0xaa0903e0U, // mov x0,x9
             0xd65f03c0U}, 0x1234ab, {0, 0, 0, 0}, 0x1234ab,
            data + 2, {0, 0xab, 0, 0});
    compare({0x381ffd29U, // strb w9,[x9,#-1]!: source is old base
             0xaa0903e0U, // mov x0,x9
             0xd65f03c0U}, 0, {0, 0, 0, 0}, 0,
            data, {1, 0, 0, 0});
    compare({0x39000928U, // strb w8,[x9,#2]
             0xaa0903e0U, // mov x0,x9
             0xd65f03c0U}, 0x1234ab, {0, 0, 0, 0}, 0x1234ab,
            data + 1, {0, 0, 0, 0xab});

    for (const auto [opcode, readable, writable, error] :
         std::array<std::tuple<std::uint32_t, bool, bool, const char*>, 4>{
             std::tuple{0x38401528U, true, true,
                        "guest read outside mapped memory"},
             std::tuple{0x38001528U, true, true,
                        "guest write outside mapped memory"},
             std::tuple{0x38401528U, false, true,
                        "guest read from inaccessible mapped memory"},
             std::tuple{0x38001528U, true, false,
                        "guest write to read-only mapped memory"}}) {
        auto image = transmute::PeImage::parse(executable({opcode, 0xd65f03c0U}));
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        const bool mapped = !readable || !writable;
        for (auto* engine : {&reference, &optimized}) {
            if (mapped) {
                engine->map_memory(data, 4096);
                engine->set_memory_access(data, readable, writable, false);
            }
            engine->set_initial_register(8, 0x5a);
            engine->set_initial_register(9, data);
        }
        optimized.set_jit_enabled(true);
        expect_failure([&] { static_cast<void>(reference.run()); }, error);
        expect_failure([&] { static_cast<void>(optimized.run()); }, error);
        expect(optimized.state().x == reference.state().x &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().sp == reference.state().sp,
               "JIT byte-memory fault changed registers before fallback");
    }
    auto cache_image = transmute::PeImage::parse(executable({0xd65f03c0U}));
    transmute::ReferenceEngine cache_memory(cache_image);
    cache_memory.map_memory(data, 4096);
    static_cast<transmute::GuestMemory&>(cache_memory).write8(data, 0x5a);
    transmute::X64BlockCache cache;
    transmute::CpuState first{};
    first.pc = cache_image.entry();
    first.x[9] = data;
    const std::array load_words{0x38401528U, 0xd65f03c0U};
    expect(cache.execute(first, cache_image.entry(), load_words, 0,
                         &cache_memory) &&
               first.x[8] == 0x5a && first.x[9] == data + 1,
           "JIT byte load did not populate the executable cache");
    cache_memory.set_memory_access(data, false, false, false);
    transmute::CpuState protected_state{};
    protected_state.pc = cache_image.entry();
    protected_state.x[8] = 0x1234;
    protected_state.x[9] = data;
    expect(cache.execute_cached(protected_state, cache_image.entry(), 0, 2,
                                nullptr, &cache_memory) == 0 &&
               protected_state.pc == cache_image.entry() &&
               protected_state.x[8] == 0x1234 &&
               protected_state.x[9] == data,
           "JIT cached byte load changed state before a permission fault");
    cache_memory.set_memory_access(data, true, true, false);
    cache_memory.unmap_memory(data);
    cache_memory.map_memory(data, 4096);
    static_cast<transmute::GuestMemory&>(cache_memory).write8(data, 0xa5);
    transmute::CpuState remapped_state{};
    remapped_state.pc = cache_image.entry();
    remapped_state.x[9] = data;
    expect(cache.execute_cached(remapped_state, cache_image.entry(), 0, 2,
                                nullptr, &cache_memory) == 2 &&
               remapped_state.x[8] == 0xa5,
           "JIT cached byte load used stale mapped data after remapping");
    expect(transmute::decode_integer_block(
               0x140001000ULL, std::array{0x38c01528U}).has_value(),
           "JIT did not decode a signed byte load with postindex writeback");
}

void test_jit_mapped_fast_access_contract() {
    constexpr std::uint64_t data = 0x500000000ULL;
    constexpr std::uint64_t code = data + 0x10000;
    auto image = transmute::PeImage::parse(executable({0xd65f03c0U}));
    transmute::ReferenceEngine engine(image);
    auto& memory = static_cast<transmute::GuestMemory&>(engine);
    engine.map_memory(data, 8);
    expect(memory.try_write_mapped(data, 8, 0x8877665544332211ULL) &&
               memory.try_read_mapped(data, 8) ==
                   0x8877665544332211ULL &&
               !memory.try_read_mapped(data + 4, 8) &&
               !memory.try_write_mapped(data + 4, 8, 0),
           "JIT mapped fast access crossed a region boundary");
    engine.set_memory_access(data, false, false, false);
    expect(!memory.try_read_mapped(data, 1) &&
               !memory.try_write_mapped(data, 1, 0),
           "JIT mapped fast access ignored changed permissions");
    engine.set_memory_access(data, true, true, false);
    engine.unmap_memory(data);
    engine.map_memory(data, 8);
    expect(memory.try_read_mapped(data, 8) == 0 &&
               memory.try_write_mapped(data, 4, 0xaabbccddU) &&
               engine.read32(data) == 0xaabbccddU,
           "JIT mapped fast access reused a stale region after remapping");

    std::array<std::uint8_t, 8> external{};
    engine.map_external_memory(data + 0x1000, external.data(),
                               external.size(), true);
    expect(memory.try_write_mapped(data + 0x1000, 8,
                                   0x0807060504030201ULL) &&
               external[0] == 1 && external[7] == 8 &&
               memory.try_read_mapped(data + 0x1000, 8) ==
                   0x0807060504030201ULL,
           "JIT mapped fast access lost external-memory coherency");

    engine.map_memory(code, 4096);
    engine.set_memory_access(code, true, true, true);
    expect(memory.try_write_mapped(code, 4, 0xd2800020U) &&
               memory.try_write_mapped(code + 4, 4, 0xd65f03c0U),
           "JIT mapped fast access could not initialize executable code");
    engine.set_jit_enabled(true);
    expect(engine.invoke_callback(code, 0) == 1 &&
               memory.try_write_mapped(code, 4, 0xd2800040U) &&
               engine.invoke_callback(code, 0) == 2,
           "JIT mapped fast write failed to invalidate executable code");
}

void test_contiguous_memory_access() {
    constexpr std::uint64_t mapped = 0x500000000ULL;
    constexpr std::uint64_t value = 0x8877665544332211ULL;
    auto bytes = executable({0xd2800020U, 0xd65f03c0U});
    put32(bytes, 0x188 + 36, 0xe0000020);
    put32(bytes, 0x188 + 8, 0x1000);
    auto image = transmute::PeImage::parse(bytes);
    transmute::ReferenceEngine engine(image);
    auto& memory = static_cast<transmute::GuestMemory&>(engine);
    engine.map_memory(mapped, 64);
    const auto image_data = image.base() + 0x1101;
    for (const unsigned width : {1U, 2U, 4U, 8U}) {
        const auto mask = width == 8 ? UINT64_MAX : (1ULL << (width * 8)) - 1;
        for (const auto address : {mapped + 1, image_data}) {
            expect(memory.try_write_contiguous(address, width, value) &&
                       memory.try_read_contiguous(address, width) == (value & mask),
                   "contiguous memory access changed unaligned width or endian behavior");
        }
        expect(image.try_read_contiguous(image_data, width) == (value & mask),
               "PE whole-width read changed its byte representation");
    }
    expect(!memory.try_read_mapped(image_data, 8) &&
               !memory.try_write_mapped(image_data, 8, 0),
           "image-aware access changed the mapped-only API contract");
    for (const unsigned invalid : {0U, 3U, 16U}) {
        expect(!memory.try_read_contiguous(mapped, invalid) &&
                   !memory.try_write_contiguous(mapped, invalid, 0) &&
                   !memory.try_read_contiguous(image_data, invalid) &&
                   !memory.try_write_contiguous(image_data, invalid, 0),
               "contiguous access accepted an unsupported width");
    }
    expect(!memory.try_write_contiguous(mapped + 60, 8, value) &&
               engine.read32(mapped + 60) == 0,
           "contiguous boundary rejection wrote part of its value");
    expect_failure([&] { engine.write64(mapped + 60, value); },
                   "guest write outside mapped memory");
    expect(engine.read32(mapped + 60) == 0x44332211,
           "wide reference boundary fault lost its prior partial-write behavior");
    const auto image_end = image.base() + image.size();
    expect(!memory.try_read_contiguous(image_end - 4, 8) &&
               !memory.try_write_contiguous(image_end - 4, 8, value),
           "contiguous access crossed the PE image extent");
    expect_failure([&] { engine.write64(image_end - 4, value); },
                   "guest write outside mapped memory");
    expect(engine.read32(image_end - 4) == 0x44332211,
           "wide PE boundary fault lost its prior partial-write behavior");
    engine.map_memory(mapped + 0x1000, 4);
    engine.map_memory(mapped + 0x1004, 4);
    expect(!memory.try_write_contiguous(mapped + 0x1000, 8, value),
           "contiguous access combined separate memory regions");
    engine.write64(mapped + 0x1000, value);
    expect(engine.read64(mapped + 0x1000) == value,
           "wide reference access failed across adjacent valid mappings");
    engine.set_memory_access(mapped, false, false, false);
    expect(!memory.try_read_contiguous(mapped, 4) &&
               !memory.try_write_contiguous(mapped, 4, value),
           "contiguous access ignored a protection change");
    engine.set_memory_access(mapped, true, true, false);
    engine.unmap_memory(mapped);
    engine.map_memory(mapped, 64);
    expect(memory.try_read_contiguous(mapped, 8) == 0,
           "contiguous access reused a stale mapping after unmap/remap");
    std::array<std::uint8_t, 16> external{};
    engine.map_external_memory(mapped + 0x2000, external.data(), external.size(), true);
    expect(memory.try_write_contiguous(mapped + 0x2001, 8, value) &&
               external[1] == 0x11 && external[8] == 0x88 &&
               memory.try_read_contiguous(mapped + 0x2001, 8) == value,
           "contiguous access lost external backing coherency");
    engine.set_jit_enabled(true);
    expect(engine.invoke_callback(image.entry(), 0) == 1 &&
               memory.try_write_contiguous(image.entry(), 4, 0xd2800040U) &&
               engine.invoke_callback(image.entry(), 0) == 2,
           "contiguous PE write failed to invalidate translated code");
    engine.write32(image.entry(), 0xd2800060U);
    expect(engine.invoke_callback(image.entry(), 0) == 3,
           "wide reference PE write failed to invalidate translated code");

    auto short_bytes = bytes;
    put32(short_bytes, 0x188 + 8, 0x100);
    put32(short_bytes, 0x188 + 16, 0x100);
    auto short_image = transmute::PeImage::parse(short_bytes);
    transmute::ReferenceEngine short_engine(short_image);
    const auto section_end = short_image.base() + 0x1100;
    expect(!short_engine.try_write_contiguous(section_end - 2, 4, value),
           "contiguous PE write crossed a writable section boundary");
    expect_failure([&] { short_engine.write32(section_end - 2, 0x44332211); },
                   "guest write to read-only PE memory");
    expect(short_image.read8(section_end - 2) == 0x11 &&
               short_image.read8(section_end - 1) == 0x22 &&
               short_image.read8(section_end) == 0,
           "PE section fault changed the bytes written before the fault");
}

void test_contiguous_memory_reservations() {
    constexpr std::uint64_t mapped = 0x500000000ULL;
    for (const bool image_memory : {false, true}) {
        for (const bool same_granule : {false, true}) {
            for (const unsigned width : {1U, 2U, 4U, 8U}) {
                auto bytes = executable({0xc85ffc81U, 0xc803fc82U, 0xd65f03c0U});
                put32(bytes, 0x188 + 36, 0xe0000020);
                auto image = transmute::PeImage::parse(bytes);
                transmute::ReferenceEngine engine(image);
                engine.map_memory(mapped, 64);
                const auto address = image_memory ? image.base() + 0x1100 : mapped;
                engine.write64(address, 42);
                engine.set_initial_register(2, 99);
                engine.set_initial_register(4, address);
                expect_failure([&] { static_cast<void>(engine.run(1)); },
                               "guest exceeded instruction limit");
                auto worker = engine.fork_thread(image.entry(), 0);
                expect(worker->try_write_contiguous(
                           address + (same_granule ? 12 : 20), width, 0xa5),
                       "contiguous reservation fixture write failed");
                static_cast<void>(engine.run());
                expect(engine.state().x[3] == (same_granule ? 1U : 0U) &&
                           engine.read64(address) == (same_granule ? 42U : 99U),
                       "contiguous write changed cross-engine exclusive granule behavior");
            }
        }
    }
}

void test_owned_mapped_write_revisions() {
    constexpr std::uint64_t data = 0x500100000ULL;
    constexpr std::uint64_t value = 0x8877665544332211ULL;
    auto image = transmute::PeImage::parse(executable({
        0xf9000001U, // str x1,[x0]
        0xd65f03c0U
    }));
    transmute::ReferenceEngine engine(image);
    auto& memory = static_cast<transmute::GuestMemory&>(engine);
    engine.map_memory(data, 64);
    engine.map_memory(data + 0x1000, 64);
    auto revision = memory.write_revision(data, 64);
    expect(revision && *revision != 0 &&
               memory.write_revision(data + 1, 8) == revision &&
               memory.write_revision(data + 0x1000, 64) != revision &&
               !memory.GuestMemory::write_revision(data, 64),
           "owned mapping revision identity or unsupported default is wrong");
    for (const unsigned width : {1U, 2U, 4U, 8U}) {
        expect(memory.try_write_contiguous(data + 1, width, value),
               "revision width fixture store failed");
        const auto changed = memory.write_revision(data, 64);
        expect(changed && *changed > *revision &&
                   memory.write_revision(data, 64) == changed,
               "whole-width write did not advance a stable owned mapping revision");
        revision = changed;
    }
    const auto byte = memory.read8(data + 1);
    expect(memory.write_revision(data, 64) == revision,
           "guest read changed an owned mapping revision");
    memory.write8(data + 1, byte);
    expect(memory.write_revision(data, 64) > revision,
           "successful byte write did not advance owned revision");
    revision = memory.write_revision(data, 64);
    engine.write32(data, 43);
    expect(memory.write_revision(data, 64) > revision,
           "checked word write did not advance owned revision");
    revision = memory.write_revision(data, 64);
    engine.write64(data, value);
    expect(memory.write_revision(data, 64) > revision,
           "checked wide write did not advance owned revision");
    revision = memory.write_revision(data, 64);
    engine.write64(data + 0x1000, value);
    expect(memory.write_revision(data, 64) == revision,
           "unrelated mapping write changed another region's revision");
    expect(!memory.try_write_contiguous(data + 60, 8, value) &&
               memory.write_revision(data, 64) == revision &&
               !memory.write_revision(data + 60, 8) &&
               !memory.write_revision(data, 0) &&
               !memory.write_revision(UINT64_MAX - 1, 8),
           "rejected or boundary-spanning access changed its owned revision");
    expect_failure([&] { engine.write64(data + 60, value); },
                   "guest write outside mapped memory");
    expect(memory.write_revision(data, 64) > revision &&
               engine.read32(data + 60) == 0x44332211,
           "partial fault did not record successful prefix writes");
    revision = memory.write_revision(data, 64);
    engine.set_memory_access(data, true, false, false);
    expect_failure([&] { memory.write8(data, 1); },
                   "guest write to read-only mapped memory");
    expect(memory.write_revision(data, 64) == revision,
           "faulting read-only write changed an owned revision");
    engine.set_memory_access(data, false, false, false);
    expect(!memory.write_revision(data, 64),
           "revision API accepted unreadable memory");
    engine.set_memory_access(data, true, true, false);
    expect(memory.write_revision(data, 64) == revision,
           "permission changes altered unchanged buffer contents");
    engine.unmap_memory(data);
    expect(!memory.write_revision(data, 64),
           "revision API reused an unmapped region hint");
    engine.map_memory(data, 64);
    expect(memory.write_revision(data, 64) > revision && engine.read64(data) == 0,
           "remapped owned region reused its old content identity");
    revision = memory.write_revision(data, 64);
    auto worker = engine.fork_thread(image.entry(), data);
    worker->set_initial_register(1, value);
    worker->set_jit_enabled(true);
    expect(memory.write_revision(data, 64) == revision,
           "worker stack mapping changed an unrelated buffer revision");
    std::exception_ptr worker_fault;
    std::thread guest_worker([&] {
        try { static_cast<void>(worker->run()); }
        catch (...) { worker_fault = std::current_exception(); }
    });
    guest_worker.join();
    if (worker_fault) std::rethrow_exception(worker_fault);
    expect(worker->jit_executed_instructions() >= 1 &&
               memory.write_revision(data, 64) > revision && engine.read64(data) == value,
           "scoped translated worker store did not publish its shared buffer revision");
    std::array<std::uint8_t, 16> external{};
    engine.map_external_memory(data + 0x2000, external.data(), external.size(), true);
    engine.write64(data + 0x2000, value);
    expect(!memory.write_revision(data + 0x2000, 8) &&
               !memory.write_revision(image.entry(), 4),
           "revision API promised tracking for external or image memory");
}

void test_scoped_jit_memory_virtual_contract() {
    constexpr std::uint64_t data = 0x500100000ULL;
    auto image = transmute::PeImage::parse(executable({
        0xb9400000U, // ldr w0,[x0]
        0xb9000020U, // str w0,[x1]
        0xd65f03c0U
    }));
    struct InstrumentedEngine final : transmute::ReferenceEngine {
        using ReferenceEngine::ReferenceEngine;
        mutable unsigned reads{};
        mutable unsigned revisions{};
        unsigned writes{};
        std::optional<std::uint64_t> write_revision(
            std::uint64_t, std::uint64_t) const override {
            ++revisions;
            return std::nullopt;
        }
        std::optional<std::uint64_t> try_read_contiguous(
            std::uint64_t address, unsigned bytes) const override {
            ++reads;
            const auto value = ReferenceEngine::try_read_contiguous(address, bytes);
            return value ? std::optional<std::uint64_t>{*value + 1} : std::nullopt;
        }
        bool try_write_contiguous(std::uint64_t address, unsigned bytes,
                                  std::uint64_t value) override {
            ++writes;
            return ReferenceEngine::try_write_contiguous(address, bytes, value + 1);
        }
    } engine(image);
    engine.map_memory(data, 16);
    engine.write32(data, 40);
    engine.set_initial_register(0, data);
    engine.set_initial_register(1, data + 8);
    engine.set_jit_enabled(true);
    const auto result = engine.run();
    const auto revision = static_cast<transmute::GuestMemory&>(engine).write_revision(data, 8);
    expect(result.exit_code == 41 && engine.read32(data + 8) == 42 &&
               engine.reads == 1 && engine.writes == 1 && !revision && engine.revisions == 1 &&
               engine.jit_executed_instructions() >= 2,
           "scoped JIT memory bypassed a derived engine's virtual contract");
}

void test_scoped_jit_memory_worker_reservations() {
    constexpr std::uint64_t mapped = 0x500100000ULL;
    for (const bool image_memory : {false, true}) {
        for (const bool same_granule : {false, true}) {
            for (const auto opcode : {0x39000001U, 0x79000001U,
                                      0xb9000001U, 0xf9000001U}) {
                auto bytes = executable({
                    0xc85ffc81U, // ldaxr x1,[x4]
                    0xc803fc82U, // stlxr w3,x2,[x4]
                    0xd65f03c0U,
                    opcode, // worker strb/strh/str w1/x1,[x0]
                    0xd65f03c0U
                });
                put32(bytes, 0x188 + 36, 0xe0000020);
                auto image = transmute::PeImage::parse(bytes);
                transmute::ReferenceEngine engine(image);
                engine.map_memory(mapped, 64);
                const auto data = image_memory ? image.base() + 0x1100 : mapped;
                engine.write64(data, 42);
                engine.set_initial_register(2, 99);
                engine.set_initial_register(4, data);
                expect_failure([&] { static_cast<void>(engine.run(1)); },
                               "guest exceeded instruction limit");
                auto worker = engine.fork_thread(image.entry() + 12,
                    data + (same_granule ? 0 : 32));
                worker->set_initial_register(1, 43);
                worker->set_jit_enabled(true);
                std::exception_ptr worker_fault;
                std::thread guest_worker([&] {
                    try { static_cast<void>(worker->run()); }
                    catch (...) { worker_fault = std::current_exception(); }
                });
                guest_worker.join();
                if (worker_fault) std::rethrow_exception(worker_fault);
                static_cast<void>(engine.run());
                expect(worker->jit_executed_instructions() >= 1 &&
                           engine.state().x[3] == (same_granule ? 1U : 0U) &&
                           engine.read64(data) == (same_granule ? 43U : 99U),
                       "scoped JIT worker store changed exclusive reservation behavior");
            }
        }
    }
}

void test_native_read_lease_lifetime() {
    constexpr std::uint64_t object = 0x500200000ULL;
    // Include a page-tag collision, so refilling the dependent second load
    // cannot restart the preceding load or require both entries simultaneously.
    for (const auto separation : {0x1000ULL, 0x40000ULL}) {
        const auto leaf = object + separation;
        auto image = transmute::PeImage::parse(executable({
            0xf9401c08U, // ldr x8,[x0,#0x38]
            0xf9400100U, // ldr x0,[x8]
            0xd65f03c0U
        }));
        transmute::ReferenceEngine engine(image);
        engine.set_jit_enabled(true);
        engine.map_memory(object, 64);
        engine.map_memory(leaf, 32);
        engine.write64(object + 56, leaf + 1);
        engine.write64(leaf + 1, 42);
        const auto call = [&] { return engine.invoke_callback(image.entry(), object); };
        expect(call() == 42 && call() == 42,
               "native read lease changed dependent loads or a page-tag collision");
        engine.set_memory_access(leaf, true, false, false);
        expect(call() == 42, "native read lease imposed write permission on a read");
        engine.set_memory_access(leaf, false, false, false);
        expect_failure([&] { static_cast<void>(call()); },
                       "guest read from inaccessible mapped memory");
        engine.set_memory_access(leaf, true, true, false);
        for (std::uint64_t value = 43; value != 75; ++value) {
            engine.unmap_memory(leaf);
            engine.map_memory(leaf, 32);
            engine.write64(leaf + 1, value);
            expect(call() == value, "native read lease reused an unmapped host span");
        }
        engine.unmap_memory(leaf);
        std::array<std::uint8_t, 32> external{};
        engine.map_external_memory(leaf, external.data(), external.size(), true);
        engine.write64(leaf + 1, 75);
        expect(call() == 75, "native read lease lost the external-memory checked fallback");
        engine.unmap_memory(leaf);
        engine.map_memory(leaf, 4);
        engine.map_memory(leaf + 4, 4);
        engine.write64(object + 56, leaf);
        engine.write64(leaf, 0x8877665544332211ULL);
        expect(call() == 0x8877665544332211ULL,
               "native read lease failed a checked load spanning adjacent mappings");
        engine.unmap_memory(leaf + 4);
        expect_failure([&] { static_cast<void>(call()); },
                       "guest read outside mapped memory");
        engine.write64(object + 56, image.base() + image.size() - 8);
        expect(call() == 0,
               "native image read lease excluded zero-filled bytes outside PE sections");
    }

    // A staged image can be discarded and destroyed before another owner is
    // mapped at exactly the same guest address. Its borrowed bytes must expire.
    constexpr std::uint64_t module_base = 0x180000000ULL;
    auto image = transmute::PeImage::parse(executable({
        0xf9401c08U, 0xf9400100U, 0xd65f03c0U}));
    transmute::ReferenceEngine engine(image);
    engine.set_jit_enabled(true);
    engine.map_memory(object, 64);
    engine.write64(object + 56, module_base + 0x1100);
    {
        auto bytes = executable({0xd65f03c0U});
        put16(bytes, 0x96, 0x2000);
        put64(bytes, 0x98 + 24, module_base);
        put64(bytes, 0x300, 123);
        auto module = transmute::PeImage::parse(bytes);
        engine.stage_module(module);
        expect(engine.invoke_callback(image.entry(), object) == 123 &&
                   engine.invoke_callback(image.entry(), object) == 123,
               "native read lease could not use a staged PE image");
        engine.discard_staged_modules();
    }
    engine.map_memory(module_base, 0x2000);
    engine.write64(module_base + 0x1100, 456);
    expect(engine.invoke_callback(image.entry(), object) == 456,
           "native read lease retained a destroyed staged image");
}

void test_native_read_lease_worker_reclamation() {
    constexpr std::uint64_t object = 0x500200000ULL;
    constexpr std::uint64_t leaf = object + 0x1000;
    auto image = transmute::PeImage::parse(executable({
        0xf9401c08U, 0xf9400100U, 0xd65f03c0U}));
    transmute::ReferenceEngine engine(image);
    engine.set_jit_enabled(true);
    engine.map_memory(object, 64);
    engine.map_memory(leaf, 32);
    engine.write64(object + 56, leaf + 1);
    engine.write64(leaf + 1, 42);
    expect(engine.invoke_callback(image.entry(), object) == 42,
           "native read reclamation fixture did not warm its load");
    auto worker = engine.fork_thread(image.entry(), object);
    std::atomic<bool> start{};
    std::exception_ptr worker_fault;
    std::thread mapping_worker([&] {
        while (!start.load(std::memory_order_acquire)) std::this_thread::yield();
        try {
            for (unsigned iteration = 0; iteration != 1000; ++iteration) {
                worker->unmap_memory(leaf);
                worker->map_memory(leaf, 32);
                worker->write64(leaf + 1, 42 + (iteration & 1U));
            }
        } catch (...) { worker_fault = std::current_exception(); }
    });
    start.store(true, std::memory_order_release);
    std::exception_ptr reader_fault;
    try {
        for (unsigned iteration = 0; iteration != 1000; ++iteration) {
            try {
                const auto value = engine.invoke_callback(image.entry(), object);
                expect(value == 0 || value == 42 || value == 43,
                       "native read observed freed or partially written mapping bytes");
            } catch (const std::runtime_error& error) {
                if (std::string_view(error.what()).find("guest read outside mapped memory") ==
                    std::string_view::npos) throw;
            }
        }
    } catch (...) { reader_fault = std::current_exception(); }
    mapping_worker.join();
    if (worker_fault) std::rethrow_exception(worker_fault);
    if (reader_fault) std::rethrow_exception(reader_fault);
}

void test_jit_image_contiguous_access() {
    for (const auto [store, load, width] :
         std::array<std::tuple<std::uint32_t, std::uint32_t, unsigned>, 4>{
             std::tuple{0x39000128U, 0x3940012aU, 1U},
             std::tuple{0x79000128U, 0x7940012aU, 2U},
             std::tuple{0xb9000128U, 0xb940012aU, 4U},
             std::tuple{0xf9000128U, 0xf940012aU, 8U}}) {
        auto bytes = executable({store, load, 0xd65f03c0U});
        put32(bytes, 0x188 + 36, 0xe0000020);
        auto reference_image = transmute::PeImage::parse(bytes);
        auto jit_image = transmute::PeImage::parse(bytes);
        transmute::ReferenceEngine reference(reference_image);
        transmute::ReferenceEngine optimized(jit_image);
        for (auto* engine : {&reference, &optimized}) {
            engine->set_initial_register(8, 0x8877665544332211ULL);
            engine->set_initial_register(9, jit_image.base() + 0x1101);
        }
        optimized.set_jit_enabled(true);
        const auto expected = reference.run();
        const auto actual = optimized.run();
        const auto mask = width == 8 ? UINT64_MAX : (1ULL << (width * 8)) - 1;
        expect(actual.instructions == expected.instructions &&
                   optimized.state().x == reference.state().x &&
                   optimized.state().x[10] == (0x8877665544332211ULL & mask) &&
                   optimized.jit_executed_instructions() >= 2,
               "translated image load/store differed from whole-width reference access");
    }
}

void test_jit_word_memory_access() {
    constexpr std::uint64_t data = 0x500000000ULL;
    for (const auto [opcode, offset, before, register_value, after_register,
                    after_memory] :
         std::array<std::tuple<std::uint32_t, std::uint64_t, std::uint64_t,
                               std::uint64_t, std::uint64_t, std::uint64_t>, 4>{
             std::tuple{0xb9400528U, 4ULL, 0x1122334487654321ULL,
                        UINT64_MAX, 0x87654321ULL,
                        0x1122334487654321ULL}, // ldr w8,[x9,#4]
             std::tuple{0xf9400528U, 8ULL, 0xfedcba9876543210ULL,
                        0ULL, 0xfedcba9876543210ULL,
                        0xfedcba9876543210ULL}, // ldr x8,[x9,#8]
             std::tuple{0xb9000528U, 4ULL, 0x1122334455667788ULL,
                        0xabcdef0187654321ULL, 0xabcdef0187654321ULL,
                        0x1122334487654321ULL}, // str w8,[x9,#4]
             std::tuple{0xf9000528U, 8ULL, 0ULL,
                        0xabcdef0187654321ULL, 0xabcdef0187654321ULL,
                        0xabcdef0187654321ULL}}) { // str x8,[x9,#8]
        auto image = transmute::PeImage::parse(executable({opcode, 0xd65f03c0U}));
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        for (auto* engine : {&reference, &optimized}) {
            engine->map_memory(data, 64);
            engine->write64(data + offset, before);
            engine->set_initial_register(8, register_value);
            engine->set_initial_register(9, data);
        }
        optimized.set_jit_enabled(true);
        const auto expected = reference.run();
        const auto actual = optimized.run();
        expect(actual.exit_code == expected.exit_code &&
                   actual.instructions == expected.instructions &&
                   optimized.state().x == reference.state().x &&
                   optimized.state().sp == reference.state().sp &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().nzcv == reference.state().nzcv &&
                   optimized.state().x[8] == after_register &&
                   optimized.read64(data + offset) == after_memory &&
                   optimized.read64(data + offset) ==
                       reference.read64(data + offset) &&
                   optimized.jit_executed_instructions() >= 1,
               "JIT W/X memory operation differs from ReferenceEngine");
    }

    auto stack_image = transmute::PeImage::parse(executable({
        0xd10103ffU, // sub sp,sp,#64
        0xf90013feU, // str x30,[sp,#32]: packaged VCRUNTIME form
        0xf94013e8U, // ldr x8,[sp,#32]
        0x910103ffU, // add sp,sp,#64
        0xd65f03c0U
    }));
    transmute::ReferenceEngine stack_reference(stack_image);
    transmute::ReferenceEngine stack_optimized(stack_image);
    stack_optimized.set_jit_enabled(true);
    const auto stack_expected = stack_reference.run();
    const auto stack_actual = stack_optimized.run();
    expect(stack_actual.exit_code == stack_expected.exit_code &&
               stack_actual.instructions == stack_expected.instructions &&
               stack_optimized.state().x == stack_reference.state().x &&
               stack_optimized.state().sp == stack_reference.state().sp &&
               stack_optimized.state().pc == stack_reference.state().pc &&
               stack_optimized.state().x[8] == stack_reference.state().x[30] &&
               stack_optimized.jit_executed_instructions() >= 2,
           "JIT W/X memory operation mishandled the SP base");

    for (const auto [opcode, error] :
         std::array<std::pair<std::uint32_t, const char*>, 2>{
             std::pair{0xb9400128U, "guest read outside mapped memory"},
             std::pair{0xb9000128U, "guest write outside mapped memory"}}) {
        auto image = transmute::PeImage::parse(executable({opcode, 0xd65f03c0U}));
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        for (auto* engine : {&reference, &optimized}) {
            engine->map_memory(data, 6);
            engine->set_initial_register(8, 0x11223344);
            engine->set_initial_register(9, data + 4);
        }
        optimized.set_jit_enabled(true);
        expect_failure([&] { static_cast<void>(reference.run()); }, error);
        expect_failure([&] { static_cast<void>(optimized.run()); }, error);
        expect(optimized.state().x == reference.state().x &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().sp == reference.state().sp &&
                   static_cast<transmute::GuestMemory&>(optimized).read8(
                       data + 4) ==
                       static_cast<transmute::GuestMemory&>(reference).read8(
                           data + 4) &&
                   static_cast<transmute::GuestMemory&>(optimized).read8(
                       data + 5) ==
                       static_cast<transmute::GuestMemory&>(reference).read8(
                           data + 5),
               "JIT W/X boundary fault changed partial-write semantics");
    }
    expect(transmute::decode_integer_block(
               0x140001000ULL, std::array{0xb8400528U}).has_value(),
           "JIT did not decode an imm9 W load with postindex writeback");
}

void test_jit_register_offset_memory_access() {
    constexpr std::uint64_t data = 0x500000000ULL;
    struct Fixture {
        std::uint32_t opcode;
        std::uint64_t base_offset;
        std::uint64_t register_offset;
        std::uint64_t source;
        std::uint64_t initial_memory;
        std::uint64_t memory_offset;
        std::uint64_t expected_x9;
        std::uint64_t expected_memory;
    };
    for (const auto fixture : std::array{
             Fixture{0xb8a85949U, 0, 1, 0, 0x80000001ULL, 4,
                     0xffffffff80000001ULL, 0x80000001ULL},
                 // ldrsw x9,[x10,w8,uxtw #2], packaged VCRUNTIME form
             Fixture{0x3828694bU, 0, 2, 0xab, 0, 0, 0x1234,
                     0x0000000000ab0000ULL},
                 // strb w11,[x10,x8], packaged VCRUNTIME form
             Fixture{0xb868d949U, 4, 0xffffffffULL, 0,
                     0x87654321ULL, 0, 0x87654321ULL, 0x87654321ULL},
                 // ldr w9,[x10,w8,sxtw #2]: negative offset
             Fixture{0xf8687949U, 0, 1, 0,
                     0xfedcba9876543210ULL, 8,
                     0xfedcba9876543210ULL, 0xfedcba9876543210ULL},
                 // ldr x9,[x10,x8,lsl #3]
             Fixture{0xb828594bU, 0, 1, 0xabcdef0187654321ULL,
                     0x1122334455667788ULL, 4, 0x1234,
                     0x1122334487654321ULL},
                 // str w11,[x10,w8,uxtw #2]
             Fixture{0xf828794bU, 0, 1, 0xabcdef0187654321ULL,
                     0, 8, 0x1234, 0xabcdef0187654321ULL},
                 // str x11,[x10,x8,lsl #3]
             Fixture{0x387f6949U, 0, 0x1234, 0, 0x5a, 0, 0x5a, 0x5a},
                 // ldrb w9,[x10,xzr]
         }) {
        auto image = transmute::PeImage::parse(executable({
            fixture.opcode, 0xd65f03c0U}));
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        for (auto* engine : {&reference, &optimized}) {
            engine->map_memory(data, 64);
            engine->write64(data + fixture.memory_offset,
                            fixture.initial_memory);
            engine->set_initial_register(8, fixture.register_offset);
            engine->set_initial_register(9, 0x1234);
            engine->set_initial_register(10, data + fixture.base_offset);
            engine->set_initial_register(11, fixture.source);
        }
        optimized.set_jit_enabled(true);
        const auto expected = reference.run();
        const auto actual = optimized.run();
        expect(actual.exit_code == expected.exit_code &&
                   actual.instructions == expected.instructions &&
                   optimized.state().x == reference.state().x &&
                   optimized.state().sp == reference.state().sp &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().nzcv == reference.state().nzcv &&
                   optimized.state().x[9] == fixture.expected_x9 &&
                   optimized.read64(data + fixture.memory_offset) ==
                       fixture.expected_memory &&
                   optimized.read64(data + fixture.memory_offset) ==
                       reference.read64(data + fixture.memory_offset) &&
                   optimized.jit_executed_instructions() >= 1,
               "JIT register-offset memory access differs from ReferenceEngine");
    }

    auto alias_image = transmute::PeImage::parse(executable({
        0xf8696949U, // ldr x9,[x10,x9]: destination is offset register
        0xd65f03c0U
    }));
    transmute::ReferenceEngine alias_reference(alias_image);
    transmute::ReferenceEngine alias_optimized(alias_image);
    for (auto* engine : {&alias_reference, &alias_optimized}) {
        engine->map_memory(data, 64);
        engine->write64(data + 8, 0xabcdef0123456789ULL);
        engine->set_initial_register(9, 8);
        engine->set_initial_register(10, data);
    }
    alias_optimized.set_jit_enabled(true);
    const auto alias_expected = alias_reference.run();
    const auto alias_actual = alias_optimized.run();
    expect(alias_actual.instructions == alias_expected.instructions &&
               alias_optimized.state().x == alias_reference.state().x &&
               alias_optimized.state().x[9] == 0xabcdef0123456789ULL &&
               alias_optimized.jit_executed_instructions() >= 1,
           "JIT register-offset load lost source/destination aliasing");

    auto fault_image = transmute::PeImage::parse(executable({
        0xb828694bU, // str w11,[x10,x8]
        0xd65f03c0U
    }));
    transmute::ReferenceEngine fault_reference(fault_image);
    transmute::ReferenceEngine fault_optimized(fault_image);
    for (auto* engine : {&fault_reference, &fault_optimized}) {
        engine->map_memory(data, 6);
        engine->set_initial_register(8, 0);
        engine->set_initial_register(10, data + 4);
        engine->set_initial_register(11, 0x11223344);
    }
    fault_optimized.set_jit_enabled(true);
    expect_failure([&] { static_cast<void>(fault_reference.run()); },
                   "guest write outside mapped memory");
    expect_failure([&] { static_cast<void>(fault_optimized.run()); },
                   "guest write outside mapped memory");
    auto& ref_memory = static_cast<transmute::GuestMemory&>(fault_reference);
    auto& jit_memory = static_cast<transmute::GuestMemory&>(fault_optimized);
    expect(fault_optimized.state().x == fault_reference.state().x &&
               fault_optimized.state().pc == fault_reference.state().pc &&
               jit_memory.read8(data + 4) == ref_memory.read8(data + 4) &&
               jit_memory.read8(data + 5) == ref_memory.read8(data + 5),
           "JIT register-offset store changed partial-fault semantics");
    expect(!transmute::decode_integer_block(
               0x140001000ULL, std::array{0x38680949U}) &&
               !transmute::decode_integer_block(
                   0x140001000ULL, std::array{0xf8a85949U}),
           "JIT accepted reserved register-offset memory form");
}

// The reference engine's own unsigned-offset LDRSB/LDRSH results, W and X.
void test_reference_signed_narrow_loads() {
    constexpr std::uint64_t data = 0x500000000ULL;
    struct Case { std::uint32_t opcode; std::uint64_t expected; const char* name; };
    for (const auto& c : {Case{0x39c00148U, 0xffffff81ULL, "ldrsb w8,[x10]"},
                          Case{0x39800148U, 0xffffffffffffff81ULL, "ldrsb x8,[x10]"},
                          Case{0x79c00148U, 0xffff8081ULL, "ldrsh w8,[x10]"},
                          Case{0x79800148U, 0xffffffffffff8081ULL, "ldrsh x8,[x10]"}}) {
        auto image = transmute::PeImage::parse(executable({c.opcode, 0xd65f03c0U}));
        transmute::ReferenceEngine engine(image);
        engine.map_memory(data, 64);
        engine.write64(data, 0x8877665544338081ULL);
        engine.set_initial_register(8, UINT64_MAX);
        engine.set_initial_register(10, data);
        static_cast<void>(engine.run());
        expect(engine.state().x[8] == c.expected,
               std::string("reference ") + c.name + " gave " + std::to_string(engine.state().x[8]) +
                   ", expected " + std::to_string(c.expected));
    }
}

void test_jit_narrow_memory_access() {
    constexpr std::uint64_t data = 0x500000000ULL;
    constexpr std::uint64_t source_value = 0xfedcba987654ab81ULL;
    // Enumerate valid integer accesses over independent addressing cases.
    // Loads include a negative value so signed W and X destinations differ.
    for (unsigned size = 0; size <= 3; ++size) {
        const auto last_access = size == 3 ? 1U : size == 2 ? 2U : 3U;
        for (unsigned access = 0; access <= last_access; ++access) {
            for (unsigned addressing = 0; addressing != 12; ++addressing) {
                auto opcode = (size << 30) | (access << 22) | (10U << 5) | 8U;
                std::uint64_t target = data + 16;
                std::uint64_t expected_base = data + 16;
                std::uint64_t offset_value = 0;
                if (addressing == 0) {
                    opcode |= 0x39000000U | (3U << 10); // unsigned imm12
                    target += 3U << size;
                } else if (addressing <= 3) {
                    opcode |= 0x38000000U | (0x1fdU << 12); // imm9 -3
                    if (addressing == 2) opcode |= 0x400U; // postindex
                    if (addressing == 3) opcode |= 0xc00U; // preindex
                    if (addressing != 2) target -= 3;
                    if (addressing != 1) expected_base -= 3;
                } else {
                    const auto option = std::array{2U, 3U, 6U, 7U}[
                        (addressing - 4) / 2];
                    const bool scaled = (addressing & 1U) != 0;
                    opcode |= 0x38200800U | (9U << 16) | (option << 13) |
                              (scaled ? 0x1000U : 0U);
                    const bool negative = option >= 6;
                    offset_value = negative
                        ? (option == 6 ? 0x12345678ffffffffULL : UINT64_MAX)
                        : (option == 2 ? 0xabcdef0100000001ULL : 1ULL);
                    const auto bytes = scaled ? 1U << size : 1U;
                    target = negative ? target - bytes : target + bytes;
                }
                auto image = transmute::PeImage::parse(executable({
                    opcode, 0x91000d0cU, // add x12,x8,#3
                    0xd65f03c0U}));
                transmute::ReferenceEngine reference(image);
                transmute::ReferenceEngine optimized(image);
                const auto initial_memory = std::array{
                    0x8877665544332281ULL, 0x8877665544338001ULL,
                    0x8877665580000001ULL, 0x8877665544332211ULL}[size];
                for (auto* engine : {&reference, &optimized}) {
                    engine->map_memory(data, 64);
                    engine->write64(target, initial_memory);
                    engine->set_initial_register(8, access == 0
                        ? source_value : UINT64_MAX);
                    engine->set_initial_register(9, offset_value);
                    engine->set_initial_register(10, data + 16);
                }
                optimized.set_jit_enabled(true);
                const auto expected = reference.run();
                const auto actual = optimized.run();
                const auto expected_load = size == 0
                    ? (access == 2 ? 0xffffffffffffff81ULL
                        : access == 3 ? 0xffffff81ULL : 0x81ULL)
                    : size == 1 ? (access == 2 ? 0xffffffffffff8001ULL
                        : access == 3 ? 0xffff8001ULL : 0x8001ULL)
                    : size == 2 ? (access == 2 ? 0xffffffff80000001ULL
                                               : 0x80000001ULL)
                    : initial_memory;
                const auto expected_register = access == 0
                    ? source_value : expected_load;
                const auto expected_memory = access == 0
                    ? (size == 0 ? 0x8877665544332281ULL
                        : size == 1 ? 0x887766554433ab81ULL
                        : size == 2 ? 0x887766557654ab81ULL
                                    : source_value)
                    : initial_memory;
                // Name every field that differs, so a failure on another machine says which.
                std::string differences;
                const auto hex = [](std::uint64_t value) {
                    char text[17];
                    std::snprintf(text, sizeof text, "%llx", static_cast<unsigned long long>(value));
                    return std::string(text);
                };
                const auto differ = [&](bool equal, const char* field, std::uint64_t jit, std::uint64_t want) {
                    if (!equal)
                        differences += std::string(" ") + field + " jit=0x" + hex(jit) + " want=0x" + hex(want) + ";";
                };
                differ(actual.instructions == expected.instructions, "instructions",
                       actual.instructions, expected.instructions);
                for (unsigned index = 0; index != optimized.state().x.size(); ++index)
                    differ(optimized.state().x[index] == reference.state().x[index],
                           ("x" + std::to_string(index) + "(reference)").c_str(),
                           optimized.state().x[index], reference.state().x[index]);
                differ(optimized.state().sp == reference.state().sp, "sp", optimized.state().sp, reference.state().sp);
                differ(optimized.state().pc == reference.state().pc, "pc", optimized.state().pc, reference.state().pc);
                differ(optimized.state().nzcv == reference.state().nzcv, "nzcv",
                       optimized.state().nzcv, reference.state().nzcv);
                differ(optimized.state().x[8] == expected_register, "x8", optimized.state().x[8], expected_register);
                differ(optimized.state().x[10] == expected_base, "x10", optimized.state().x[10], expected_base);
                differ(optimized.state().x[12] == expected_register + 3, "x12",
                       optimized.state().x[12], expected_register + 3);
                differ(optimized.read64(target) == expected_memory, "memory",
                       optimized.read64(target), expected_memory);
                differ(optimized.jit_executed_instructions() == 3, "native instructions",
                       optimized.jit_executed_instructions(), 3);
                expect(differences.empty(),
                       "JIT integer memory addressing or sign extension differs from reference: size " +
                           std::to_string(size) + ", access " + std::to_string(access) +
                           ", addressing " + std::to_string(addressing) + ":" + differences);
                for (unsigned byte = 0; byte != 64; ++byte) {
                    expect(static_cast<transmute::GuestMemory&>(optimized).read8(data + byte) ==
                               static_cast<transmute::GuestMemory&>(reference).read8(data + byte),
                           "JIT integer memory access changed unrelated guest memory");
                }
            }
        }
    }

    // The exact LDRSB words sampled in Blender startup must lower directly.
    for (const auto word : {0x39c0010bU, 0x38c01d09U, 0x39808113U}) {
        const auto decoded = transmute::decode_integer_block(
            0x140001000ULL, std::array{word});
        expect(decoded && decoded->instructions.front().op ==
                              transmute::BlockOp::load_signed_byte,
               "JIT failed to lower a profiled Blender LDRSB form");
    }

    // Base/destination and offset/destination aliases use the old input value.
    for (const auto opcode : {0x79c00108U, // ldrsh w8,[x8]
                              0x78e86948U}) { // ldrsh w8,[x10,x8]
        auto image = transmute::PeImage::parse(executable({opcode, 0xd65f03c0U}));
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        for (auto* engine : {&reference, &optimized}) {
            engine->map_memory(data, 64);
            engine->write64(data + 8, 0x8001);
            engine->set_initial_register(8, opcode == 0x79c00108U ? data + 8 : 8);
            engine->set_initial_register(10, data);
        }
        optimized.set_jit_enabled(true);
        static_cast<void>(reference.run());
        static_cast<void>(optimized.run());
        expect(optimized.state().x == reference.state().x &&
                   optimized.state().x[8] == 0xffff8001ULL &&
                   optimized.jit_executed_instructions() == 2,
               "JIT narrow load lost base or offset aliasing");
    }

    // SP is a base, while WZR/XZR discards loads and supplies zero to stores.
    auto stack_image = transmute::PeImage::parse(executable({
        0xd10043ffU, // sub sp,sp,#16
        0x781f0fe8U, // strh w8,[sp,#-16]!
        0x788107edU, // ldrsh x13,[sp],#16
        0x790007e8U, // strh w8,[sp,#2]
        0x798007e9U, // ldrsh x9,[sp,#2]
        0x79c007eaU, // ldrsh w10,[sp,#2]
        0x794007ffU, // ldrh wzr,[sp,#2]
        0x790007ffU, // strh wzr,[sp,#2]
        0x794007ebU, // ldrh w11,[sp,#2]
        0x910043ffU, // add sp,sp,#16
        0xd65f03c0U}));
    transmute::ReferenceEngine stack_reference(stack_image);
    transmute::ReferenceEngine stack_optimized(stack_image);
    for (auto* engine : {&stack_reference, &stack_optimized}) {
        engine->set_initial_register(8, 0x8001);
    }
    stack_optimized.set_jit_enabled(true);
    static_cast<void>(stack_reference.run());
    static_cast<void>(stack_optimized.run());
    expect(stack_optimized.state().x == stack_reference.state().x &&
               stack_optimized.state().sp == stack_reference.state().sp &&
               stack_optimized.state().x[9] == 0xffffffffffff8001ULL &&
               stack_optimized.state().x[10] == 0xffff8001ULL &&
               stack_optimized.state().x[11] == 0 &&
               stack_optimized.state().x[13] == 0xffffffffffff8001ULL &&
               stack_optimized.jit_executed_instructions() == 11,
           "JIT halfword memory family confused SP with ZR");

    for (const auto opcode : {0x78c01d48U, // ldrsh w8,[x10,#1]!
                              0x78c01548U, // ldrsh w8,[x10],#1
                              0x78001548U}) { // strh w8,[x10],#1
        auto image = transmute::PeImage::parse(executable({opcode, 0xd65f03c0U}));
        transmute::ReferenceEngine memory(image);
        memory.map_memory(data, 1);
        static_cast<transmute::GuestMemory&>(memory).write8(data, 0x6c);
        transmute::X64BlockCache cache;
        transmute::CpuState state{};
        state.pc = image.entry();
        state.x[8] = 0xab81;
        state.x[10] = data;
        const auto before = state;
        expect(!cache.execute(state, image.entry(),
                              std::array{opcode, 0xd65f03c0U}, 0, &memory) &&
                   state.x == before.x && state.pc == before.pc &&
                   state.sp == before.sp &&
                   static_cast<transmute::GuestMemory&>(memory).read8(data) == 0x6c,
               "JIT halfword boundary fault committed state before fallback");
        // Interpreter fallback retains its partial-store behavior exactly.
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        for (auto* engine : {&reference, &optimized}) {
            engine->map_memory(data, 1);
            static_cast<transmute::GuestMemory&>(*engine).write8(data, 0x6c);
            engine->set_initial_register(8, 0xab81);
            engine->set_initial_register(10, data);
        }
        optimized.set_jit_enabled(true);
        const auto error = opcode == 0x78001548U
            ? "guest write outside mapped memory" : "guest read outside mapped memory";
        expect_failure([&] { static_cast<void>(reference.run()); }, error);
        expect_failure([&] { static_cast<void>(optimized.run()); }, error);
        expect(optimized.state().x == reference.state().x &&
                   optimized.state().pc == reference.state().pc &&
                   static_cast<transmute::GuestMemory&>(optimized).read8(data) ==
                       static_cast<transmute::GuestMemory&>(reference).read8(data),
               "JIT halfword fault fallback changed partial-write semantics");
    }

    for (const auto opcode : {0x78c01d48U, 0x39800148U, 0x79000148U,
                              0x79c0015fU}) { // Load to WZR still accesses memory.
        auto image = transmute::PeImage::parse(executable({0xd65f03c0U}));
        transmute::ReferenceEngine memory(image);
        memory.map_memory(data, 64);
        memory.set_memory_access(data, false, false, false);
        transmute::X64BlockCache cache;
        transmute::CpuState state{};
        state.pc = image.entry();
        state.x[8] = 0xabcdef;
        state.x[10] = data;
        const auto before = state;
        expect(!cache.execute(state, image.entry(), std::array{opcode}, 0, &memory) &&
                   cache.execute_cached(state, image.entry(), 0, 1,
                                        nullptr, &memory) == 0 &&
                   state.x == before.x && state.sp == before.sp &&
                   state.pc == before.pc,
               "JIT cached narrow access changed registers on a permission fault");
    }

    // Reserved opcodes, extension values, and new writeback overlaps fall back.
    for (const auto word : {0xb9c00148U, 0xf9c00148U, 0xb8c00148U,
                            0xf8801548U, 0x78680948U, 0x78c00948U,
                            0x38c01d08U, 0x7840154aU, 0x78001d4aU,
                            0x3dc00148U}) {
        expect(!transmute::decode_integer_block(
                   0x140001000ULL, std::array{word}),
               "JIT accepted reserved or constrained narrow memory encoding " +
                   std::to_string(word));
    }
    const auto split = transmute::decode_integer_block(
        0x140001000ULL, std::array{0xd503201fU, 0x79c00148U});
    expect(split && split->words.size() == 1,
           "JIT moved a halfword load after an architectural state change");

    // A compiled STRH changing executable memory must invalidate cached code.
    constexpr std::uint64_t code = data + 0x10000;
    auto code_image = transmute::PeImage::parse(executable({
        0x79000148U, // strh w8,[x10]
        0xd65f03c0U}));
    transmute::ReferenceEngine code_engine(code_image);
    code_engine.map_memory(code, 64);
    code_engine.write32(code, 0xd2800020U); // movz x0,#1
    code_engine.write32(code + 4, 0xd65f03c0U);
    code_engine.set_memory_access(code, true, true, true);
    code_engine.set_jit_enabled(true);
    expect(code_engine.invoke_callback(code, 0) == 1,
           "JIT executable halfword-store test did not cache the original code");
    code_engine.set_initial_register(8, 0x0040); // movz x0,#2 low halfword
    code_engine.set_initial_register(10, code);
    static_cast<void>(code_engine.run());
    expect(code_engine.read32(code) == 0xd2800040U &&
               code_engine.invoke_callback(code, 0) == 2,
           "JIT STRH failed to invalidate changed executable memory");
}

void test_jit_integer_pair_memory_access() {
    constexpr std::uint64_t data = 0x500000000ULL;
    auto hot_image = transmute::PeImage::parse(executable({
        0xa9bd53f3U, // stp x19,x20,[sp,#-48]!: packaged VCRUNTIME form
        0xd2800013U, // movz x19,#0
        0xd2800014U, // movz x20,#0
        0xa8c353f3U, // ldp x19,x20,[sp],#48
        0xd65f03c0U
    }));
    transmute::ReferenceEngine hot_reference(hot_image);
    transmute::ReferenceEngine hot_optimized(hot_image);
    for (auto* engine : {&hot_reference, &hot_optimized}) {
        engine->set_initial_register(19, 0x1122334455667788ULL);
        engine->set_initial_register(20, 0xfedcba9876543210ULL);
    }
    hot_optimized.set_jit_enabled(true);
    const auto hot_expected = hot_reference.run();
    const auto hot_actual = hot_optimized.run();
    expect(hot_actual.exit_code == hot_expected.exit_code &&
               hot_actual.instructions == hot_expected.instructions &&
               hot_optimized.state().x == hot_reference.state().x &&
               hot_optimized.state().sp == hot_reference.state().sp &&
               hot_optimized.state().pc == hot_reference.state().pc &&
               hot_optimized.state().x[19] == 0x1122334455667788ULL &&
               hot_optimized.state().x[20] == 0xfedcba9876543210ULL &&
               hot_optimized.jit_executed_instructions() >= 4,
           "JIT integer pair pre/post writeback differs from ReferenceEngine");

    auto word_image = transmute::PeImage::parse(executable({
        0x29012548U, // stp w8,w9,[x10,#8]
        0x52800008U, // movz w8,#0
        0x52800009U, // movz w9,#0
        0x29412548U, // ldp w8,w9,[x10,#8]
        0xd65f03c0U
    }));
    transmute::ReferenceEngine word_reference(word_image);
    transmute::ReferenceEngine word_optimized(word_image);
    for (auto* engine : {&word_reference, &word_optimized}) {
        engine->map_memory(data, 64);
        engine->set_initial_register(8, 0xaaaaaaaa87654321ULL);
        engine->set_initial_register(9, 0xbbbbbbbb12345678ULL);
        engine->set_initial_register(10, data);
    }
    word_optimized.set_jit_enabled(true);
    const auto word_expected = word_reference.run();
    const auto word_actual = word_optimized.run();
    expect(word_actual.instructions == word_expected.instructions &&
               word_optimized.state().x == word_reference.state().x &&
               word_optimized.state().pc == word_reference.state().pc &&
               word_optimized.state().x[8] == 0x87654321ULL &&
               word_optimized.state().x[9] == 0x12345678ULL &&
               word_optimized.read64(data + 8) == 0x1234567887654321ULL &&
               word_optimized.read64(data + 8) ==
                   word_reference.read64(data + 8) &&
               word_optimized.jit_executed_instructions() >= 2,
           "JIT W pair offset load/store differs from ReferenceEngine");

    auto alias_image = transmute::PeImage::parse(executable({
        0xa9c12d4aU, // ldp x10,x11,[x10,#16]!: base aliases first destination
        0xd65f03c0U
    }));
    transmute::ReferenceEngine alias_reference(alias_image);
    transmute::ReferenceEngine alias_optimized(alias_image);
    for (auto* engine : {&alias_reference, &alias_optimized}) {
        engine->map_memory(data, 64);
        engine->write64(data + 16, 0x1111222233334444ULL);
        engine->write64(data + 24, 0x5555666677778888ULL);
        engine->set_initial_register(10, data);
    }
    alias_optimized.set_jit_enabled(true);
    const auto alias_expected = alias_reference.run();
    const auto alias_actual = alias_optimized.run();
    expect(alias_actual.instructions == alias_expected.instructions &&
               alias_optimized.state().x == alias_reference.state().x &&
               alias_optimized.state().x[10] == data + 16 &&
               alias_optimized.state().x[11] == 0x5555666677778888ULL &&
               alias_optimized.jit_executed_instructions() >= 1,
           "JIT pair load lost base/destination alias writeback order");

    auto store_alias_image = transmute::PeImage::parse(executable({
        0xa8812d4aU, // stp x10,x11,[x10],#16: source aliases base
        0xd65f03c0U
    }));
    transmute::ReferenceEngine store_alias_reference(store_alias_image);
    transmute::ReferenceEngine store_alias_optimized(store_alias_image);
    for (auto* engine : {&store_alias_reference, &store_alias_optimized}) {
        engine->map_memory(data, 64);
        engine->set_initial_register(10, data);
        engine->set_initial_register(11, 0x0123456789abcdefULL);
    }
    store_alias_optimized.set_jit_enabled(true);
    const auto store_alias_expected = store_alias_reference.run();
    const auto store_alias_actual = store_alias_optimized.run();
    expect(store_alias_actual.instructions == store_alias_expected.instructions &&
               store_alias_optimized.state().x ==
                   store_alias_reference.state().x &&
               store_alias_optimized.state().x[10] == data + 16 &&
               store_alias_optimized.read64(data) == data &&
               store_alias_optimized.read64(data + 8) ==
                   0x0123456789abcdefULL &&
               store_alias_optimized.jit_executed_instructions() >= 1,
           "JIT pair store did not read aliased source before writeback");

    auto duplicate_image = transmute::PeImage::parse(executable({
        0xa8c12148U, // ldp x8,x8,[x10],#16: second load wins
        0xd65f03c0U
    }));
    transmute::ReferenceEngine duplicate_reference(duplicate_image);
    transmute::ReferenceEngine duplicate_optimized(duplicate_image);
    for (auto* engine : {&duplicate_reference, &duplicate_optimized}) {
        engine->map_memory(data, 64);
        engine->write64(data, 0x1111111111111111ULL);
        engine->write64(data + 8, 0x2222222222222222ULL);
        engine->set_initial_register(10, data);
    }
    duplicate_optimized.set_jit_enabled(true);
    const auto duplicate_expected = duplicate_reference.run();
    const auto duplicate_actual = duplicate_optimized.run();
    expect(duplicate_actual.instructions == duplicate_expected.instructions &&
               duplicate_optimized.state().x == duplicate_reference.state().x &&
               duplicate_optimized.state().x[8] == 0x2222222222222222ULL &&
               duplicate_optimized.state().x[10] == data + 16 &&
               duplicate_optimized.jit_executed_instructions() >= 1,
           "JIT pair load lost duplicate-destination ordering");

    auto unaligned_image = transmute::PeImage::parse(executable({
        0x29002548U, // stp w8,w9,[x10]
        0x29402548U, // ldp w8,w9,[x10]
        0xd65f03c0U
    }));
    transmute::ReferenceEngine unaligned_reference(unaligned_image);
    transmute::ReferenceEngine unaligned_optimized(unaligned_image);
    for (auto* engine : {&unaligned_reference, &unaligned_optimized}) {
        engine->map_memory(data, 64);
        engine->set_initial_register(8, 0x12345678);
        engine->set_initial_register(9, 0xabcdef01);
        engine->set_initial_register(10, data + 1);
    }
    unaligned_optimized.set_jit_enabled(true);
    const auto unaligned_expected = unaligned_reference.run();
    const auto unaligned_actual = unaligned_optimized.run();
    expect(unaligned_actual.instructions == unaligned_expected.instructions &&
               unaligned_optimized.state().x == unaligned_reference.state().x &&
               unaligned_optimized.read64(data + 1) ==
                   unaligned_reference.read64(data + 1) &&
               unaligned_optimized.read64(data + 1) ==
                   0xabcdef0112345678ULL &&
               unaligned_optimized.jit_executed_instructions() >= 2,
           "JIT pair transfer changed ordinary unaligned access semantics");

    for (const auto [opcode, error] :
         std::array<std::pair<std::uint32_t, const char*>, 2>{
             std::pair{0xa9002548U, "guest write outside mapped memory"},
             std::pair{0xa9402548U, "guest read outside mapped memory"}}) {
        auto image = transmute::PeImage::parse(executable({opcode, 0xd65f03c0U}));
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        for (auto* engine : {&reference, &optimized}) {
            engine->map_memory(data, 12);
            engine->set_initial_register(8, 0x1122334455667788ULL);
            engine->set_initial_register(9, 0x99aabbccddeeff00ULL);
            engine->set_initial_register(10, data + 4);
        }
        optimized.set_jit_enabled(true);
        expect_failure([&] { static_cast<void>(reference.run()); }, error);
        expect_failure([&] { static_cast<void>(optimized.run()); }, error);
        expect(optimized.state().x == reference.state().x &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().sp == reference.state().sp &&
                   optimized.read64(data + 4) == reference.read64(data + 4),
               "JIT pair cross-region fault changed partial state or memory");
    }
    expect(!transmute::decode_integer_block(
               0x140001000ULL, std::array{0x69c02548U}),
           "JIT accepted signed pair loads outside its integer pair subset");
}

void test_jit_pc_relative_addresses() {
    auto image = transmute::PeImage::parse(executable({
        0x1000076aU, // ADR X10,#236: packaged VCRUNTIME form
        0x1000120aU, // ADR X10,#576: packaged VCRUNTIME form
        0x70ffffe2U, // ADR X2,#-1
        0x9000000bU, // ADRP X11,#0
        0xb000000cU, // ADRP X12,#1 page
        0xf0ffffedU, // ADRP X13,#-1 page
        0x1000001fU, // ADR XZR,#0
        0xd65f03c0U
    }));
    transmute::ReferenceEngine reference(image);
    transmute::ReferenceEngine optimized(image);
    optimized.set_jit_enabled(true);
    const auto expected = reference.run();
    const auto actual = optimized.run();
    const auto page = image.entry() & ~0xfffULL;
    expect(actual.exit_code == expected.exit_code &&
               actual.instructions == expected.instructions &&
               optimized.state().x == reference.state().x &&
               optimized.state().sp == reference.state().sp &&
               optimized.state().pc == reference.state().pc &&
               optimized.state().nzcv == reference.state().nzcv &&
               optimized.state().x[10] == image.entry() + 4 + 576 &&
               optimized.state().x[2] == image.entry() + 7 &&
               optimized.state().x[11] == page &&
               optimized.state().x[12] == page + 4096 &&
               optimized.state().x[13] == page - 4096 &&
               optimized.jit_executed_instructions() >= 7,
           "JIT ADR/ADRP differs from ReferenceEngine");
    const auto cross_page = transmute::decode_integer_block(
        0x140001ffcULL,
        std::array{0x90000000U, 0x90000001U, 0xd65f03c0U});
    expect(cross_page && cross_page->instructions.size() == 3 &&
               cross_page->instructions[0].immediate == 0x140001000ULL &&
               cross_page->instructions[1].immediate == 0x140002000ULL,
           "JIT ADRP page base did not follow the instruction PC");
}

void test_jit_flag_arithmetic_and_conditional_branches() {
    const auto compare = [](std::uint32_t arithmetic, std::uint32_t condition,
                            std::uint64_t lhs, std::uint64_t rhs) {
        auto image = transmute::PeImage::parse(executable({
            arithmetic,
            0x54000040U | condition, // b.cond +8
            0xd2800120U,             // movz x0, #9 when branch not taken
            0xd65f03c0U
        }));
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        for (auto* engine : {&reference, &optimized}) {
            engine->set_initial_register(0, 5);
            engine->set_initial_register(1, lhs);
            engine->set_initial_register(2, rhs);
        }
        optimized.set_jit_enabled(true);
        const auto expected = reference.run();
        const auto actual = optimized.run();
        expect(actual.exit_code == expected.exit_code &&
                   actual.instructions == expected.instructions &&
                   optimized.state().x == reference.state().x &&
                   optimized.state().sp == reference.state().sp &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().nzcv == reference.state().nzcv &&
                   optimized.jit_executed_instructions() >= 2,
               "JIT arithmetic flags or conditional branch differs from ReferenceEngine");
    };
    for (unsigned condition = 0; condition < 16; ++condition) {
        for (const auto [lhs, rhs] : std::array{
                 std::pair{0ULL, 0ULL},
                 std::pair{1ULL, 2ULL},
                 std::pair{2ULL, 1ULL},
                 std::pair{0x7fffffffffffffffULL, UINT64_MAX},
                 std::pair{0x8000000000000000ULL, 1ULL}}) {
            compare(0xeb02003fU, condition, lhs, rhs); // cmp x1, x2
        }
    }
    for (const auto [opcode, lhs, rhs] : std::array{
             std::tuple{0xab020023U, UINT64_MAX, 1ULL}, // adds x3,x1,x2
             std::tuple{0xeb020023U, 0ULL, 1ULL},       // subs x3,x1,x2
             std::tuple{0x2b020023U, 0xffffffffULL, 1ULL}, // adds w3,w1,w2
             std::tuple{0x6b020023U, 0ULL, 1ULL},       // subs w3,w1,w2
             std::tuple{0x31000423U, 0xffffffffULL, 0ULL}, // adds w3,w1,#1
             std::tuple{0x71000423U, 0ULL, 0ULL},       // subs w3,w1,#1
             std::tuple{0xb1000423U, UINT64_MAX, 0ULL}, // adds x3,x1,#1
             std::tuple{0xf100043fU, 1ULL, 0ULL},       // cmp x1,#1
             std::tuple{0xb10007e3U, 0ULL, 0ULL},       // adds x3,sp,#1
             std::tuple{0xab1f03e3U, 0ULL, 0ULL}}) {   // adds x3,xzr,xzr
        compare(opcode, 0, lhs, rhs);
        compare(opcode, 1, lhs, rhs);
    }
    const auto backward = transmute::decode_integer_block(
        0x140001000ULL, std::array{0xd503201fU, 0x54ffffc1U});
    expect(backward && backward->instructions.back().op ==
               transmute::BlockOp::conditional_branch &&
               backward->instructions.back().immediate == 0x140000ffcULL,
           "JIT conditional branch lost its signed displacement");
    expect(!transmute::decode_integer_block(
               0x140001000ULL, std::array{0x54000010U}),
           "JIT accepted reserved conditional branch encoding");
}

void test_jit_logical_register_forms() {
    const auto compare = [](std::uint32_t logical, std::uint64_t lhs,
                            std::uint64_t rhs, unsigned condition) {
        auto image = transmute::PeImage::parse(executable({
            logical,
            0x54000040U | condition, // b.cond +8; observes ANDS/BICS flags
            0xd2800120U,             // movz x0, #9 when not taken
            0xd65f03c0U
        }));
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        for (auto* engine : {&reference, &optimized}) {
            engine->set_initial_register(0, 5);
            engine->set_initial_register(1, lhs);
            engine->set_initial_register(2, rhs);
        }
        optimized.set_jit_enabled(true);
        const auto expected = reference.run();
        const auto actual = optimized.run();
        expect(actual.exit_code == expected.exit_code &&
                   actual.instructions == expected.instructions &&
                   optimized.state().x == reference.state().x &&
                   optimized.state().sp == reference.state().sp &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().nzcv == reference.state().nzcv &&
                   optimized.jit_executed_instructions() >= 2,
               "JIT logical register or NZCV result differs from ReferenceEngine");
    };
    for (const auto opcode : std::array{
             0x8a020023U, 0x8a220023U, // AND, BIC x3,x1,x2
             0xaa020023U, 0xaa220023U, // ORR, ORN
             0xca020023U, 0xca220023U, // EOR, EON
             0xea020023U, 0xea220023U, // ANDS, BICS
             0x0a020023U, 0x0a220023U, // 32-bit forms
             0x2a020023U, 0x2a220023U,
             0x4a020023U, 0x4a220023U,
             0x6a020023U, 0x6a220023U}) {
        compare(opcode, 0xffff0000ffff0000ULL, 0x0f0f0f0f00ff00ffULL, 0);
        compare(opcode, 0, 0, 1);
    }
    compare(0xaa1f03e3U, UINT64_MAX, UINT64_MAX, 14); // mov x3, xzr
    compare(0xea02003fU, 0, UINT64_MAX, 0); // tst x1, x2
    compare(0x8a020423U, UINT64_MAX, 0x0123456789abcdefULL, 14); // and x3,x1,x2,lsl#1
    expect(!transmute::decode_integer_block(
               0x140001000ULL, std::array{0x0a028023U}),
           "JIT accepted reserved W logical shift amount 32");
}

void test_jit_conditional_select_forms() {
    const auto compare = [](std::uint32_t select, std::uint64_t lhs,
                            std::uint64_t rhs) {
        auto image = transmute::PeImage::parse(executable({
            0xeb02003fU, // cmp x1, x2
            select,
            0xaa1f0060U, // mov x0, x3
            0xd65f03c0U
        }));
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        for (auto* engine : {&reference, &optimized}) {
            engine->set_initial_register(1, lhs);
            engine->set_initial_register(2, rhs);
            engine->set_initial_register(3, 0xdeadbeefULL);
            engine->set_initial_register(4, 0x8000000100000007ULL);
            engine->set_initial_register(5, UINT64_MAX);
        }
        optimized.set_jit_enabled(true);
        const auto expected = reference.run();
        const auto actual = optimized.run();
        expect(actual.exit_code == expected.exit_code &&
                   actual.instructions == expected.instructions &&
                   optimized.state().x == reference.state().x &&
                   optimized.state().sp == reference.state().sp &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().nzcv == reference.state().nzcv &&
                   optimized.jit_executed_instructions() == 4,
               "JIT conditional select differs from ReferenceEngine");
    };
    for (unsigned condition = 0; condition < 16; ++condition) {
        for (const auto base : std::array{
                 0x1a800000U, 0x1a800400U, // CSEL, CSINC
                 0x5a800000U, 0x5a800400U}) { // CSINV, CSNEG
            for (const auto width : std::array{0U, 0x80000000U}) {
                const auto opcode = base | width | (5U << 16) |
                    (condition << 12) | (4U << 5) | 3U;
                compare(opcode, 0, 0); // zero and carry set
                compare(opcode, 1, 2); // negative and carry clear
            }
        }
    }
    compare(0x9a9f03e3U, 0, 0); // csel x3, xzr, xzr, eq
    compare(0xda9f03e3U, 1, 2); // csinv x3, xzr, xzr, eq
}

void test_jit_logical_immediate_forms() {
    const auto compare = [](std::uint32_t logical, std::uint64_t source) {
        auto image = transmute::PeImage::parse(executable({
            logical,
            0x54000040U, // b.eq +8; observes ANDS flags
            0xd2800120U, // movz x0, #9 when not taken
            0xd65f03c0U
        }));
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        for (auto* engine : {&reference, &optimized}) {
            engine->set_initial_register(0, 5);
            engine->set_initial_register(8, source);
            engine->set_initial_register(15, source);
        }
        optimized.set_jit_enabled(true);
        const auto expected = reference.run();
        const auto actual = optimized.run();
        expect(actual.exit_code == expected.exit_code &&
                   actual.instructions == expected.instructions &&
                   optimized.state().x == reference.state().x &&
                   optimized.state().sp == reference.state().sp &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().nzcv == reference.state().nzcv &&
                   optimized.jit_executed_instructions() >= 2,
               "JIT logical immediate differs from ReferenceEngine");
    };
    for (const auto opcode : std::array{
             0x121a01efU, 0x321a01efU, // AND/ORR w15,w15,#0x40
             0x521a01efU, 0x721a01efU, // EOR/ANDS
             0x9240bd09U, 0xb240bd09U, // AND/ORR x9,x8,#mask
             0xd240bd09U, 0xf240bd09U}) { // EOR/ANDS
        compare(opcode, 0);
        compare(opcode, UINT64_MAX);
        compare(opcode, 0x8000000180000040ULL);
    }
    compare(0x321a01ffU, 0x40); // ORR WSP, W15, #0x40
    compare(0xf240bd1fU, UINT64_MAX); // TST X8, mask, discard Rd
    compare(0xb240bfe9U, 0); // ORR X9, XZR, mask
    expect(!transmute::decode_integer_block(
               0x140001000ULL, std::array{0x1200fc00U}) &&
               !transmute::decode_integer_block(
                   0x140001000ULL, std::array{0x125a01efU}),
           "JIT accepted reserved logical immediate bitmask");
}

void test_jit_unsigned_bitfield_forms() {
    const auto compare = [](std::uint32_t bitfield, std::uint64_t source) {
        auto image = transmute::PeImage::parse(executable({
            bitfield,
            0xd65f03c0U
        }));
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        for (auto* engine : {&reference, &optimized}) {
            engine->set_initial_register(0, 42);
            engine->set_initial_register(1, source);
            engine->set_initial_register(10, source);
            engine->set_initial_register(15, source);
        }
        optimized.set_jit_enabled(true);
        const auto expected = reference.run();
        const auto actual = optimized.run();
        expect(actual.exit_code == expected.exit_code &&
                   actual.instructions == expected.instructions &&
                   optimized.state().x == reference.state().x &&
                   optimized.state().sp == reference.state().sp &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().nzcv == reference.state().nzcv &&
                   optimized.jit_executed_instructions() == 2,
               "JIT unsigned bitfield differs from ReferenceEngine");
    };
    for (const auto opcode : std::array{
             0x53001defU, // staged Blender: uxtb w15, w15
             0x53083d4bU, // staged Blender: ubfx w11, w10, #8, #8
             0xd341fc20U, // existing guest fixture: lsr x0, x1, #1
             0xd37ff820U, // lsl x0, x1, #1
             0x53185c23U, // lsl w3, w1, #8
             0xd34c6c23U, // ubfx x3, x1, #12, #16
             0xd340ffe3U}) { // ubfm x3, xzr, #0, #63
        compare(opcode, 0);
        compare(opcode, UINT64_MAX);
        compare(opcode, 0x8000000187654321ULL);
    }
    for (const auto wide : std::array{false, true}) {
        const auto width = wide ? 64U : 32U;
        for (const auto [immr, imms] : std::array{
                 std::pair{0U, 7U},
                 std::pair{1U, width - 1},
                 std::pair{width - 1, width - 2},
                 std::pair{width - 1, width - 1},
                 std::pair{8U, 15U},
                 std::pair{0U, width - 1}}) {
            const auto opcode = (wide ? 0xd3400000U : 0x53000000U) |
                (immr << 16) | (imms << 10) | (1U << 5) | 3U;
            compare(opcode, 0x8000000187654321ULL);
        }
    }
    expect(!transmute::decode_integer_block(
               0x140001000ULL, std::array{0x53401defU}) &&
               !transmute::decode_integer_block(
                   0x140001000ULL, std::array{0xd301fc20U}) &&
               !transmute::decode_integer_block(
                   0x140001000ULL, std::array{0x53201defU}) &&
               !transmute::decode_integer_block(
                   0x140001000ULL, std::array{0x53009defU}),
           "JIT accepted reserved unsigned bitfield encoding");
}

void test_jit_shifted_and_extended_arithmetic() {
    const auto compare = [](std::uint32_t arithmetic) {
        auto image = transmute::PeImage::parse(executable({
            arithmetic,
            0x54000040U, // b.eq +8, observing arithmetic NZCV
            0xd2800120U, // movz x0, #9 when not taken
            0xd65f03c0U
        }));
        transmute::ReferenceEngine reference(image);
        transmute::ReferenceEngine optimized(image);
        for (auto* engine : {&reference, &optimized}) {
            engine->set_initial_register(0, 0x87654321ULL);
            engine->set_initial_register(1, 0x8000000100000001ULL);
            engine->set_initial_register(2, 0xffffffff80000080ULL);
            engine->set_initial_register(8, 0xffffffffffffff80ULL);
            engine->set_initial_register(10, 0x12345678ULL);
            engine->set_initial_register(17, 8);
        }
        optimized.set_jit_enabled(true);
        const auto expected = reference.run();
        const auto actual = optimized.run();
        expect(actual.exit_code == expected.exit_code &&
                   actual.instructions == expected.instructions &&
                   optimized.state().x == reference.state().x &&
                   optimized.state().sp == reference.state().sp &&
                   optimized.state().pc == reference.state().pc &&
                   optimized.state().nzcv == reference.state().nzcv &&
                   optimized.jit_executed_instructions() >= 2,
               "JIT shifted/extended arithmetic differs from ReferenceEngine");
    };
    compare(0x0b00140aU); // Blender hot loop: add w10,w0,w0,lsl #5
    compare(0x0b288140U); // Blender hot loop: add w0,w10,w8,sxtb
    compare(0xcb3163f1U); // sub x17,sp,x17,uxtx
    for (const auto wide : {false, true}) {
        const auto width = wide ? 64U : 32U;
        for (const auto subtract : {false, true}) {
            for (const auto flags : {false, true}) {
                const auto bits = (wide ? 0x80000000U : 0U) |
                    (subtract ? 0x40000000U : 0U) |
                    (flags ? 0x20000000U : 0U);
                for (unsigned shift_type = 0; shift_type < 3; ++shift_type) {
                    for (const auto shift : std::array{
                             0U, 1U, 5U, width - 1}) {
                        compare(0x0b000000U | bits |
                                (shift_type << 22) | (2U << 16) |
                                (shift << 10) | (1U << 5) | 3U);
                    }
                }
                for (unsigned option = 0; option < 8; ++option) {
                    for (const auto shift : {0U, 4U}) {
                        compare(0x0b200000U | bits | (2U << 16) |
                                (option << 13) | (shift << 10) |
                                (1U << 5) | 3U);
                    }
                }
            }
        }
    }
    compare(0x8b2263ffU); // add sp,sp,x2,uxtx
    compare(0xeb2263ffU); // adds xzr,sp,x2,uxtx
    expect(!transmute::decode_integer_block(
               0x140001000ULL, std::array{0x0bc20023U}) &&
               !transmute::decode_integer_block(
                   0x140001000ULL, std::array{0x0b028023U}) &&
               !transmute::decode_integer_block(
                   0x140001000ULL, std::array{0x0b201423U}),
           "JIT accepted reserved shifted/extended arithmetic form");
}

void test_jit_scalar_float_bit_moves() {
    constexpr std::array opcodes{
        0x1e2e100bU, // fmov s11, #1.0
        0x1e6e100bU, // fmov d11, #1.0
        0x1e2c1010U, // fmov s16, #0.5
        0x1e7f1011U, // fmov d17, #-1.5
        0x1e204028U, // fmov s8, s1
        0x1e604028U, // fmov d8, d1
        0x1e604021U, // fmov d1, d1 (alias)
        0x1e214028U, // fneg s8, s1
        0x1e614028U, // fneg d8, d1
        0x1e614021U, // fneg d1, d1 (alias)
        0x1e20c028U, // fabs s8, s1
        0x1e60c028U, // fabs d8, d1
        0x1e60c021U, // fabs d1, d1 (alias)
        0x1e260008U, // fmov w8, s0
        0x9e660008U, // fmov x8, d0
        0x1e270088U, // fmov s8, w4
        0x9e670088U, // fmov d8, x4
        0x1e2703e8U, // fmov s8, wzr
        0x9e6703e8U, // fmov d8, xzr
        0x1e26001fU, // fmov wzr, s0
        0x9e66001fU, // fmov xzr, d0
    };
    for (const auto fpcr : {0U, 0x07c0ff00U}) {
        for (const auto opcode : opcodes) {
            auto image = transmute::PeImage::parse(executable({
                0xd51b4400U, // msr fpcr, x0
                0xd51b4421U, // msr fpsr, x1
                opcode,
                0xd65f03c0U,
            }));
            transmute::ReferenceEngine reference(image);
            reference.set_initial_register(0, fpcr);
            reference.set_initial_register(1, 0xa000001fU);
            reference.set_initial_register(4, 0xff800123cafef00dULL);
            reference.set_initial_vector(0, {0x7ff0000000000042ULL,
                                             0x123456789abcdef0ULL});
            reference.set_initial_vector(1, {0xffffffff7f800123ULL,
                                             0xfedcba9876543210ULL});
            reference.set_initial_vector(8, {UINT64_MAX, UINT64_MAX});
            auto native = reference.state();
            native.pc = image.entry() + 8;
            native.fpcr = fpcr;
            native.fpsr = 0xa000001fU;
            transmute::X64BlockCache cache;
            const std::array block{opcode, 0xd65f03c0U};
            expect(cache.execute(native, native.pc, block),
                   "JIT rejected scalar FP bit-move opcode");
            static_cast<void>(reference.run());
            const auto& expected = reference.state();
            expect(native.x == expected.x && native.v == expected.v &&
                       native.sp == expected.sp && native.pc == expected.pc &&
                       native.nzcv == expected.nzcv &&
                       native.fpcr == expected.fpcr &&
                       native.fpsr == expected.fpsr,
                   "JIT scalar FP bit movement differs from ReferenceEngine");

            transmute::ReferenceEngine dispatched(image);
            dispatched.set_initial_register(0, fpcr);
            dispatched.set_initial_register(1, 0xa000001fU);
            dispatched.set_initial_register(4, 0xff800123cafef00dULL);
            dispatched.set_initial_vector(0, {0x7ff0000000000042ULL,
                                              0x123456789abcdef0ULL});
            dispatched.set_initial_vector(1, {0xffffffff7f800123ULL,
                                              0xfedcba9876543210ULL});
            dispatched.set_initial_vector(8, {UINT64_MAX, UINT64_MAX});
            dispatched.set_jit_enabled(true);
            static_cast<void>(dispatched.run());
            expect(dispatched.state().x == expected.x &&
                       dispatched.state().v == expected.v &&
                       dispatched.state().fpcr == expected.fpcr &&
                       dispatched.state().fpsr == expected.fpsr &&
                       dispatched.jit_executed_instructions() >= 2,
                   "JIT dispatch did not preserve FP bit-move state");
        }
    }
    expect(!transmute::decode_integer_block(0x140001000ULL,
               std::array{0x1e61c020U}),
           "JIT accepted FP square root without status handling");
}

void benchmark_jit_float_bit_moves() {
    constexpr std::uint64_t iterations = 200'000;
    auto image = transmute::PeImage::parse(executable({
        0x1e604028U, // fmov d8, d1
        0x1e614109U, // fneg d9, d8
        0x1e60c12aU, // fabs d10, d9
        0xf1000400U, // subs x0, x0, #1
        0x54ffff81U, // b.ne back to fmov
        0xd65f03c0U,
    }));
    const auto measure = [&](bool jit) {
        transmute::ReferenceEngine engine(image);
        engine.set_initial_register(0, iterations);
        engine.set_initial_vector(1, {0x3ff8000000000000ULL, UINT64_MAX});
        engine.set_instruction_limit(iterations * 5 + 10);
        engine.set_jit_enabled(jit);
        const auto start = std::chrono::steady_clock::now();
        const auto result = engine.run();
        const auto elapsed = std::chrono::duration<double>(
            std::chrono::steady_clock::now() - start).count();
        expect(result.instructions == iterations * 5 + 1 &&
                   engine.state().v[10] ==
                       std::array<std::uint64_t, 2>{0x3ff8000000000000ULL, 0},
               "JIT scalar FP bit-move benchmark changed guest state");
        std::cout << (jit ? "jit" : "interpreter") << " scalar FP bit moves: "
                  << result.instructions << " guest instructions in "
                  << elapsed << " seconds; native guest instructions "
                  << engine.jit_executed_instructions() << '\n';
        return elapsed;
    };
    const auto baseline = measure(false);
    const auto compiled = measure(true);
    std::cout << "synthetic scalar-FP-bit-move jit/interpreter ratio: "
              << compiled / baseline << '\n';
}

void benchmark_jit_loop() {
    constexpr std::uint64_t iterations = 200'000;
    auto image = transmute::PeImage::parse(executable({
        0xd2800000U,
        0x91000400U,
        0xd1000421U,
        0xb5ffffc1U,
        0xd65f03c0U
    }));
    const auto measure = [&](bool jit) {
        transmute::ReferenceEngine engine(image);
        engine.set_initial_register(1, iterations);
        engine.set_instruction_limit(iterations * 4 + 10);
        engine.set_jit_enabled(jit);
        const auto start = std::chrono::steady_clock::now();
        const auto result = engine.run();
        const auto elapsed = std::chrono::duration<double>(
            std::chrono::steady_clock::now() - start).count();
        expect(result.exit_code == iterations &&
                   result.instructions == iterations * 3 + 2,
               "JIT benchmark loop returned the wrong guest result");
        std::cout << (jit ? "jit" : "interpreter") << ": "
                  << result.instructions << " guest instructions in "
                  << elapsed << " seconds; native block instructions "
                  << engine.jit_executed_instructions() << '\n';
        return elapsed;
    };
    const auto baseline = measure(false);
    const auto compiled = measure(true);
    std::cout << "jit/interpreter time ratio: " << compiled / baseline << '\n';
}

void benchmark_jit_memory() {
    constexpr std::uint64_t iterations = 200'000;
    constexpr std::uint64_t data = 0x500000000ULL;
    const auto measure = [&](bool store, bool jit) {
        auto image = transmute::PeImage::parse(executable({
            store ? 0x38001528U : 0x38401528U, // strb/ldrb w8,[x9],#1
            0xd1000421U, // sub x1,x1,#1
            0xb5ffffc1U, // cbnz x1,-8
            0xd65f03c0U
        }));
        transmute::ReferenceEngine engine(image);
        engine.map_memory(data, static_cast<std::size_t>(iterations));
        engine.set_initial_register(1, iterations);
        engine.set_initial_register(8, 0x5a);
        engine.set_initial_register(9, data);
        engine.set_instruction_limit(iterations * 3 + 10);
        engine.set_jit_enabled(jit);
        const auto start = std::chrono::steady_clock::now();
        const auto result = engine.run();
        const auto elapsed = std::chrono::duration<double>(
            std::chrono::steady_clock::now() - start).count();
        expect(result.instructions == iterations * 3 + 1 &&
                   engine.state().x[9] == data + iterations &&
                   (!store || static_cast<transmute::GuestMemory&>(engine).read8(
                       data + iterations - 1) == 0x5a),
               "JIT memory benchmark changed guest loop semantics");
        std::cout << (store ? "store" : "load") << ' '
                  << (jit ? "jit" : "interpreter") << ": "
                  << elapsed << " seconds; native guest instructions "
                  << engine.jit_executed_instructions() << '\n';
        return elapsed;
    };
    for (const bool store : {false, true}) {
        const auto baseline = measure(store, false);
        const auto compiled = measure(store, true);
        std::cout << (store ? "store" : "load")
                  << " jit/interpreter ratio: " << compiled / baseline << '\n';
    }
    const auto measure_signed_scan = [&](bool jit) {
        auto image = transmute::PeImage::parse(executable({
            0x38c01d09U, // ldrsb w9,[x8,#1]!: exact Blender startup fallback
            0x35ffffe9U, // cbnz w9,-4: exact next startup instruction
            0xd65f03c0U}));
        transmute::ReferenceEngine engine(image);
        engine.map_memory(data, static_cast<std::size_t>(iterations + 1));
        for (std::uint64_t index = 1; index != iterations; ++index) {
            static_cast<transmute::GuestMemory&>(engine).write8(data + index, 0x81);
        }
        engine.set_initial_register(8, data);
        engine.set_initial_register(9, UINT64_MAX);
        engine.set_instruction_limit(iterations * 2 + 10);
        engine.set_jit_enabled(jit);
        const auto start = std::chrono::steady_clock::now();
        const auto result = engine.run();
        const auto elapsed = std::chrono::duration<double>(
            std::chrono::steady_clock::now() - start).count();
        expect(result.instructions == iterations * 2 + 1 &&
                   engine.state().x[8] == data + iterations &&
                   engine.state().x[9] == 0 &&
                   (!jit || engine.jit_executed_instructions() == result.instructions),
               "JIT signed-byte scan benchmark changed guest loop semantics");
        std::cout << "signed-byte scan " << (jit ? "jit" : "interpreter")
                  << ": " << elapsed << " seconds; native guest instructions "
                  << engine.jit_executed_instructions() << '\n';
        return elapsed;
    };
    const auto baseline = measure_signed_scan(false);
    const auto compiled = measure_signed_scan(true);
    std::cout << "signed-byte scan jit/interpreter ratio: "
              << compiled / baseline << '\n';
}

void benchmark_wide_memory() {
    constexpr std::uint64_t mapped = 0x500000000ULL;
    constexpr unsigned iterations = 500'000;
    for (const bool image_memory : {false, true}) {
        for (const unsigned width : {4U, 8U}) {
            for (const bool store : {false, true}) {
                auto bytes = executable({0xd65f03c0});
                put32(bytes, 0x188 + 36, 0xe0000020);
                auto image = transmute::PeImage::parse(bytes);
                transmute::ReferenceEngine engine(image);
                engine.map_memory(mapped, 4096);
                const auto address = image_memory ? image.base() + 0x1100 : mapped;
                auto& memory = static_cast<transmute::GuestMemory&>(engine);
                memory.write64(address, 0x1234567887654321ULL);
                std::uint64_t checksum{};
                const auto start = std::chrono::steady_clock::now();
                for (unsigned index = 0; index < iterations; ++index) {
                    if (store) {
                        if (width == 4) memory.write32(address, index);
                        else memory.write64(address, index);
                    } else {
                        checksum += width == 4 ? memory.read32(address) : memory.read64(address);
                    }
                }
                const auto elapsed = std::chrono::duration<double>(
                    std::chrono::steady_clock::now() - start).count();
                if (store) {
                    expect((width == 4 ? memory.read32(address) : memory.read64(address)) ==
                               iterations - 1,
                           "wide memory benchmark changed stored value");
                } else {
                    expect(checksum == (width == 4 ? std::uint64_t{0x87654321}
                                                  : 0x1234567887654321ULL) * iterations,
                           "wide memory benchmark changed loaded value");
                }
                std::cout << (image_memory ? "image" : "mapped") << ' '
                          << (store ? "write" : "read") << width * 8 << ": "
                          << elapsed << " seconds\n";
            }
        }
    }
}

void benchmark_scoped_jit_memory() {
    constexpr std::uint64_t mapped = 0x500100000ULL;
    constexpr std::uint64_t iterations = 500'000;
    struct CheckedEngine final : transmute::ReferenceEngine {
        using ReferenceEngine::ReferenceEngine;
    };
    for (const bool image_memory : {false, true}) {
        for (const bool wide : {false, true}) {
            for (const bool store : {false, true}) {
                for (const bool scoped : {false, true}) {
                    auto bytes = executable({
                        store ? (wide ? 0xf9000100U : 0xb9000100U)
                              : (wide ? 0xf9400100U : 0xb9400100U),
                        // str/ldr x0/w0,[x8]
                        0xd1000421U, // sub x1,x1,#1
                        0xb5ffffc1U, // cbnz x1,-8
                        0xd65f03c0U
                    });
                    put16(bytes, 0x86, 2);
                    const auto data_section = 0x188U + 40;
                    put32(bytes, data_section + 8, 0x100);
                    put32(bytes, data_section + 12, 0x1800);
                    put32(bytes, data_section + 36, 0xc0000040);
                    auto image = transmute::PeImage::parse(bytes);
                    std::unique_ptr<transmute::ReferenceEngine> engine;
                    if (scoped) engine = std::make_unique<transmute::ReferenceEngine>(image);
                    else engine = std::make_unique<CheckedEngine>(image);
                    engine->map_memory(mapped, 64);
                    const auto data = image_memory ? image.base() + 0x1800 : mapped;
                    constexpr std::uint64_t value = 0x1234567887654321ULL;
                    engine->write64(data, value);
                    engine->set_initial_register(0, value);
                    engine->set_initial_register(1, iterations);
                    engine->set_initial_register(8, data);
                    engine->set_instruction_limit(iterations * 3 + 16);
                    engine->set_jit_enabled(true);
                    const std::array<std::uint64_t, 2> warm_arguments{value, 1000};
                    static_cast<void>(engine->invoke_callback(image.entry(), warm_arguments));
                    const auto start = std::chrono::steady_clock::now();
                    const auto result = engine->run();
                    const auto elapsed = std::chrono::duration<double>(
                        std::chrono::steady_clock::now() - start).count();
                    const auto expected = wide ? value : static_cast<std::uint32_t>(value);
                    expect(result.instructions == iterations * 3 + 1 &&
                               engine->state().x[1] == 0 &&
                               (store ? (wide ? engine->read64(data) : engine->read32(data))
                                      : engine->state().x[0]) == expected &&
                               engine->jit_executed_instructions() >= result.instructions,
                           "scoped JIT memory benchmark changed guest loop semantics");
                    std::cout << "scoped memory " << (image_memory ? "image" : "mapped")
                              << ' ' << (store ? "write" : "read") << (wide ? 64 : 32)
                              << ' ' << (scoped ? "scoped" : "checked") << ": "
                              << elapsed << " seconds\n";
                }
            }
        }
    }
}

void benchmark_jit_variable_shifts() {
    constexpr std::uint64_t iterations = 200'000;
    const auto measure = [=](bool jit) {
        auto image = transmute::PeImage::parse(executable({
            0x9ac82128U, // lslv x8,x9,x8: exact sampled Blender fallback
            0x9ad82128U, // lslv x8,x9,x24: exact sampled Blender fallback
            0xd1000421U, // sub x1,x1,#1
            0xb5ffffa1U, // cbnz x1,-12
            0xd65f03c0U}));
        transmute::ReferenceEngine engine(image);
        engine.set_initial_register(1, iterations);
        engine.set_initial_register(8, 2);
        engine.set_initial_register(9, 0x12345678);
        engine.set_initial_register(24, 65);
        engine.set_instruction_limit(iterations * 4 + 10);
        engine.set_jit_enabled(jit);
        const auto start = std::chrono::steady_clock::now();
        const auto result = engine.run();
        const auto elapsed = std::chrono::duration<double>(
            std::chrono::steady_clock::now() - start).count();
        expect(result.instructions == iterations * 4 + 1 &&
                   engine.state().x[1] == 0 && engine.state().x[8] == 0x2468acf0 &&
                   engine.state().x[9] == 0x12345678 && engine.state().x[24] == 65 &&
                   (!jit || engine.jit_executed_instructions() == result.instructions),
               "JIT variable-shift benchmark changed guest loop semantics");
        std::cout << "variable-shift loop " << (jit ? "jit" : "interpreter")
                  << ": " << elapsed << " seconds; native guest instructions "
                  << engine.jit_executed_instructions() << '\n';
        return elapsed;
    };
    const auto baseline = measure(false);
    const auto compiled = measure(true);
    std::cout << "variable-shift loop jit/interpreter ratio: "
              << compiled / baseline << '\n';
}
#endif

