void test_scheduler_and_event_hints() {
    auto image = transmute::PeImage::parse(executable({
        0xd503201f, // nop
        0x52800520, // mov w0, #41
        0xd503203f, // yield (seen in OpenImageIO_Util.dll spin loop)
        0x11000400, // add w0, w0, #1
        0xd65f03c0  // ret
    }));
    transmute::ReferenceEngine engine(image);
    expect(engine.run().exit_code == 42,
           "NOP/YIELD hint sequence changed guest result");
    for (const auto instruction : {
             0xd503205fU, // wfe
             0xd503207fU, // wfi
             0xd503209fU, // sev
             0xd50320bfU  // sevl
         }) {
        auto unsupported_image = transmute::PeImage::parse(executable({
            instruction, 0xd65f03c0
        }));
        transmute::ReferenceEngine unsupported(unsupported_image);
        expect_failure([&] { static_cast<void>(unsupported.run()); },
                       "guest event/interrupt hint is unsupported");
    }
}

void test_data_cache_zero_by_address() {
    constexpr std::uint64_t base = 0x60000000;
    auto image = transmute::PeImage::parse(executable({
        0xd53b00e1, // mrs x1, dczid_el0
        0xd50b7423, // dc zva, x3 (VCRUNTIME140.dll+0xf014)
        0xd65f03c0  // ret
    }));
    transmute::ReferenceEngine engine(image);
    engine.map_memory(base, 256);
    auto& memory = static_cast<transmute::GuestMemory&>(engine);
    for (unsigned offset = 0; offset < 256; ++offset) {
        memory.write8(base + offset, 0xa5);
    }
    engine.set_initial_register(3, base + 64 + 37);
    static_cast<void>(engine.run());
    expect(engine.state().x[1] == 4 &&
               engine.state().x[3] == base + 64 + 37,
           "DCZID_EL0 block size or DC ZVA address register changed");
    for (unsigned offset = 0; offset < 256; ++offset) {
        expect(memory.read8(base + offset) ==
                   (offset >= 64 && offset < 128 ? 0 : 0xa5),
               "DC ZVA did not zero only its naturally aligned 64-byte block");
    }

    auto protected_image = transmute::PeImage::parse(executable({
        0xd50b7423, 0xd65f03c0
    }));
    transmute::ReferenceEngine protected_engine(protected_image);
    protected_engine.map_memory(base, 64);
    protected_engine.set_memory_access(base, true, false, false);
    protected_engine.set_initial_register(3, base + 35);
    expect_failure([&] { static_cast<void>(protected_engine.run()); },
                   "guest write to read-only mapped memory");
    transmute::ReferenceEngine unmapped(protected_image);
    unmapped.set_initial_register(3, base + 35);
    expect_failure([&] { static_cast<void>(unmapped.run()); },
                   "guest write outside mapped memory");

    auto exclusive_image = transmute::PeImage::parse(executable({
        0xc85ffc81, // ldaxr x1, [x4]
        0xd50b7426, // dc zva, x6
        0xc803fc82, // stlxr w3, x2, [x4]
        0xd65f03c0
    }));
    transmute::ReferenceEngine exclusive(exclusive_image);
    const auto reserved = exclusive.state().sp - 64;
    exclusive.write64(reserved, 42);
    exclusive.set_initial_register(2, 99);
    exclusive.set_initial_register(4, reserved);
    exclusive.set_initial_register(6, reserved + 7);
    static_cast<void>(exclusive.run());
    expect(exclusive.state().x[1] == 42 && exclusive.state().x[3] == 1 &&
               exclusive.read64(reserved) == 0,
           "DC ZVA failed to invalidate an overlapping exclusive reservation");

#if defined(_WIN32) && (defined(_M_X64) || defined(__x86_64__))
    auto jit_image = transmute::PeImage::parse(executable({
        0xd50b7423, 0xd65f03c0
    }));
    transmute::ReferenceEngine jit(jit_image);
    constexpr std::uint64_t code = base + 0x1000;
    jit.map_memory(code, 64);
    jit.write32(code, 0xd2800540); // mov x0, #42
    jit.write32(code + 4, 0xd65f03c0); // ret
    jit.set_memory_access(code, true, true, true);
    jit.set_jit_enabled(true);
    jit.set_initial_register(3, code + 29);
    for (unsigned repeat = 0; repeat < 8; ++repeat) {
        expect(jit.invoke_callback(code, 0) == 42,
               "mapped executable code changed before DC ZVA");
    }
    expect(jit.jit_executed_instructions() != 0,
           "DC ZVA invalidation fixture did not warm the JIT cache");
    static_cast<void>(jit.run());
    expect_failure([&] { static_cast<void>(jit.invoke_callback(code, 0)); },
                   "unsupported ARM64 instruction 0x00000000");
#endif
}

