void test_non_temporal_pair_access() {
    {
        auto image = transmute::PeImage::parse(executable({
            0x286bca1b, // ldnp w27, w18, [x16, #-0xa4] (Blender)
            0xd65f03c0
        }));
        transmute::ReferenceEngine engine(image);
        const auto data = image.base() + image.size();
        engine.map_memory(data, 8);
        engine.write32(data, 0x80000001U);
        engine.write32(data + 4, 0x7ffffffeU);
        engine.set_initial_register(16, data + 0xa4);
        engine.set_initial_register(27, UINT64_MAX);
        engine.set_initial_register(18, UINT64_MAX);
        static_cast<void>(engine.run());
        expect(engine.state().x[27] == 0x80000001U &&
                   engine.state().x[18] == 0x7ffffffeU &&
                   engine.state().x[16] == data + 0xa4,
               "non-temporal W pair load lost offset, zero-extension, or base");
    }
    {
        auto image = transmute::PeImage::parse(executable({
            0xa800e000, // stnp x0, x24, [x0, #8] (runtime library)
            0xa8409805, // ldnp x5, x6, [x0, #8]
            0xd65f03c0
        }));
        transmute::ReferenceEngine engine(image);
        const auto data = image.base() + image.size();
        engine.map_memory(data, 16);
        engine.set_initial_register(0, data - 8);
        engine.set_initial_register(24, 0x8123456789abcdefULL);
        static_cast<void>(engine.run());
        expect(engine.read64(data) == data - 8 &&
                   engine.read64(data + 8) == 0x8123456789abcdefULL &&
                   engine.state().x[5] == data - 8 &&
                   engine.state().x[6] == 0x8123456789abcdefULL &&
                   engine.state().x[0] == data - 8,
               "non-temporal X pair store/load did not preserve offset or base");
    }
    {
        auto image = transmute::PeImage::parse(executable({
            0x2c000821, // stnp s1, s2, [x1]
            0x2c401023, // ldnp s3, s4, [x1]
            0xd65f03c0
        }));
        transmute::ReferenceEngine engine(image);
        const auto data = image.base() + image.size();
        engine.map_memory(data, 8);
        engine.set_initial_register(1, data);
        engine.set_initial_vector(1, {0x1234567880000001ULL, UINT64_MAX});
        engine.set_initial_vector(2, {0xabcdef017ffffffeULL, UINT64_MAX});
        static_cast<void>(engine.run());
        expect(engine.state().v[3] ==
                   std::array<std::uint64_t, 2>{0x80000001ULL, 0} &&
                   engine.state().v[4] ==
                   std::array<std::uint64_t, 2>{0x7ffffffeULL, 0} &&
                   engine.state().x[1] == data,
               "non-temporal S pair did not transfer exact scalar widths");
    }
    {
        auto image = transmute::PeImage::parse(executable({
            0x6c6a5a59, // ldnp d25, d22, [x18, #-0x160] (runtime library)
            0xd65f03c0
        }));
        transmute::ReferenceEngine engine(image);
        const auto data = image.base() + image.size();
        engine.map_memory(data, 16);
        engine.write64(data, 0x1122334455667788ULL);
        engine.write64(data + 8, 0x99aabbccddeeff00ULL);
        engine.set_initial_register(18, data + 0x160);
        engine.set_initial_vector(25, {0, UINT64_MAX});
        engine.set_initial_vector(22, {0, UINT64_MAX});
        static_cast<void>(engine.run());
        expect(engine.state().v[25] ==
                   std::array<std::uint64_t, 2>{0x1122334455667788ULL, 0} &&
                   engine.state().v[22] ==
                   std::array<std::uint64_t, 2>{0x99aabbccddeeff00ULL, 0} &&
                   engine.state().x[18] == data + 0x160,
               "non-temporal D pair load did not clear upper halves");
    }
    {
        auto image = transmute::PeImage::parse(executable({
            0xac083127, // stnp q7, q12, [x9, #0x100] (Blender)
            0xac48392d, // ldnp q13, q14, [x9, #0x100]
            0xd65f03c0
        }));
        transmute::ReferenceEngine engine(image);
        const auto data = image.base() + image.size();
        engine.map_memory(data, 32);
        engine.set_initial_register(9, data - 0x100);
        engine.set_initial_vector(7, {0x0123456789abcdefULL,
                                      0xfedcba9876543210ULL});
        engine.set_initial_vector(12, {0x0011223344556677ULL,
                                       0x8899aabbccddeeffULL});
        static_cast<void>(engine.run());
        expect(engine.state().v[13] == engine.state().v[7] &&
                   engine.state().v[14] == engine.state().v[12] &&
                   engine.state().x[9] == data - 0x100,
               "non-temporal Q pair failed 128-bit round-trip");
    }
    {
        auto image = transmute::PeImage::parse(executable({
            0x2840021b, // ldnp w27, w0, [x16], second word unmapped
            0xd65f03c0
        }));
        transmute::ReferenceEngine engine(image);
        const auto data = image.base() + image.size();
        engine.map_memory(data, 8);
        engine.set_initial_register(16, data + 4);
        engine.set_initial_register(27, 0x12345678);
        engine.set_initial_register(0, 0x87654321);
        expect_failure([&] { static_cast<void>(engine.run()); },
                       "guest read outside mapped memory");
        expect(engine.state().x[27] == 0x12345678 &&
                   engine.state().x[0] == 0x87654321 &&
                   engine.state().x[16] == data + 4,
               "failed non-temporal pair load changed registers");
    }
}

void test_sign_extended_pair_load() {
    auto image = transmute::PeImage::parse(executable({
        0x69421dce, // ldpsw x14, x7, [x14, #16] (oslexec.dll)
        0x69c135ec, // ldpsw x12, x13, [x15, #8]!
        0x68c14a11, // ldpsw x17, x18, [x16], #8
        0xd65f03c0  // ret
    }));
    transmute::ReferenceEngine engine(image);
    const auto data = image.base() + image.size();
    engine.map_memory(data, 4096);
    engine.write32(data, 0x80000001U);
    engine.write32(data + 4, 0x7ffffffeU);
    engine.set_initial_register(14, data - 16);
    engine.set_initial_register(15, data - 8);
    engine.set_initial_register(16, data);
    static_cast<void>(engine.run());
    const auto& state = engine.state();
    expect(state.x[14] == 0xffffffff80000001ULL &&
               state.x[7] == 0x7ffffffeULL &&
               state.x[12] == 0xffffffff80000001ULL &&
               state.x[13] == 0x7ffffffeULL && state.x[15] == data &&
               state.x[17] == 0xffffffff80000001ULL &&
               state.x[18] == 0x7ffffffeULL && state.x[16] == data + 8,
           "LDPSW pair loads did not sign-extend or update their base");
}

