void test_relocated_fixture(const char* path) {
    std::ifstream input(path, std::ios::binary);
    expect(static_cast<bool>(input), "cannot open ARM64 relocation fixture");
    const std::vector<std::uint8_t> bytes{std::istreambuf_iterator<char>(input),
                                           std::istreambuf_iterator<char>()};
    constexpr std::uint64_t alternate_base = 0x180000000ULL;
    auto image = transmute::PeImage::parse(bytes, alternate_base);
    expect(image.preferred_base() == 0x140000000ULL && image.base() == alternate_base,
           "PE image load base was not changed");
    transmute::ReferenceEngine engine(image);
    expect(engine.run().exit_code == 42, "relocated ARM64 image returned wrong value");

    auto lower_image = transmute::PeImage::parse(bytes, 0x120000000ULL);
    transmute::ReferenceEngine lower_engine(lower_image);
    expect(lower_engine.run().exit_code == 42, "downward relocation returned wrong value");

    auto missing_relocations = bytes;
    const auto pe = get32(bytes, 0x3c);
    put32(missing_relocations, pe + 24 + 152, 0);
    expect_failure([&] { transmute::PeImage::parse(missing_relocations, alternate_base); },
                   "cannot be loaded away from its preferred base");

    const auto section_table = pe + 24 + get16(bytes, pe + 20);
    std::size_t relocation_file_offset = 0;
    for (std::size_t i = 0; i < get16(bytes, pe + 6); ++i) {
        const auto section = section_table + i * 40;
        if (std::string_view(reinterpret_cast<const char*>(bytes.data() + section), 6) ==
            ".reloc") {
            relocation_file_offset = get32(bytes, section + 20);
        }
    }
    expect(relocation_file_offset != 0, "compiled fixture has no relocation section");
    auto unsupported_type = bytes;
    put16(unsupported_type, relocation_file_offset + 8,
          static_cast<std::uint16_t>((get16(bytes, relocation_file_offset + 8) & 0x0fffU) |
                                     0xb000U));
    expect_failure([&] { transmute::PeImage::parse(unsupported_type, alternate_base); },
                   "unsupported PE relocation type");

    auto invalid_block = bytes;
    put32(invalid_block, relocation_file_offset + 4, 0xffffU);
    expect_failure([&] { transmute::PeImage::parse(invalid_block, alternate_base); },
                   "invalid PE relocation block");
}

void test_guest_dll_fixture(const char* application_path) {
    transmute::GuestProcess process(application_path);
    expect(process.modules().size() == 3, "transitive guest DLLs were not loaded");
    expect(process.modules()[1]->is_dll() && process.modules()[1]->entry_rva() != 0 &&
               process.modules()[1]->find_export("guest_answer").has_value(),
           "initialized guest DLL export was not found");
    expect(process.modules()[1]->preferred_base() == process.executable().base() &&
               process.modules()[1]->base() != process.modules()[1]->preferred_base(),
           "colliding guest DLL was not relocated");
    expect(process.executable().imports().size() == 2,
           "guest application function and data imports were not parsed");
    expect(process.modules()[1]->imports().size() == 1 &&
               process.modules()[1]->imports()[0].entry == 0 &&
               process.modules()[2]->find_export("guest_leaf_answer").has_value(),
           "transitive guest DLL import was not bound");
    for (const auto& imported : process.executable().imports()) {
        expect(imported.entry == 0, "guest application import was not bound");
        const auto target = process.modules()[1]->find_export(imported.function);
        expect(target.has_value(), "guest DLL export was not found");
        std::uint64_t iat_target = 0;
        const auto iat = process.executable().base() + imported.iat_rva;
        for (unsigned byte = 0; byte < 8; ++byte) {
            iat_target |= static_cast<std::uint64_t>(process.executable().read8(iat + byte))
                          << (byte * 8);
        }
        expect(iat_target == *target, "guest import address table points to wrong export");
    }
    transmute::ReferenceEngine before_attach(process.executable());
    before_attach.add_module(*process.modules()[1]);
    before_attach.add_module(*process.modules()[2]);
    expect(before_attach.run().exit_code == 56,
           "DLL initialization fixture did not detect missing process attach");
    transmute::ReferenceEngine engine(process.executable());
    engine.add_module(*process.modules()[1]);
    engine.add_module(*process.modules()[2]);
    expect_failure([&] { engine.add_module(*process.modules()[1]); },
                   "guest modules overlap");
    expect(process.attachment_order().size() == 2 &&
               process.attachment_order()[0] == process.modules()[2].get() &&
               process.attachment_order()[1] == process.modules()[1].get(),
           "DLL process attach order does not follow dependencies");
    engine.initialize_dlls(process.attachment_order());
    expect(engine.run().exit_code == 42, "ARM64 call into guest DLL returned wrong value");

#ifdef _WIN32
    transmute::Win32Bridge bridge;
    for (const auto& module : process.modules()) {
        bridge.register_guest_module(*module);
    }
    transmute::CpuState disable_threads{};
    disable_threads.x[0] = process.modules()[1]->base();
    static_cast<void>(bridge.dispatch(
        {"kernel32.dll", "DisableThreadLibraryCalls", 0},
        disable_threads, engine));
    expect(disable_threads.x[0] == 1,
           "guest DLL could not disable thread notifications");
    const auto symbol = engine.state().sp - 64;
    const char* symbol_name = "guest_answer";
    auto& memory = static_cast<transmute::GuestMemory&>(engine);
    for (std::size_t index = 0; symbol_name[index] != 0; ++index) {
        memory.write8(symbol + index,
                      static_cast<std::uint8_t>(symbol_name[index]));
    }
    memory.write8(symbol + 12, 0);
    transmute::CpuState lookup{};
    lookup.x[0] = process.modules()[1]->base();
    lookup.x[1] = symbol;
    static_cast<void>(bridge.dispatch(
        {"kernel32.dll", "GetProcAddress", 0}, lookup, engine));
    expect(lookup.x[0] == *process.modules()[1]->find_export(symbol_name),
           "GetProcAddress did not return the ARM64 guest DLL export");
#endif

    expect_failure([&] {
        transmute::ReferenceEngine invalid(*process.modules()[1]);
    }, "cannot run a DLL as an executable");

    const auto library_path = std::filesystem::path(application_path).parent_path() /
                              "guest_library.dll";
    std::ifstream input(library_path, std::ios::binary);
    expect(static_cast<bool>(input), "cannot open guest DLL fixture");
    std::vector<std::uint8_t> library{std::istreambuf_iterator<char>(input),
                                      std::istreambuf_iterator<char>()};
    const auto pe = get32(library, 0x3c);
    const auto optional = pe + 24;
    expect(get32(library, optional + 112) != 0, "compiled DLL has no exports");
    put32(library, optional + 116, 39);
    expect_failure([&] { transmute::PeImage::parse(library); },
                   "invalid PE export directory");
}

#ifdef _WIN32
void test_dynamic_guest_dll_search(const char* application_path) {
    transmute::GuestProcess process(application_path);
    transmute::ReferenceEngine engine(process.executable());
    for (std::size_t index = 1; index < process.modules().size(); ++index) {
        engine.add_module(*process.modules()[index]);
    }
    auto worker = engine.fork_thread(process.executable().entry(), 0);
    transmute::Win32Bridge bridge;
    for (const auto& module : process.modules()) bridge.register_guest_module(*module);
    bridge.set_guest_dll_loader([&](const std::filesystem::path& path,
                                    const std::vector<std::filesystem::path>& directories,
                                    bool include_requested_directory,
                                    transmute::ReferenceEngine& caller) {
        return bridge.load_guest_dll(process, path, directories,
                                     include_requested_directory, caller);
    });
    const auto directory = std::filesystem::temp_directory_path() /
        ("transmute-dynamic-dll-" + std::to_string(GetCurrentProcessId()));
    std::filesystem::create_directories(directory);
    const auto source = std::filesystem::path(application_path).parent_path() /
        "guest_leaf.dll";
    const auto first = directory / "dynamic_first.dll";
    const auto second = directory / "dynamic_second.dll";
    const auto third = directory / "dynamic_third.dll";
    std::ifstream source_file(source, std::ios::binary);
    expect(static_cast<bool>(source_file), "dynamic DLL source fixture is missing");
    const std::vector<std::uint8_t> source_bytes{
        std::istreambuf_iterator<char>(source_file), std::istreambuf_iterator<char>()};
    const auto write_fixture = [&](const std::filesystem::path& target,
                                   std::uint64_t preferred_base) {
        auto bytes = source_bytes;
        put64(bytes, get32(bytes, 0x3c) + 24 + 24, preferred_base);
        std::ofstream output(target, std::ios::binary | std::ios::trunc);
        output.write(reinterpret_cast<const char*>(bytes.data()),
                     static_cast<std::streamsize>(bytes.size()));
        expect(static_cast<bool>(output), "dynamic DLL fixture write failed");
    };
    write_fixture(first, 0x1a0000000ULL);
    write_fixture(second, 0x1b0000000ULL);
    write_fixture(third, 0x1c0000000ULL);
    auto& memory = static_cast<transmute::GuestMemory&>(engine);
    const auto buffer = engine.state().sp - 2048;
    const auto write_wide = [&](std::uint64_t address, std::wstring_view value) {
        for (std::size_t index = 0; index <= value.size(); ++index) {
            const auto unit = static_cast<std::uint16_t>(
                index == value.size() ? 0 : value[index]);
            memory.write8(address + index * 2, static_cast<std::uint8_t>(unit));
            memory.write8(address + index * 2 + 1,
                          static_cast<std::uint8_t>(unit >> 8));
        }
    };
    const auto load = [&](std::wstring_view name, DWORD flags) {
        write_wide(buffer, name);
        transmute::CpuState call{};
        call.x[0] = buffer;
        call.x[2] = flags;
        SetLastError(ERROR_SUCCESS);
        static_cast<void>(bridge.dispatch(
            {"kernel32.dll", "LoadLibraryExW", 0}, call, engine));
        return call.x[0];
    };
    expect(load(L"dynamic_first.dll", 0) == 0 &&
               GetLastError() == ERROR_MOD_NOT_FOUND,
           "AddDllDirectory search was used before registration");
    write_wide(buffer + 512, directory.wstring());
    transmute::CpuState call{};
    call.x[0] = buffer + 512;
    static_cast<void>(bridge.dispatch(
        {"kernel32.dll", "AddDllDirectory", 0}, call, engine));
    const auto cookie = call.x[0];
    expect(cookie != 0, "guest DLL search directory was not registered");
    expect(load(L"dynamic_first.dll", 0) == 0 &&
               GetLastError() == ERROR_MOD_NOT_FOUND,
           "AddDllDirectory incorrectly changed unflagged search");
    const auto base = load(L"dynamic_first.dll", LOAD_LIBRARY_SEARCH_USER_DIRS);
    expect(base != 0 && process.modules().size() == 4,
           "LoadLibraryExW did not load an ARM64 DLL from user directories");
    const auto export_address = process.modules().back()->find_export(
        "guest_leaf_answer");
    expect(export_address && worker->invoke_callback(*export_address,
                          std::span<const std::uint64_t>{}) == 42,
           "preexisting guest worker could not execute runtime DLL export");
    expect(load(L"dynamic_first.dll", 0) == base,
           "already loaded runtime DLL did not retain its module handle");
    call.x[0] = cookie;
    static_cast<void>(bridge.dispatch(
        {"kernel32.dll", "RemoveDllDirectory", 0}, call, engine));
    expect(call.x[0] == 1 &&
               load(L"dynamic_second.dll", LOAD_LIBRARY_SEARCH_USER_DIRS) == 0 &&
               GetLastError() == ERROR_MOD_NOT_FOUND,
           "RemoveDllDirectory left its path searchable");
    expect(load(first.wstring(), 0) == base,
           "absolute path to loaded guest DLL changed its handle");
    call.x[0] = LOAD_LIBRARY_SEARCH_USER_DIRS;
    static_cast<void>(bridge.dispatch(
        {"kernel32.dll", "SetDefaultDllDirectories", 0}, call, engine));
    expect(call.x[0] == 1, "guest default DLL search flags were rejected");
    call.x[0] = buffer + 512;
    static_cast<void>(bridge.dispatch(
        {"kernel32.dll", "AddDllDirectory", 0}, call, engine));
    const auto second_cookie = call.x[0];
    expect(second_cookie != 0 && load(L"dynamic_third.dll", 0) != 0,
           "default USER_DIRS search omitted AddDllDirectory path");
    call.x[0] = second_cookie;
    static_cast<void>(bridge.dispatch(
        {"kernel32.dll", "RemoveDllDirectory", 0}, call, engine));
    std::filesystem::remove(first);
    std::filesystem::remove(second);
    std::filesystem::remove(third);
    std::filesystem::remove(directory);
}

void test_dynamic_guest_dll_lifecycle(const char* application_path) {
    const auto root = std::filesystem::temp_directory_path() /
        ("transmute-runtime-attach-" + std::to_string(GetCurrentProcessId()));
    const auto directory = root / "dlls";
    std::filesystem::create_directories(directory);
    const auto executable_path = root / "runtime_host.exe";
    const auto host_bytes = executable({0xd65f03c0});
    {
        std::ofstream output(executable_path, std::ios::binary | std::ios::trunc);
        output.write(reinterpret_cast<const char*>(host_bytes.data()),
                     static_cast<std::streamsize>(host_bytes.size()));
        expect(static_cast<bool>(output), "runtime host fixture write failed");
    }
    const auto fixtures = std::filesystem::path(application_path).parent_path();
    for (const auto name : {"guest_library.dll", "guest_leaf.dll",
                            "guest_fail.dll"}) {
        std::filesystem::copy_file(fixtures / name, directory / name,
            std::filesystem::copy_options::overwrite_existing);
    }
    transmute::GuestProcess process(executable_path);
    transmute::ReferenceEngine engine(process.executable());
    transmute::Win32Bridge bridge;
    bridge.register_guest_module(process.executable());
    bridge.initialize_thread_environment(engine, process.executable().base());
    bridge.initialize_static_tls(engine);
    auto worker = engine.fork_thread(process.executable().entry(), 0);
    bridge.set_guest_dll_loader([&](const std::filesystem::path& path,
                                    const std::vector<std::filesystem::path>& search,
                                    bool include_directory,
                                    transmute::ReferenceEngine& caller) {
        return bridge.load_guest_dll(process, path, search,
                                     include_directory, caller);
    });
    auto& memory = static_cast<transmute::GuestMemory&>(engine);
    const auto buffer = engine.state().sp - 2048;
    const auto write_wide = [&](std::uint64_t address, std::wstring_view value) {
        for (std::size_t index = 0; index <= value.size(); ++index) {
            const auto unit = static_cast<std::uint16_t>(
                index == value.size() ? 0 : value[index]);
            memory.write8(address + index * 2, static_cast<std::uint8_t>(unit));
            memory.write8(address + index * 2 + 1,
                          static_cast<std::uint8_t>(unit >> 8));
        }
    };
    write_wide(buffer + 512, directory.wstring());
    transmute::CpuState call{};
    call.x[0] = buffer + 512;
    static_cast<void>(bridge.dispatch(
        {"kernel32.dll", "AddDllDirectory", 0}, call, engine));
    const auto cookie = call.x[0];
    expect(cookie != 0, "runtime fixture DLL directory was not registered");
    const auto load = [&](std::wstring_view name) {
        write_wide(buffer, name);
        transmute::CpuState request{};
        request.x[0] = buffer;
        request.x[2] = LOAD_LIBRARY_SEARCH_USER_DIRS;
        SetLastError(ERROR_SUCCESS);
        static_cast<void>(bridge.dispatch(
            {"kernel32.dll", "LoadLibraryExW", 0}, request, engine));
        return std::pair{request.x[0], GetLastError()};
    };
    const auto [library_base, library_error] = load(L"guest_library.dll");
    static_cast<void>(library_error);
    expect(library_base != 0 && process.modules().size() == 3,
           "runtime DLL dependency closure was not loaded");
    auto* library = process.modules()[1].get();
    auto* leaf = process.modules()[2].get();
    expect(library->base() == library_base &&
               library->imports().size() == 1 &&
               library->imports()[0].entry == 0 &&
               leaf->find_export("guest_leaf_answer").has_value(),
           "runtime ARM64 import was not bound to its dependency");
    const auto answer = library->find_export("guest_answer");
    expect(answer && worker->invoke_callback(*answer,
                          std::span<const std::uint64_t>{}) == 42,
           "runtime DLL process attach or preexisting-worker visibility failed");
    const auto count_before_failure = process.modules().size();
    const auto [failed_base, failure_error] = load(L"guest_fail.dll");
    expect(failed_base == 0 && failure_error == ERROR_DLL_INIT_FAILED &&
               process.modules().size() == count_before_failure,
           "failed guest DllMain was not rolled back transactionally");
    write_wide(buffer, L"guest_fail.dll");
    call = {};
    call.x[0] = buffer;
    static_cast<void>(bridge.dispatch(
        {"kernel32.dll", "GetModuleHandleW", 0}, call, engine));
    expect(call.x[0] == 0 && GetLastError() == ERROR_MOD_NOT_FOUND,
           "failed guest DLL remained visible to module lookup");
    std::ifstream leaf_input(fixtures / "guest_leaf.dll", std::ios::binary);
    const std::vector<std::uint8_t> leaf_bytes{
        std::istreambuf_iterator<char>(leaf_input), std::istreambuf_iterator<char>()};
    auto replacement = leaf_bytes;
    put64(replacement, get32(replacement, 0x3c) + 24 + 24, 0x1d0000000ULL);
    {
        std::ofstream output(directory / "post_failure.dll",
                             std::ios::binary | std::ios::trunc);
        output.write(reinterpret_cast<const char*>(replacement.data()),
                     static_cast<std::streamsize>(replacement.size()));
    }
    const auto [replacement_base, replacement_error] = load(L"post_failure.dll");
    static_cast<void>(replacement_error);
    expect(replacement_base == 0x1d0000000ULL &&
               process.modules().size() == count_before_failure + 1,
           "failed attach left its address or registry entry reserved");
    call.x[0] = cookie;
    static_cast<void>(bridge.dispatch(
        {"kernel32.dll", "RemoveDllDirectory", 0}, call, engine));
    std::filesystem::remove_all(root);
}

void test_dynamic_guest_dll_tls() {
    constexpr std::uint64_t dll_base = 0x1e0000000ULL;
    const auto root = std::filesystem::temp_directory_path() /
        ("transmute-runtime-tls-" + std::to_string(GetCurrentProcessId()));
    std::filesystem::create_directories(root);
    const auto host_path = root / "host.exe";
    const auto write_file = [](const std::filesystem::path& path,
                               const std::vector<std::uint8_t>& bytes) {
        std::ofstream output(path, std::ios::binary | std::ios::trunc);
        output.write(reinterpret_cast<const char*>(bytes.data()),
                     static_cast<std::streamsize>(bytes.size()));
        expect(static_cast<bool>(output), "runtime TLS fixture write failed");
    };
    write_file(host_path, executable({0xd65f03c0}));
    auto dll_bytes = executable({0xd65f03c0, 0xd65f03c0});
    put16(dll_bytes, 0x96, 0x2002); // IMAGE_FILE_DLL | executable image
    put64(dll_bytes, 0x98 + 24, dll_base);
    put32(dll_bytes, 0x98 + 184, 0x1100);
    put32(dll_bytes, 0x98 + 188, 40);
    put32(dll_bytes, 0x188 + 36, 0xe0000020);
    put64(dll_bytes, 0x300, dll_base + 0x1140);
    put64(dll_bytes, 0x308, dll_base + 0x1144);
    put64(dll_bytes, 0x310, dll_base + 0x1150);
    put64(dll_bytes, 0x318, dll_base + 0x1160);
    put32(dll_bytes, 0x320, 4);
    put32(dll_bytes, 0x340, 0xaabbccdd);
    put64(dll_bytes, 0x360, dll_base + 0x1004);
    write_file(root / "runtime_tls.dll", dll_bytes);
    transmute::GuestProcess process(host_path);
    transmute::ReferenceEngine engine(process.executable());
    transmute::Win32Bridge bridge;
    bridge.register_guest_module(process.executable());
    bridge.initialize_thread_environment(engine, process.executable().base());
    bridge.initialize_static_tls(engine);
    bridge.set_guest_dll_loader([&](const std::filesystem::path& path,
                                    const std::vector<std::filesystem::path>& search,
                                    bool include_directory,
                                    transmute::ReferenceEngine& caller) {
        return bridge.load_guest_dll(process, path, search,
                                     include_directory, caller);
    });
    auto worker = engine.fork_thread(process.executable().entry(), 0);
    std::atomic<bool> ready{false};
    std::atomic<bool> release{false};
    std::uint64_t worker_tls_data{};
    std::exception_ptr worker_failure;
    std::thread worker_thread([&] {
        try {
            bridge.initialize_worker_thread_environment(
                *worker, process.executable().base());
            ready.store(true, std::memory_order_release);
            while (!release.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }
            const auto array = worker->read64(worker->state().x[18] + 0x58);
            worker_tls_data = worker->read64(array);
            if (worker_tls_data != 0 &&
                worker->read32(worker_tls_data) != 0xaabbccdd) {
                throw std::runtime_error("existing worker TLS template was wrong");
            }
            bridge.cleanup_worker_thread(*worker);
        } catch (...) {
            worker_failure = std::current_exception();
            ready.store(true, std::memory_order_release);
        }
    });
    while (!ready.load(std::memory_order_acquire)) std::this_thread::yield();
    auto& memory = static_cast<transmute::GuestMemory&>(engine);
    const auto path_address = engine.state().sp - 512;
    const auto write_wide = [&](std::wstring_view value) {
        for (std::size_t index = 0; index <= value.size(); ++index) {
            const auto unit = static_cast<std::uint16_t>(
                index == value.size() ? 0 : value[index]);
            memory.write8(path_address + index * 2,
                          static_cast<std::uint8_t>(unit));
            memory.write8(path_address + index * 2 + 1,
                          static_cast<std::uint8_t>(unit >> 8));
        }
    };
    const auto load = [&](std::wstring_view name) {
        write_wide(name);
        transmute::CpuState state{};
        state.x[0] = path_address;
        SetLastError(ERROR_SUCCESS);
        static_cast<void>(bridge.dispatch(
            {"kernel32.dll", "LoadLibraryExW", 0}, state, engine));
        return std::pair{state.x[0], GetLastError()};
    };
    std::uint64_t base{};
    try {
        base = bridge.load_guest_dll(
            process, root / "runtime_tls.dll", {root}, false, engine);
    } catch (...) {
        release.store(true, std::memory_order_release);
        worker_thread.join();
        throw;
    }
    release.store(true, std::memory_order_release);
    worker_thread.join();
    if (worker_failure) std::rethrow_exception(worker_failure);
    expect(base == dll_base && worker_tls_data != 0 &&
               process.modules().size() == 2,
           "runtime TLS DLL did not initialize an existing guest worker: base=" +
               std::to_string(base) + " worker_tls=" +
               std::to_string(worker_tls_data) + " modules=" +
               std::to_string(process.modules().size()));
    const auto& tls = *process.modules().back()->tls();
    const auto array = engine.read64(engine.state().x[18] + 0x58);
    const auto data = engine.read64(array);
    expect(engine.read32(tls.index_address) == 0 && data != 0 &&
               engine.read32(data) == 0xaabbccdd && engine.read32(data + 4) == 0,
           "runtime TLS index/template was not initialized on the loading thread");
    auto bad_bytes = dll_bytes;
    constexpr std::uint64_t bad_base = 0x1f0000000ULL;
    put64(bad_bytes, 0x98 + 24, bad_base);
    put64(bad_bytes, 0x300, bad_base + 0x1140);
    put64(bad_bytes, 0x308, bad_base + 0x1144);
    put64(bad_bytes, 0x310, bad_base + 0x1150);
    put64(bad_bytes, 0x318, bad_base + 0x1160);
    put64(bad_bytes, 0x360, bad_base + 0x1004);
    put32(bad_bytes, 0x204, 0); // Force the TLS callback to fault.
    write_file(root / "runtime_tls_bad.dll", bad_bytes);
    const auto before_failure = process.modules().size();
    const auto [failed, failure_error] = load(
        (root / "runtime_tls_bad.dll").wstring());
    expect(failed == 0 && failure_error == ERROR_NOT_SUPPORTED &&
               process.modules().size() == before_failure &&
               engine.read64(array + 8) == 0,
           "failed runtime TLS callback left its slot or module published");
    std::filesystem::remove_all(root);
}

void test_dynamic_guest_dll_publication_gate() {
    constexpr std::uint64_t dll_base = 0x1e1000000ULL;
    const auto root = std::filesystem::temp_directory_path() /
        ("transmute-runtime-publish-" + std::to_string(GetCurrentProcessId()));
    std::filesystem::create_directories(root);
    const auto host_path = root / "host.exe";
    const auto dll_path = root / "publish.dll";
    const auto write_file = [](const std::filesystem::path& path,
                               const std::vector<std::uint8_t>& bytes) {
        std::ofstream output(path, std::ios::binary | std::ios::trunc);
        output.write(reinterpret_cast<const char*>(bytes.data()),
                     static_cast<std::streamsize>(bytes.size()));
        expect(static_cast<bool>(output), "publication fixture write failed");
    };
    write_file(host_path, executable({0xd65f03c0}));
    transmute::GuestProcess process(host_path);
    transmute::ReferenceEngine engine(process.executable());
    transmute::Win32Bridge bridge;
    bridge.register_guest_module(process.executable());
    bridge.initialize_thread_environment(engine, process.executable().base());
    bridge.initialize_static_tls(engine);
    const auto wait_until = [](auto predicate, const char* message) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(5);
        while (!predicate()) {
            if (std::chrono::steady_clock::now() >= deadline) {
                throw std::runtime_error(message);
            }
            std::this_thread::yield();
        }
    };
    std::atomic<bool> attach_entered{false};
    std::atomic<bool> release_attach{false};
    const auto hook = engine.register_guest_call(
        [&](transmute::CpuState& callback, transmute::GuestMemory&) {
            attach_entered.store(true, std::memory_order_release);
            wait_until([&] { return release_attach.load(std::memory_order_acquire); },
                       "publication fixture did not release process attach");
            callback.x[0] = 1;
        });
    auto dll_bytes = executable({0x58000049, 0xd61f0120, 0, 0});
    put16(dll_bytes, 0x96, 0x2002);
    put64(dll_bytes, 0x98 + 24, dll_base);
    put64(dll_bytes, 0x208, hook);
    write_file(dll_path, dll_bytes);
    const auto name_address = engine.state().sp - 256;
    auto& memory = static_cast<transmute::GuestMemory&>(engine);
    constexpr std::wstring_view name = L"publish.dll";
    for (std::size_t index = 0; index <= name.size(); ++index) {
        const auto unit = static_cast<std::uint16_t>(
            index == name.size() ? 0 : name[index]);
        memory.write8(name_address + index * 2,
                      static_cast<std::uint8_t>(unit));
        memory.write8(name_address + index * 2 + 1,
                      static_cast<std::uint8_t>(unit >> 8));
    }
    auto worker = engine.fork_thread(process.executable().entry(), 0);
    std::atomic<bool> worker_ready{false};
    std::atomic<bool> lookup_go{false};
    std::atomic<bool> lookup_started{false};
    std::atomic<bool> lookup_done{false};
    std::atomic<bool> load_done{false};
    std::uint64_t loaded_base{};
    std::uint64_t lookup_base{};
    std::exception_ptr load_failure;
    std::exception_ptr worker_failure;
    std::thread worker_thread;
    std::thread loading_thread;
    struct JoinPublicationThreads {
        std::atomic<bool>& lookup_go;
        std::atomic<bool>& release_attach;
        std::thread& loading;
        std::thread& worker;
        ~JoinPublicationThreads() {
            lookup_go.store(true, std::memory_order_release);
            release_attach.store(true, std::memory_order_release);
            if (loading.joinable()) loading.join();
            if (worker.joinable()) worker.join();
        }
    } cleanup{lookup_go, release_attach, loading_thread, worker_thread};
    worker_thread = std::thread([&] {
        try {
            bridge.initialize_worker_thread_environment(
                *worker, process.executable().base());
            worker_ready.store(true, std::memory_order_release);
            wait_until([&] { return lookup_go.load(std::memory_order_acquire); },
                       "publication fixture did not start worker lookup");
            transmute::CpuState query{};
            query.x[0] = name_address;
            lookup_started.store(true, std::memory_order_release);
            static_cast<void>(bridge.dispatch(
                {"kernel32.dll", "GetModuleHandleW", 0}, query, *worker));
            lookup_base = query.x[0];
            lookup_done.store(true, std::memory_order_release);
            bridge.cleanup_worker_thread(*worker);
        } catch (...) {
            worker_failure = std::current_exception();
            worker_ready.store(true, std::memory_order_release);
            lookup_started.store(true, std::memory_order_release);
            lookup_done.store(true, std::memory_order_release);
        }
    });
    // Worker setup also acquires the bridge publication lock. Finish it before
    // the loader deliberately holds that lock inside the paused attach hook.
    wait_until([&] { return worker_ready.load(std::memory_order_acquire); },
               "publication fixture worker did not initialize");
    loading_thread = std::thread([&] {
        try {
            loaded_base = bridge.load_guest_dll(
                process, dll_path, {root}, false, engine);
        } catch (...) {
            load_failure = std::current_exception();
        }
        load_done.store(true, std::memory_order_release);
    });
    wait_until([&] {
        return attach_entered.load(std::memory_order_acquire) ||
               load_done.load(std::memory_order_acquire);
    }, "publication fixture loader did not reach process attach");
    lookup_go.store(true, std::memory_order_release);
    wait_until([&] { return lookup_started.load(std::memory_order_acquire); },
               "publication fixture worker did not start module lookup");
    std::this_thread::sleep_for(std::chrono::milliseconds(20));
    const bool lookup_waited_for_attach = !lookup_done.load(std::memory_order_acquire);
    release_attach.store(true, std::memory_order_release);
    loading_thread.join();
    worker_thread.join();
    if (load_failure) std::rethrow_exception(load_failure);
    if (worker_failure) std::rethrow_exception(worker_failure);
    expect(attach_entered && lookup_waited_for_attach &&
               loaded_base == dll_base && lookup_base == dll_base,
           "worker observed a runtime DLL before process attach and publication");
    engine.unregister_guest_call(hook);
    std::filesystem::remove_all(root);
}
#endif

std::vector<std::uint8_t> forwarder_dll(std::uint64_t base,
                                        std::string_view name,
                                        std::string_view forwarder) {
    auto bytes = executable({0xd65f03c0});
    bytes.resize(0x600);
    put16(bytes, 0x86, 2);
    put16(bytes, 0x96, 0x2000);
    put64(bytes, 0x98 + 24, base);
    put32(bytes, 0x98 + 56, 0x3000);
    put32(bytes, 0x98 + 112, 0x2000);
    put32(bytes, 0x98 + 116, 0x200);
    constexpr std::size_t section = 0x188 + 40;
    bytes[section] = '.';
    bytes[section + 1] = 'e';
    bytes[section + 2] = 'd';
    bytes[section + 3] = 'a';
    bytes[section + 4] = 't';
    bytes[section + 5] = 'a';
    put32(bytes, section + 8, 0x200);
    put32(bytes, section + 12, 0x2000);
    put32(bytes, section + 16, 0x200);
    put32(bytes, section + 20, 0x400);
    put32(bytes, section + 36, 0x40000040);
    put32(bytes, 0x400 + 16, 1);                 // ordinal base
    put32(bytes, 0x400 + 20, 1);                 // one function
    put32(bytes, 0x400 + 24, 1);                 // one name
    put32(bytes, 0x400 + 28, 0x2040);           // function RVAs
    put32(bytes, 0x400 + 32, 0x2050);           // name RVAs
    put32(bytes, 0x400 + 36, 0x2060);           // name ordinals
    put32(bytes, 0x440, forwarder.empty() ? 0x1000 : 0x2080);
    put32(bytes, 0x450, 0x2070);
    for (std::size_t i = 0; i < name.size(); ++i) {
        bytes.at(0x470 + i) = static_cast<std::uint8_t>(name[i]);
    }
    if (!forwarder.empty()) {
        for (std::size_t i = 0; i < forwarder.size(); ++i) {
            bytes.at(0x480 + i) = static_cast<std::uint8_t>(forwarder[i]);
        }
    }
    return bytes;
}

std::vector<std::uint8_t> forwarder_import_executable(bool by_ordinal) {
    auto bytes = executable({0xd65f03c0});
    bytes.resize(0x600);
    put16(bytes, 0x86, 2);
    put32(bytes, 0x98 + 56, 0x3000);
    put32(bytes, 0x98 + 120, 0x2000);
    put32(bytes, 0x98 + 124, 40);
    constexpr std::size_t section = 0x188 + 40;
    bytes[section] = '.';
    bytes[section + 1] = 'i';
    bytes[section + 2] = 'd';
    bytes[section + 3] = 'a';
    bytes[section + 4] = 't';
    bytes[section + 5] = 'a';
    put32(bytes, section + 8, 0x200);
    put32(bytes, section + 12, 0x2000);
    put32(bytes, section + 16, 0x200);
    put32(bytes, section + 20, 0x400);
    put32(bytes, section + 36, 0xc0000040);
    put32(bytes, 0x400, 0x2040);                // original thunk
    put32(bytes, 0x40c, 0x2070);                // DLL name
    put32(bytes, 0x410, 0x2050);                // IAT
    put64(bytes, 0x440, by_ordinal ? (1ULL << 63) | 1 : 0x2080);
    put64(bytes, 0x450, by_ordinal ? (1ULL << 63) | 1 : 0x2080);
    constexpr char dll[] = "fwd_a.dll";
    for (std::size_t i = 0; i < sizeof(dll); ++i) {
        bytes[0x470 + i] = static_cast<std::uint8_t>(dll[i]);
    }
    constexpr char name[] = "Forwarded";
    for (std::size_t i = 0; i < sizeof(name); ++i) {
        bytes[0x482 + i] = static_cast<std::uint8_t>(name[i]);
    }
    return bytes;
}

#include "native_import_tests.inc"
#include "bridge_bulk_memory_tests.inc"
#include "crt_scan_bulk_tests.inc"

void test_forwarded_guest_exports() {
    auto named = forwarder_dll(0x180000000ULL, "Forwarded", "fwd_b.real");
    auto image = transmute::PeImage::parse(named);
    const auto forward = image.find_export_target("Forwarded");
    expect(forward && !forward->address && forward->forwarder == "fwd_b.real" &&
               !image.find_export("Forwarded") &&
               image.find_export_target("#1") &&
               image.find_export_target("#1")->forwarder == "fwd_b.real",
           "PE named and ordinal export forwarders were not parsed");
    auto direct = transmute::PeImage::parse(
        forwarder_dll(0x190000000ULL, "real", {}));
    expect(direct.find_export("real") == 0x190001000ULL &&
               direct.find_export_target("#1") &&
               direct.find_export_target("#1")->address == 0x190001000ULL,
           "direct named and ordinal PE exports regressed");

    auto malformed = named;
    put32(malformed, 0x440, 0x21ff);
    malformed[0x5ff] = 'x';
    expect_failure([&] { (void)transmute::PeImage::parse(malformed); },
                   "unterminated PE export forwarder");
    for (const auto invalid : {"missingperiod", "fwd_b.", ".real"}) {
        malformed = forwarder_dll(0x180000000ULL, "Forwarded", invalid);
        expect_failure([&] { (void)transmute::PeImage::parse(malformed); },
                       "invalid PE export forwarder");
    }
    for (const auto invalid : {"fwd_b.#", "fwd_b.#abc", "fwd_b.#65536"}) {
        malformed = forwarder_dll(0x180000000ULL, "Forwarded", invalid);
        expect_failure([&] { (void)transmute::PeImage::parse(malformed); },
                       "invalid PE export forwarder ordinal");
    }
    malformed = named;
    put32(malformed, 0x440, 0x3000);
    expect_failure([&] { (void)transmute::PeImage::parse(malformed); },
                   "PE export is outside mapped sections");

    const auto directory = std::filesystem::temp_directory_path() /
        ("transmute-forwarder-" + std::to_string(
            std::chrono::steady_clock::now().time_since_epoch().count()));
    std::filesystem::create_directory(directory);
    const auto app_path = directory / "fwd_app.exe";
    const auto first_path = directory / "fwd_a.dll";
    const auto second_path = directory / "fwd_b.dll";
    const auto write = [](const std::filesystem::path& path,
                          const std::vector<std::uint8_t>& bytes) {
        std::ofstream stream(path, std::ios::binary);
        expect(static_cast<bool>(stream), "cannot create forwarded PE fixture");
        stream.write(reinterpret_cast<const char*>(bytes.data()),
                     static_cast<std::streamsize>(bytes.size()));
        expect(static_cast<bool>(stream), "cannot write forwarded PE fixture");
    };
    struct Cleanup {
        std::filesystem::path directory;
        std::filesystem::path app;
        std::filesystem::path first;
        std::filesystem::path second;
        ~Cleanup() {
            std::error_code error;
            std::filesystem::remove(app, error);
            std::filesystem::remove(first, error);
            std::filesystem::remove(second, error);
            std::filesystem::remove(directory, error);
        }
    } cleanup{directory, app_path, first_path, second_path};
    write(app_path, forwarder_import_executable(false));
    write(first_path, named);
    write(second_path, forwarder_dll(0x190000000ULL, "real", {}));
    const auto check_bound = [&](std::uint64_t expected) {
        transmute::GuestProcess process(app_path);
        expect(process.modules().size() == 3 &&
                   process.attachment_order().size() == 2 &&
                   process.attachment_order()[0] == process.modules()[2].get(),
               "forwarder target was not loaded before its forwarding DLL");
        const auto& imported = process.executable().imports().front();
        std::uint64_t bound = 0;
        for (unsigned byte = 0; byte < 8; ++byte) {
            bound |= static_cast<std::uint64_t>(process.executable().read8(
                process.executable().base() + imported.iat_rva + byte)) << (byte * 8);
        }
        expect(imported.entry == 0 && bound == expected,
               "forwarded guest export did not bind to final ARM64 target");
    };
    check_bound(0x190001000ULL);
    write(first_path, forwarder_dll(0x180000000ULL,
                                    "Forwarded", "fwd_b.#1"));
    write(app_path, forwarder_import_executable(true));
    check_bound(0x190001000ULL);
    write(second_path, forwarder_dll(0x190000000ULL,
                                     "real", "fwd_a.Forwarded"));
    expect_failure([&] { (void)transmute::GuestProcess(app_path); },
                   "cyclic PE export forwarder");
    write(first_path, forwarder_dll(0x180000000ULL,
                                    "Forwarded", "kernel32.GetCurrentProcessId"));
    expect_failure([&] { (void)transmute::GuestProcess(app_path); },
                   "PE export forwarder targets host DLL");
}

#ifdef _WIN32
void test_win32_fixture(const char* path) {
    std::ifstream input(path, std::ios::binary);
    expect(static_cast<bool>(input), "cannot open ARM64 Win32 fixture");
    const std::vector<std::uint8_t> bytes{std::istreambuf_iterator<char>(input),
                                           std::istreambuf_iterator<char>()};
    auto image = transmute::PeImage::parse(bytes);
    expect(image.imports().size() == 1 &&
               image.imports().front().function == "GetCurrentProcessId",
           "ARM64 import table was not resolved");
    transmute::ReferenceEngine engine(image, transmute::dispatch_win32_import);
    expect(engine.run().exit_code == GetCurrentProcessId(),
           "ARM64 to native Win32 call returned the wrong process ID");
}
#endif

